import { test } from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder } from './cart.mjs';

test('defaults coupon and shipping to zero and returns exactly the pricing fields', () => {
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 0, totalCents: 0,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 2, unitPriceCents: 101 }]), {
    subtotalCents: 202, discountCents: 0, taxCents: 14, shippingCents: 0, totalCents: 216,
  });
});

test('taxes the discounted subtotal at 7 percent and excludes shipping', () => {
  const cart = [{ sku: 'a', quantity: 2, unitPriceCents: 500 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 20, shippingCents: 250 }), {
    subtotalCents: 1000, discountCents: 200, taxCents: 56, shippingCents: 250, totalCents: 1106,
  });
  assert.deepEqual(priceOrder(cart, { couponPercent: 20 }), {
    subtotalCents: 1000, discountCents: 200, taxCents: 56, shippingCents: 0, totalCents: 856,
  });
});

test('clamps coupons to the revised 0 to 20 percent range', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  for (const couponPercent of [20, 21, 100]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 1000, discountCents: 200, taxCents: 56, shippingCents: 0, totalCents: 856,
    });
  }
  assert.deepEqual(priceOrder(cart, { couponPercent: -5 }), {
    subtotalCents: 1000, discountCents: 0, taxCents: 70, shippingCents: 0, totalCents: 1070,
  });
});

test('rounds fractional coupons once per order and taxes after the rounded discount', () => {
  const cart = [
    { sku: 'a', quantity: 1, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 5 },
  ];
  assert.deepEqual(priceOrder(cart, { couponPercent: 10.5 }), {
    subtotalCents: 10, discountCents: 1, taxCents: 1, shippingCents: 0, totalCents: 10,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 8 }], {
    couponPercent: 6.25,
  }), {
    subtotalCents: 8, discountCents: 1, taxCents: 0, shippingCents: 0, totalCents: 7,
  });
});

test('prices normalized lines without mutating frozen cart or options', () => {
  const cart = Object.freeze([
    null,
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 101 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 50 }),
    Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
    Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 999 }),
  ]);
  const options = Object.freeze({ couponPercent: 15, shippingCents: 30 });
  const before = structuredClone({ cart, options });
  assert.deepEqual(priceOrder(cart, options), {
    subtotalCents: 555, discountCents: 83, taxCents: 33, shippingCents: 30, totalCents: 535,
  });
  assert.deepEqual({ cart, options }, before);
});

