import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { canReturn } from './returns.mjs';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { formatSummary } from './summary.mjs';

test('release exports agree across fulfillment, receipt, CSV, summary and return', () => {
  const order = Object.freeze({
    id: 'order,"one"',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 500 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 500 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 0 }),
      Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
    status: 'delivered',
    deliveredDay: 10,
  });
  const stock = Object.freeze({ a: 5, b: 2 });
  const context = Object.freeze({ nowDay: 24 });
  const before = structuredClone({ order, stock, context });
  assert.deepEqual(normalizeCart(order.cart), [
    { sku: 'a', quantity: 2, unitPriceCents: 500 },
    { sku: 'a', quantity: 1, unitPriceCents: 0 },
    { sku: 'b', quantity: 1, unitPriceCents: 0 },
  ]);
  assert.deepEqual(priceOrder(order.cart, order.options), {
    subtotalCents: 1000, discountCents: 200, taxCents: 56,
    shippingCents: 250, totalCents: 1106,
  });
  const fulfillment = fulfillOrder(order, stock);
  assert.deepEqual(fulfillment, {
    receipt: {
      orderId: 'order,"one"', subtotalCents: 1000, discountCents: 200,
      taxCents: 56, shippingCents: 250, totalCents: 1106, itemCount: 4, currency: 'USD',
    },
    stock: { a: 2, b: 1 },
  });
  assert.deepEqual(fulfillment.receipt, buildReceipt(order));
  assert.deepEqual(fulfillment.stock, reserveInventory(stock, order.cart));
  const receipts = Object.freeze([Object.freeze(fulfillment.receipt)]);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\n"order,""one""",1106,USD');
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 1106, units: 4 });
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual(returnOrder(order, context), {
    eligible: true, reason: 'eligible', refundCents: 1106, currency: 'USD',
  });
  assert.deepEqual(returnOrder(order, { nowDay: 25 }), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'USD',
  });
  assert.deepEqual({ order, stock, context }, before);
});

test('summary handles empty and zero-total receipts without mutating inputs', () => {
  assert.deepEqual(formatSummary(Object.freeze([])), { orders: 0, totalCents: 0, units: 0 });
  const receipts = Object.freeze([
    Object.freeze({ totalCents: 0, itemCount: 2 }),
    Object.freeze({ totalCents: 107, itemCount: 1 }),
    Object.freeze({ totalCents: 50, itemCount: 3 }),
  ]);
  const before = structuredClone(receipts);
  const result = formatSummary(receipts);
  assert.deepEqual(result, { orders: 3, totalCents: 157, units: 6 });
  result.units = 99;
  assert.deepEqual(formatSummary(receipts), { orders: 3, totalCents: 157, units: 6 });
  assert.deepEqual(receipts, before);
});

