    [[{ sku: 'a', quantity: 1, unitPriceCents: 5 },
      { sku: 'b', quantity: 1, unitPriceCents: 5 }], 10.5, 10],
    [[{ sku: 'a', quantity: 1, unitPriceCents: 8 }], 6.25, 7],
  ]) {
    assert.deepEqual(returnOrder({
      status: 'delivered', deliveredDay: 10, cart, options: { couponPercent },
    }, { nowDay: 10 }), {
      eligible: true, reason: 'eligible', refundCents, currency: 'USD',
    });
  }
});

test('refunds normalize carts and preserve frozen order and context inputs', () => {
  const order = Object.freeze({
    id: 'normalized', status: 'delivered', deliveredDay: 10,
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
