import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('return status must be delivered and takes precedence over date and window', () => {
  for (const status of [undefined, null, 'pending', 'shipped', 'returned', 'Delivered', ' delivered ']) {
    for (const [deliveredDay, nowDay] of [[-1, NaN], [0, 15], [0, 0]]) {
      assert.deepEqual(canReturn({ status, deliveredDay }, { nowDay }), {
        eligible: false, reason: 'status',
      });
    }
  }
});

test('return dates must be nonnegative integers and now cannot precede delivery', () => {
  for (const invalidDay of [undefined, null, -1, 0.5, '0', NaN, Infinity, -Infinity, true]) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: invalidDay }, { nowDay: 100 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: invalidDay }), {
      eligible: false, reason: 'date',
    });
  }
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 10 }, { nowDay: 9 }), {
    eligible: false, reason: 'date',
  });
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, {}), {
    eligible: false, reason: 'date',
  });
});

test('returns allow delivery day through day 14 inclusive and reject day 15', () => {
  for (const deliveredDay of [0, 10]) {
    for (const elapsed of [0, 1, 13, 14]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: true, reason: 'eligible',
      });
    }
    for (const elapsed of [15, 30]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: false, reason: 'window',
      });
    }
  }
});

test('eligibility preserves frozen inputs and returns independent result objects', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 10, extra: true });
  const context = Object.freeze({ nowDay: 24, extra: true });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  result.eligible = false;
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

