      Object.freeze({ sku: ' ', quantity: 9, unitPriceCents: 100 }),
      Object.freeze({ sku: 'bad-price', quantity: 9, unitPriceCents: -1 }),
    ]),
    options: Object.freeze({ couponPercent: 15, shippingCents: 30 }),
    status: 'delivered',
    deliveredDay: 10,
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'normalized', subtotalCents: 555, discountCents: 83,
    taxCents: 33, shippingCents: 30, totalCents: 535, itemCount: 8, currency: 'EUR',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  receipt.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
