test('receipt uses the revised coupon cap and discounted tax base excluding shipping', () => {
  assert.deepEqual(buildReceipt({
    id: 'capped',
    cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
    options: { couponPercent: 99, shippingCents: 250 },
  }), {
    orderId: 'capped', subtotalCents: 1000, discountCents: 200,
    taxCents: 56, shippingCents: 250, totalCents: 1106, itemCount: 2, currency: 'EUR',
  });
});

test('receipt preserves once-per-order discount rounding and tax after rounding', () => {
  for (const [cart, couponPercent, subtotalCents, discountCents, taxCents, totalCents] of [
    [[{ sku: 'a', quantity: 1, unitPriceCents: 5 },
      { sku: 'b', quantity: 1, unitPriceCents: 5 }], 10.5, 10, 1, 1, 10],
    [[{ sku: 'a', quantity: 1, unitPriceCents: 8 }], 6.25, 8, 1, 0, 7],
  ]) {
