});

test('CSV projects fields with CRLF separators, no trailing newline and preserves frozen receipts', () => {
  const receipts = Object.freeze([
    Object.freeze({ currency: 'EUR', totalCents: 107, orderId: 'first', itemCount: 9 }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'EUR' }),
