  assert.deepEqual(receipts, before);
});

test('CSV escapes commas, quotes, LF, CRLF and CR in every exported field', () => {
  for (const [value, escaped] of [
    ['plain', 'plain'],
    ['', ''],
    ['a,b', '"a,b"'],
    ['a"b', '"a""b"'],
    ['a\nb', '"a\nb"'],
    ['a\r\nb', '"a\r\nb"'],
    ['a\rb', '"a\rb"'],
    ['a,"b"\nc', '"a,""b""\nc"'],
  ]) {
    assert.equal(
      renderCSV([{ orderId: value, totalCents: value, currency: value }]),
      `orderId,totalCents,currency\r\n${escaped},${escaped},${escaped}`,
    );
  }
});

test('built receipts render directly to CSV', () => {
  const receipt = buildReceipt({
    id: 'order,"one"',
    cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
    options: { couponPercent: 20, shippingCents: 250 },
