import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart } from './cart.mjs';

test('drops invalid lines and accepts trimmed SKUs and zero prices', () => {
  const cart = [
    null, undefined, {}, 'a', 7,
    { sku: '', quantity: 1, unitPriceCents: 10 },
    { sku: ' \t\n', quantity: 1, unitPriceCents: 10 },
    { sku: 123, quantity: 1, unitPriceCents: 10 },
    ...[0, -1, 1.5, '2', NaN, Infinity, undefined].map(quantity => ({
      sku: 'a', quantity, unitPriceCents: 10,
    })),
    ...[-1, 1.5, '10', NaN, Infinity, undefined].map(unitPriceCents => ({
      sku: 'a', quantity: 1, unitPriceCents,
    })),
    { sku: ' free \t', quantity: 2, unitPriceCents: 0, extra: 'discard' },
  ];
  assert.deepEqual(normalizeCart(cart), [
    { sku: 'free', quantity: 2, unitPriceCents: 0 },
  ]);
});

test('merges only matching trimmed SKU and price in first appearance order', () => {
  assert.deepEqual(normalizeCart([
    { sku: ' a ', quantity: 2, unitPriceCents: 10 },
    { sku: 'b', quantity: 1, unitPriceCents: 10 },
    { sku: 'a', quantity: 3, unitPriceCents: 20 },
    { sku: 'a', quantity: 4, unitPriceCents: 10 },
    { sku: ' a\n', quantity: 5, unitPriceCents: 20 },
    { sku: 'A', quantity: 1, unitPriceCents: 10 },
  ]), [
    { sku: 'a', quantity: 6, unitPriceCents: 10 },
    { sku: 'b', quantity: 1, unitPriceCents: 10 },
    { sku: 'a', quantity: 8, unitPriceCents: 20 },
    { sku: 'A', quantity: 1, unitPriceCents: 10 },
  ]);
});

test('treats object property names as ordinary SKUs', () => {
  const skus = ['__proto__', 'constructor', 'toString'];
  const cart = skus.map(sku => ({ sku, quantity: 1, unitPriceCents: 1 }));
  assert.deepEqual(normalizeCart([...cart, ...cart]),
    skus.map(sku => ({ sku, quantity: 2, unitPriceCents: 1 })));
});

test('preserves frozen input and returns independent new objects on each call', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 10, extra: true }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 10 }),
    Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 0 }),
  ]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);
  const again = normalizeCart(cart);
  assert.deepEqual(cart, before);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], cart[0]);
  assert.notStrictEqual(result[1], cart[2]);
  result[0].quantity = 99;
  result[1].sku = 'changed';
  assert.deepEqual(cart, before);
  assert.deepEqual(again, [
    { sku: 'a', quantity: 5, unitPriceCents: 10 },
    { sku: 'b', quantity: 1, unitPriceCents: 0 },
  ]);
});

