test('fulfillment returns exactly receipt and reserved stock using revised pricing', () => {
  const order = Object.freeze({
    id: 'fulfill',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 500 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 500 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
    status: 'pending',
  });
  const stock = Object.freeze({ a: 5, untouched: 9 });
  const before = structuredClone({ order, stock });
  const result = fulfillOrder(order, stock);
  const expected = {
    receipt: {
      orderId: 'fulfill', subtotalCents: 1000, discountCents: 200,
      taxCents: 56, shippingCents: 250, totalCents: 1106, itemCount: 3, currency: 'EUR',
