test('fulfillment defaults empty order pricing and copies stock', () => {
  const stock = { a: 1 };
  const result = fulfillOrder({ id: 'empty', cart: [] }, stock);
  assert.deepEqual(result, {
    receipt: {
      orderId: 'empty', subtotalCents: 0, discountCents: 0,
