    options: { couponPercent: 10.5 },
  }, { a: 1, b: 1 }), {
    receipt: {
      orderId: 'rounding', subtotalCents: 10, discountCents: 1,
      taxCents: 1, shippingCents: 0, totalCents: 10, itemCount: 2, currency: 'EUR',
    },
    stock: { a: 0, b: 0 },
