});

test('fulfillment propagates shortage errors without changing order or stock', () => {
  const order = {
    id: 'short',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 10 },
      { sku: 'b', quantity: 2, unitPriceCents: 20 },
    ],
    options: { couponPercent: 15, shippingCents: 10 },
  };
  const stock = { a: 5, b: 1 };
  const before = structuredClone({ order, stock });
  assert.throws(() => fulfillOrder(order, stock), {
    name: 'RangeError', message: 'insufficient stock',
