});

test('absent, inherited and zero-count SKUs have no available stock', () => {
  for (const [stock, sku] of [
    [{}, 'missing'], [{ a: 0 }, 'a'], [{}, '__proto__'],
    [{}, 'constructor'], [{}, 'toString'], [Object.create({ a: 5 }), 'a'],
