  const order = Object.freeze({
    id: 'normalized',
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 50 }),
