  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'normalized', subtotalCents: 555, discountCents: 83,
    taxCents: 33, shippingCents: 30, totalCents: 535, itemCount: 8, currency: 'EUR',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  receipt.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('receipt uses the revised coupon cap and discounted tax base excluding shipping', () => {
  assert.deepEqual(buildReceipt({
    id: 'capped',
    cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
    options: { couponPercent: 99, shippingCents: 250 },
  }), {
    orderId: 'capped', subtotalCents: 1000, discountCents: 200,
    taxCents: 56, shippingCents: 250, totalCents: 1106, itemCount: 2, currency: 'EUR',
  });
});

test('receipt preserves once-per-order discount rounding and tax after rounding', () => {
  for (const [cart, couponPercent, subtotalCents, discountCents, taxCents, totalCents] of [
    [[{ sku: 'a', quantity: 1, unitPriceCents: 5 },
      { sku: 'b', quantity: 1, unitPriceCents: 5 }], 10.5, 10, 1, 1, 10],
    [[{ sku: 'a', quantity: 1, unitPriceCents: 8 }], 6.25, 8, 1, 0, 7],
  ]) {
    const receipt = buildReceipt({ id: 'rounding', cart, options: { couponPercent } });
    assert.deepEqual(
      [receipt.subtotalCents, receipt.discountCents, receipt.taxCents, receipt.totalCents],
      [subtotalCents, discountCents, taxCents, totalCents],
    );
  }
});

test('CSV returns only the header for empty input', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV projects fields with CRLF separators, no trailing newline and preserves frozen receipts', () => {
  const receipts = Object.freeze([
    Object.freeze({ currency: 'EUR', totalCents: 107, orderId: 'first', itemCount: 9 }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'EUR' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\nfirst,107,EUR\r\n0,0,EUR');
  assert.deepEqual(receipts, before);
});

test('CSV escapes commas, quotes, LF, CRLF and CR in every exported field', () => {
  for (const [value, escaped] of [
    ['plain', 'plain'],
    ['', ''],
    ['a,b', '"a,b"'],
    ['a"b', '"a""b"'],
    ['a\nb', '"a\nb"'],
    ['a\r\nb', '"a\r\nb"'],
    ['a\rb', '"a\rb"'],
    ['a,"b"\nc', '"a,""b""\nc"'],
  ]) {
    assert.equal(
      renderCSV([{ orderId: value, totalCents: value, currency: value }]),
      `orderId,totalCents,currency\r\n${escaped},${escaped},${escaped}`,
    );
  }
});

test('built receipts render directly to CSV', () => {
  const receipt = buildReceipt({
    id: 'order,"one"',
    cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
    options: { couponPercent: 20, shippingCents: 250 },
  });
  assert.equal(renderCSV([receipt]), 'orderId,totalCents,currency\r\n"order,""one""",1106,EUR');
});

