import { test } from 'node:test';
import assert from 'node:assert/strict';
import { returnOrder } from './pipeline.mjs';

test('eligible returns refund the shared total with capped discount, tax and shipping', () => {
  assert.deepEqual(returnOrder({
    id: 'return', status: 'delivered', deliveredDay: 10,
    cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
    options: { couponPercent: 99, shippingCents: 250 }, extra: true,
  }, { nowDay: 26 }), {
    eligible: true, reason: 'eligible', refundCents: 1106, currency: 'EUR',
  });
});

test('ineligible returns report each policy reason and skip pricing', () => {
  for (const [status, deliveredDay, nowDay, reason] of [
    ['pending', -1, -1, 'status'],
    ['delivered', 10, 9, 'date'],
    ['delivered', 0, 17, 'window'],
  ]) {
    const order = Object.freeze({
      status, deliveredDay,
      get cart() { throw new Error('ineligible order must not be priced'); },
      get options() { throw new Error('ineligible order must not be priced'); },
    });
    assert.deepEqual(returnOrder(order, Object.freeze({ nowDay })), {
      eligible: false, reason, refundCents: 0, currency: 'EUR',
    });
  }
});

test('refunds stay eligible on days 14, 15 and 16 and reject day 17 in EUR', () => {
  for (const deliveredDay of [0, 10]) {
    const order = Object.freeze({
      status: 'delivered', deliveredDay,
      cart: Object.freeze([Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 })]),
    });
    for (const elapsed of [14, 15, 16, 17]) {
      const eligible = elapsed <= 16;
      assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: deliveredDay + elapsed })), {
        eligible, reason: eligible ? 'eligible' : 'window',
        refundCents: eligible ? 107 : 0, currency: 'EUR',
      });
    }
  }
});

test('eligible refunds honor pricing defaults, zero totals and shipping-only totals', () => {
  for (const [cart, options, refundCents] of [
    [[], undefined, 0],
    [[{ sku: 'a', quantity: 2, unitPriceCents: 101 }], undefined, 216],
    [[], { shippingCents: 250 }, 250],
  ]) {
    assert.deepEqual(returnOrder({ status: 'delivered', deliveredDay: 0, cart, options }, { nowDay: 0 }), {
      eligible: true, reason: 'eligible', refundCents, currency: 'EUR',
    });
  }
});

test('refunds round discount once per order and calculate tax after rounding', () => {
  for (const [cart, couponPercent, refundCents] of [
    [[{ sku: 'a', quantity: 1, unitPriceCents: 5 },
      { sku: 'b', quantity: 1, unitPriceCents: 5 }], 10.5, 10],
    [[{ sku: 'a', quantity: 1, unitPriceCents: 8 }], 6.25, 7],
  ]) {
    assert.deepEqual(returnOrder({
      status: 'delivered', deliveredDay: 10, cart, options: { couponPercent },
    }, { nowDay: 10 }), {
      eligible: true, reason: 'eligible', refundCents, currency: 'EUR',
    });
  }
});

test('refunds normalize carts and preserve frozen order and context inputs', () => {
  const order = Object.freeze({
    id: 'normalized', status: 'delivered', deliveredDay: 10,
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 50 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 15, shippingCents: 30 }),
  });
  const context = Object.freeze({ nowDay: 26 });
  const before = structuredClone({ order, context });
  const expected = { eligible: true, reason: 'eligible', refundCents: 535, currency: 'EUR' };
  const result = returnOrder(order, context);
  assert.deepEqual(result, expected);
  result.refundCents = 0;
  assert.deepEqual(returnOrder(order, context), expected);
  assert.deepEqual({ order, context }, before);
});

returns.mjs.text:
// Return eligibility policy.

export function canReturn(order, { nowDay } = {}) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  const { deliveredDay } = order;
  if (
    !Number.isInteger(deliveredDay) || deliveredDay < 0 ||
    !Number.isInteger(nowDay) || nowDay < 0 ||
    nowDay < deliveredDay
  ) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - deliveredDay > 16) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

