import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';

test('receipt defaults to zero totals and USD for empty or entirely invalid carts', () => {
  for (const cart of [[], [null, { sku: ' ', quantity: 1, unitPriceCents: 100 }]]) {
    assert.deepEqual(buildReceipt({ id: 'empty', cart }), {
      orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
      shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'USD',
    });
  }
});

test('receipt counts normalized units and returns independent exact-shape results from frozen inputs', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 });
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      line, line,
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 196 }),
      Object.freeze({ sku: 'free', quantity: 3, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'bad', quantity: '2', unitPriceCents: 1000 }),
      Object.freeze({ sku: 'bad', quantity: 1, unitPriceCents: -1 }),
    ]),
    options: Object.freeze({ couponPercent: 25, shippingCents: 25 }),
    status: 'delivered', deliveredDay: 12, extra: 'ignored',
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 600, discountCents: 120, taxCents: 34,
    shippingCents: 25, totalCents: 539, itemCount: 8, currency: 'USD',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.totalCents = 0;
  receipt.itemCount = 99;
  assert.deepEqual(order, before);
  assert.deepEqual(buildReceipt(order), expected);
});

test('receipt delegates coupon limits and fractional rounding to revised pricing', () => {
  for (const [couponPercent, discountCents, taxCents, totalCents] of [
    [-5, 0, 7, 107], [20, 20, 6, 86], [25, 20, 6, 86], [12.5, 13, 6, 93],
  ]) {
    assert.deepEqual(buildReceipt({
      id: 0, cart: [{ sku: 'a', quantity: 1, unitPriceCents: 100 }],
      options: { couponPercent },
    }), {
      orderId: 0, subtotalCents: 100, discountCents, taxCents,
      shippingCents: 0, totalCents, itemCount: 1, currency: 'USD',
    });
  }
});

test('receipt rounds discount and tax once per order', () => {
  assert.deepEqual(buildReceipt({
    id: 'discount', cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 3 })),
    options: { couponPercent: 20 },
  }), {
    orderId: 'discount', subtotalCents: 9, discountCents: 2, taxCents: 0,
    shippingCents: 0, totalCents: 7, itemCount: 3, currency: 'USD',
  });
  assert.deepEqual(buildReceipt({
    id: 'tax', cart: ['a', 'b'].map(sku => ({ sku, quantity: 1, unitPriceCents: 25 })),
  }), {
    orderId: 'tax', subtotalCents: 50, discountCents: 0, taxCents: 4,
    shippingCents: 0, totalCents: 54, itemCount: 2, currency: 'USD',
  });
});

test('receipt excludes shipping from tax for a zero-price cart', () => {
  assert.deepEqual(buildReceipt({
    id: 'free', cart: [{ sku: 'free', quantity: 2, unitPriceCents: 0 }],
    options: { shippingCents: 100 },
  }), {
    orderId: 'free', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 100, totalCents: 100, itemCount: 2, currency: 'USD',
  });
});

test('empty CSV contains only the header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves row order, zero values and plain fields with LF separators', () => {
  assert.equal(renderCSV([
    { orderId: 'z', totalCents: 107, currency: 'USD', itemCount: 1 },
    { orderId: 0, totalCents: 0, currency: 'USD' },
    { orderId: ' a ', totalCents: 216, currency: 'USD' },
  ]), 'orderId,totalCents,currency\nz,107,USD\n0,0,USD\n a ,216,USD');
});

test('CSV escapes commas, quotes, LF and CR in every selected field', () => {
  for (const [value, escaped] of [
    ['a,b', '"a,b"'], ['a"b"', '"a""b"""'],
    ['a\nb', '"a\nb"'], ['a\rb', '"a\rb"'], ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\nc', '"a,""b""\nc"'], ['', ''],
  ]) {
    for (const key of ['orderId', 'totalCents', 'currency']) {
      const receipt = { orderId: 'id', totalCents: 0, currency: 'USD', [key]: value };
      const fields = { orderId: 'id', totalCents: '0', currency: 'USD', [key]: escaped };
      assert.equal(renderCSV([receipt]),
        `orderId,totalCents,currency\n${fields.orderId},${fields.totalCents},${fields.currency}`);
    }
  }
});

test('CSV renders built receipts and repeated frozen references without mutation', () => {
  const receipt = Object.freeze(buildReceipt({
    id: 'order,"one"', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }],
    options: { couponPercent: 20, shippingCents: 100 },
  }));
  const receipts = Object.freeze([receipt, receipt]);
  const before = structuredClone(receipts);
  const expected = 'orderId,totalCents,currency\n"order,""one""",956,USD\n"order,""one""",956,USD';
  assert.equal(renderCSV(receipts), expected);
  assert.deepEqual(receipts, before);
  assert.equal(renderCSV(receipts), expected);
});

