    Object.freeze({ sku: 'missing', quantity: '1', unitPriceCents: 10 }),
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 10 }),
  ]);
  assert.deepEqual(reserveInventory(stock, cart), { a: 2, b: 0, untouched: 9 });
  assert.deepEqual(stock, { a: 8, b: 2, untouched: 9 });
});

test('shortage across prices fails atomically even after an available SKU', () => {
