test('receipt counts normalized units and returns independent exact-shape results from frozen inputs', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 });
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      line, line,
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 196 }),
      Object.freeze({ sku: 'free', quantity: 3, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'bad', quantity: '2', unitPriceCents: 1000 }),
      Object.freeze({ sku: 'bad', quantity: 1, unitPriceCents: -1 }),
    ]),
    options: Object.freeze({ couponPercent: 25, shippingCents: 25 }),
    status: 'delivered', deliveredDay: 12, extra: 'ignored',
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 600, discountCents: 120, taxCents: 34,
    shippingCents: 25, totalCents: 539, itemCount: 8, currency: 'USD',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.totalCents = 0;
  receipt.itemCount = 99;
  assert.deepEqual(order, before);
  assert.deepEqual(buildReceipt(order), expected);
