    id: 'free', cart: [{ sku: 'free', quantity: 2, unitPriceCents: 0 }],
    options: { shippingCents: 100 },
  }), {
    orderId: 'free', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 100, totalCents: 100, itemCount: 2, currency: 'USD',
  });
});

test('empty CSV contains only the header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves row order, zero values and plain fields with LF separators', () => {
  assert.equal(renderCSV([
    { orderId: 'z', totalCents: 107, currency: 'USD', itemCount: 1 },
    { orderId: 0, totalCents: 0, currency: 'USD' },
    { orderId: ' a ', totalCents: 216, currency: 'USD' },
  ]), 'orderId,totalCents,currency\nz,107,USD\n0,0,USD\n a ,216,USD');
});

test('CSV escapes commas, quotes, LF and CR in every selected field', () => {
  for (const [value, escaped] of [
    ['a,b', '"a,b"'], ['a"b"', '"a""b"""'],
    ['a\nb', '"a\nb"'], ['a\rb', '"a\rb"'], ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\nc', '"a,""b""\nc"'], ['', ''],
  ]) {
    for (const key of ['orderId', 'totalCents', 'currency']) {
      const receipt = { orderId: 'id', totalCents: 0, currency: 'USD', [key]: value };
      const fields = { orderId: 'id', totalCents: '0', currency: 'USD', [key]: escaped };
      assert.equal(renderCSV([receipt]),
        `orderId,totalCents,currency\n${fields.orderId},${fields.totalCents},${fields.currency}`);
    }
  }
});

test('CSV renders built receipts and repeated frozen references without mutation', () => {
  const receipt = Object.freeze(buildReceipt({
    id: 'order,"one"', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }],
    options: { couponPercent: 20, shippingCents: 100 },
  }));
  const receipts = Object.freeze([receipt, receipt]);
  const before = structuredClone(receipts);
  const expected = 'orderId,totalCents,currency\n"order,""one""",956,USD\n"order,""one""",956,USD';
  assert.equal(renderCSV(receipts), expected);
  assert.deepEqual(receipts, before);
  assert.equal(renderCSV(receipts), expected);
});

