import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('return eligibility requires exact delivered status before checking dates', () => {
  for (const status of [undefined, null, 'pending', 'Delivered', 'delivered ', 1]) {
    assert.deepEqual(canReturn({ status, deliveredDay: -1 }, { nowDay: -2 }),
      { eligible: false, reason: 'status' });
    assert.deepEqual(canReturn({ status, deliveredDay: 0 }, { nowDay: 100 }),
      { eligible: false, reason: 'status' });
  }
});

test('return dates must be nonnegative integers without coercion', () => {
  const invalidDates = [undefined, null, -1, 1.5, '0', false, NaN, Infinity, -Infinity];
  for (const value of invalidDates) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: value }, { nowDay: 100 }),
      { eligible: false, reason: 'date' });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: value }),
      { eligible: false, reason: 'date' });
  }
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 5 }, { nowDay: 4 }),
    { eligible: false, reason: 'date' });
});

test('delivery day and day 14 are eligible; day 15 and later are outside the window', () => {
  for (const deliveredDay of [0, 20]) {
    const order = { status: 'delivered', deliveredDay };
    for (const elapsed of [0, 1, 13, 14]) {
      assert.deepEqual(canReturn(order, { nowDay: deliveredDay + elapsed }),
        { eligible: true, reason: 'eligible' });
    }
    for (const elapsed of [15, 30, 100]) {
      assert.deepEqual(canReturn(order, { nowDay: deliveredDay + elapsed }),
        { eligible: false, reason: 'window' });
    }
  }
});

test('return eligibility leaves frozen inputs unchanged and returns independent objects', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 7 });
  const context = Object.freeze({ nowDay: 21 });
  const first = canReturn(order, context);
  const second = canReturn(order, context);
  assert.notStrictEqual(first, second);
  first.eligible = false;
  assert.deepEqual(second, { eligible: true, reason: 'eligible' });
  assert.deepEqual(order, { status: 'delivered', deliveredDay: 7 });
  assert.deepEqual(context, { nowDay: 21 });
});

