import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';

test('drops invalid lines without numeric or string coercion', () => {
  const valid = { sku: 'a', quantity: 1, unitPriceCents: 0 };
  const invalid = [null, undefined, {}, 1, false, 'a', [],
    ...['', ' \t\n ', null, undefined, 12, new String('a')].map(sku => ({ ...valid, sku })),
    ...[0, -1, 1.5, NaN, Infinity, '2', true, null, undefined].map(quantity => ({ ...valid, quantity })),
    ...[-1, 0.5, NaN, Infinity, '0', false, null, undefined].map(unitPriceCents => ({ ...valid, unitPriceCents })),
  ];

  assert.deepEqual(normalizeCart([...invalid, valid]), [valid]);
  assert.deepEqual(normalizeCart(invalid), []);
});

test('trims sku and merges matching prices in global first appearance order', () => {
  const cart = [
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 1, unitPriceCents: 200 },
    { sku: 'a', quantity: 3, unitPriceCents: 101 },
    { sku: '\ta\n', quantity: 4, unitPriceCents: 100 },
    { sku: ' b ', quantity: 5, unitPriceCents: 200 },
    { sku: 'a', quantity: 6, unitPriceCents: 101 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ];

  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 6, unitPriceCents: 100 },
    { sku: 'b', quantity: 6, unitPriceCents: 200 },
    { sku: 'a', quantity: 9, unitPriceCents: 101 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ]);
});

test('keeps arbitrary sku strings distinct and accepts zero prices', () => {
  const skus = ['__proto__', 'constructor', 'toString', 'a:1', 'a', '123', 'x\u0000y'];
  const cart = skus.map(sku => ({ sku, quantity: 1, unitPriceCents: 0 }));
  assert.deepEqual(normalizeCart([...cart, ...cart]),
    skus.map(sku => ({ sku, quantity: 2, unitPriceCents: 0 })));
});

test('does not mutate frozen inputs, including repeated references and extra fields', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101, extra: { note: 'keep' } });
  const cart = Object.freeze([line, line, null]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);

  assert.deepEqual(result, [{ sku: 'a', quantity: 4, unitPriceCents: 101 }]);
  assert.deepEqual(cart, before);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], line);

  result[0].sku = 'changed';
  result[0].quantity = 99;
  assert.deepEqual(cart, before);
  assert.deepEqual(normalizeCart(cart), [{ sku: 'a', quantity: 4, unitPriceCents: 101 }]);
});

test('creates fresh independent objects even when no merging is needed', () => {
  const cart = [
    { sku: 'a', quantity: 1, unitPriceCents: 100, ignored: true },
    { sku: 'b', quantity: 2, unitPriceCents: 100 },
  ];
  const result = normalizeCart(cart);
  for (let i = 0; i < cart.length; i++) {
    assert.notStrictEqual(result[i], cart[i]);
    assert.deepEqual(Object.keys(result[i]), ['sku', 'quantity', 'unitPriceCents']);
  }
  result[0].quantity = 8;
  assert.equal(result[1].quantity, 2);
  assert.equal(cart[0].quantity, 1);
});

test('ignores holes in sparse carts', () => {
  const cart = new Array(3);
  cart[1] = { sku: ' a ', quantity: 1, unitPriceCents: 0 };
  assert.deepEqual(normalizeCart(cart), [{ sku: 'a', quantity: 1, unitPriceCents: 0 }]);
  assert.equal(0 in cart, false);
  assert.equal(2 in cart, false);
});

test('priceOrder defaults coupon and shipping to zero and returns exact totals', () => {
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 0, totalCents: 0,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 2, unitPriceCents: 101 }]), {
    subtotalCents: 202, discountCents: 0, taxCents: 14, shippingCents: 0, totalCents: 216,
  });
});

test('priceOrder applies 7% tax after discount and excludes shipping from tax', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 20, shippingCents: 100 }), {
    subtotalCents: 1000, discountCents: 200, taxCents: 56, shippingCents: 100, totalCents: 956,
  });
  assert.deepEqual(priceOrder([], { couponPercent: 20, shippingCents: 100 }), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 100, totalCents: 100,
  });
});

test('priceOrder clamps coupons to the revised range and accepts fractional percentages', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 100 }];
  for (const couponPercent of [-5, 0]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 100, discountCents: 0, taxCents: 7, shippingCents: 0, totalCents: 107,
    });
  }
  for (const couponPercent of [20, 25]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 100, discountCents: 20, taxCents: 6, shippingCents: 0, totalCents: 86,
    });
  }
  assert.deepEqual(priceOrder(cart, { couponPercent: 12.5 }), {
    subtotalCents: 100, discountCents: 13, taxCents: 6, shippingCents: 0, totalCents: 93,
  });
});

test('priceOrder rounds discount and tax once per order', () => {
  const cart = ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 3 }));
  assert.deepEqual(priceOrder(cart, { couponPercent: 20 }), {
    subtotalCents: 9, discountCents: 2, taxCents: 0, shippingCents: 0, totalCents: 7,
  });
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 25 },
    { sku: 'b', quantity: 1, unitPriceCents: 25 },
  ]), {
    subtotalCents: 50, discountCents: 0, taxCents: 4, shippingCents: 0, totalCents: 54,
  });
});

test('priceOrder uses normalized valid lines and does not mutate cart or options', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 100 });
  const cart = Object.freeze([
    line, line, Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 150 }),
    null, Object.freeze({ sku: 'invalid', quantity: '2', unitPriceCents: 1000 }),
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 1000 }),
  ]);
  const options = Object.freeze({ couponPercent: 20, shippingCents: 25, extra: 'ignored' });
  const before = structuredClone({ cart, options });
  const expected = {
    subtotalCents: 600, discountCents: 120, taxCents: 34, shippingCents: 25, totalCents: 539,
  };
  const result = priceOrder(cart, options);
  assert.deepEqual(result, expected);
  assert.deepEqual({ cart, options }, before);
  result.totalCents = 0;
  assert.deepEqual(priceOrder(cart, options), expected);
});

