test('reservation normalizes lines and combines quantities across prices', () => {
  const stock = Object.freeze({ a: 8, b: 2, untouched: 9 });
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 200 }),
    Object.freeze({ sku: 'b', quantity: 2, unitPriceCents: 0 }),
    null,
    Object.freeze({ sku: 'missing', quantity: 0, unitPriceCents: 10 }),
    Object.freeze({ sku: 'missing', quantity: 1, unitPriceCents: -1 }),
    Object.freeze({ sku: 'missing', quantity: '1', unitPriceCents: 10 }),
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 10 }),
  ]);
  assert.deepEqual(reserveInventory(stock, cart), { a: 2, b: 0, untouched: 9 });
  assert.deepEqual(stock, { a: 8, b: 2, untouched: 9 });
});

test('shortage across prices fails atomically even after an available SKU', () => {
  const stock = { a: 4, b: 3 };
  const cart = [
    { sku: 'a', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 2, unitPriceCents: 200 },
  ];
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
});

test('missing, zero, case-mismatched and inherited SKUs have no available stock', () => {
  for (const [stock, sku] of [
    [{}, 'missing'], [{ a: 0 }, 'a'], [{ a: 5 }, 'A'],
    [{}, 'constructor'], [{}, 'toString'], [{}, '__proto__'],
    [Object.create({ inherited: 10 }), 'inherited'],
  ]) {
    assert.throws(() => reserveInventory(stock, [{ sku, quantity: 1, unitPriceCents: 1 }]), {
      name: 'RangeError', message: 'insufficient stock',
    });
  }
});

test('special SKU keys reserve as ordinary own properties', () => {
  const stock = Object.freeze(JSON.parse('{"__proto__":4,"constructor":3,"toString":2}'));
  const cart = Object.keys(stock).map(sku => ({ sku, quantity: 2, unitPriceCents: 1 }));
  const result = reserveInventory(stock, cart);
  assert.deepEqual(result, JSON.parse('{"__proto__":2,"constructor":1,"toString":0}'));
  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.deepEqual(stock, JSON.parse('{"__proto__":4,"constructor":3,"toString":2}'));
});

test('empty and invalid carts return independent stock copies', () => {
  const stock = Object.freeze({ a: 3 });
  for (const cart of [Object.freeze([]), Object.freeze([null, {}])]) {
    const first = reserveInventory(stock, cart);
    const second = reserveInventory(stock, cart);
    assert.deepEqual(first, { a: 3 });
    assert.notStrictEqual(first, stock);
    assert.notStrictEqual(first, second);
    first.a = 0;
    assert.deepEqual(second, { a: 3 });
    assert.deepEqual(stock, { a: 3 });
  }
});

test('repeated line references are counted without changing the line', () => {
  const line = Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 10 });
  const stock = Object.freeze({ a: 5 });
  assert.deepEqual(reserveInventory(stock, Object.freeze([line, line])), { a: 1 });
  assert.equal(line.quantity, 2);
});

pipeline.mjs.text:
// Fulfillment and return compositions.
import { buildReceipt } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { priceOrder } from './cart.mjs';
import { canReturn } from './returns.mjs';

export function fulfillOrder(order, stock) {
  return {
    receipt: buildReceipt(order),
    stock: reserveInventory(stock, order.cart),
  };
}

export function returnOrder(order, context) {
  const eligibility = canReturn(order, context);
  return {
    ...eligibility,
    refundCents: eligibility.eligible ? priceOrder(order.cart, order.options).totalCents : 0,
    currency: 'EUR',
  };
}

