// Cart normalization and price calculation. Implement the requested exports here.

export function normalizeCart(cart) {
  const normalized = [];
  const bySku = new Map();

  for (const line of cart) {
    if (line == null || typeof line.sku !== 'string' ||
        !Number.isInteger(line.quantity) || line.quantity <= 0 ||
        !Number.isInteger(line.unitPriceCents) || line.unitPriceCents < 0) {
      continue;
    }

    const sku = line.sku.trim();
    if (!sku) continue;

    let byPrice = bySku.get(sku);
    if (!byPrice) {
      byPrice = new Map();
      bySku.set(sku, byPrice);
    }

    const existing = byPrice.get(line.unitPriceCents);
    if (existing) {
      existing.quantity += line.quantity;
    } else {
      const item = { sku, quantity: line.quantity, unitPriceCents: line.unitPriceCents };
      byPrice.set(line.unitPriceCents, item);
      normalized.push(item);
    }
  }

  return normalized;
}

export function priceOrder(cart, options = {}) {
  const subtotalCents = normalizeCart(cart).reduce(
    (sum, line) => sum + line.quantity * line.unitPriceCents, 0);
  const couponPercent = Math.min(20, Math.max(0, options.couponPercent ?? 0));
  const discountCents = Math.round(subtotalCents * couponPercent / 100);
  const taxCents = Math.round((subtotalCents - discountCents) * 7 / 100);
  const shippingCents = options.shippingCents ?? 0;
  const totalCents = subtotalCents - discountCents + taxCents + shippingCents;

  return { subtotalCents, discountCents, taxCents, shippingCents, totalCents };
}

