import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder } from './pipeline.mjs';

test('fulfillment composes normalized reservation with revised receipt pricing', () => {
  const order = Object.freeze({
    id: 'order-1', status: 'placed', deliveredDay: 0,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 201 }),
      Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 0 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 50 }),
  });
  const stock = Object.freeze({ a: 5, b: 1, spare: 6 });
  const before = structuredClone({ order, stock });
  const first = fulfillOrder(order, stock);
  const second = fulfillOrder(order, stock);
  assert.deepEqual(first, {
    receipt: {
      orderId: 'order-1', subtotalCents: 403, discountCents: 81,
      taxCents: 23, shippingCents: 50, totalCents: 395,
      itemCount: 4, currency: 'EUR',
    },
    stock: { a: 2, b: 0, spare: 6 },
  });
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first.receipt, second.receipt);
  assert.notStrictEqual(first.stock, second.stock);
  assert.notStrictEqual(first.stock, stock);
  first.stock.a = 99;
  first.receipt.totalCents = 0;
  assert.equal(second.stock.a, 2);
  assert.equal(second.receipt.totalCents, 395);
  assert.deepEqual({ order, stock }, before);
});

test('empty fulfillment supports default pricing options and returns fresh stock', () => {
  const order = Object.freeze({ id: 'empty', cart: Object.freeze([]) });
  const stock = Object.freeze({ a: 5 });
  const result = fulfillOrder(order, stock);
