import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { canReturn } from './returns.mjs';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { formatSummary } from './summary.mjs';

test('integrated release fulfills, reports and refunds the same normalized order', () => {
  const order = Object.freeze({
    id: 'order,"one"', status: 'delivered', deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 0 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 201 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
      null,
      Object.freeze({ sku: 'bad', quantity: '1', unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 50 }),
  });
  const stock = Object.freeze({ a: 5, b: 1, spare: 8 });
  const before = structuredClone({ order, stock });
  assert.deepEqual(normalizeCart(order.cart), [
    { sku: 'a', quantity: 3, unitPriceCents: 101 },
    { sku: 'b', quantity: 1, unitPriceCents: 0 },
    { sku: 'a', quantity: 1, unitPriceCents: 201 },
  ]);
  assert.deepEqual(priceOrder(order.cart, order.options), {
    subtotalCents: 504, discountCents: 101, taxCents: 28,
    shippingCents: 50, totalCents: 481,
  });
  const fulfilled = fulfillOrder(order, stock);
  assert.deepEqual(fulfilled, {
    receipt: {
      orderId: 'order,"one"', subtotalCents: 504, discountCents: 101,
      taxCents: 28, shippingCents: 50, totalCents: 481, itemCount: 5, currency: 'EUR',
    },
    stock: { a: 1, b: 0, spare: 8 },
  });
  assert.deepEqual(fulfilled.receipt, buildReceipt(order));
  assert.deepEqual(fulfilled.stock, reserveInventory(stock, order.cart));
  assert.deepEqual(formatSummary([fulfilled.receipt]), { orders: 1, totalCents: 481, units: 5 });
  assert.equal(renderCSV([fulfilled.receipt]),
    'orderId,totalCents,currency\r\n"order,""one""",481,EUR');
  for (const elapsed of [14, 15, 16]) {
    const context = { nowDay: order.deliveredDay + elapsed };
    assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
    assert.deepEqual(returnOrder(order, context), {
      eligible: true, reason: 'eligible', refundCents: fulfilled.receipt.totalCents, currency: 'EUR',
    });
  }
  assert.deepEqual(canReturn(order, { nowDay: 27 }), { eligible: false, reason: 'window' });
  assert.deepEqual(returnOrder(order, { nowDay: 27 }), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'EUR',
  });
  assert.throws(() => fulfillOrder(order, fulfilled.stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual(fulfilled.stock, { a: 1, b: 0, spare: 8 });
  assert.deepEqual({ order, stock }, before);
});

