import { test } from 'node:test';
import assert from 'node:assert/strict';
import { returnOrder } from './pipeline.mjs';

test('eligible refund uses normalized cart, capped discount, discounted tax and shipping', () => {
  const order = {
    status: 'delivered', deliveredDay: 10,
    cart: [
      { sku: ' a ', quantity: 2, unitPriceCents: 101 },
      { sku: 'a', quantity: 3, unitPriceCents: 101 },
      { sku: 'bad', quantity: -1, unitPriceCents: 10000 },
      null,
    ],
    options: { couponPercent: 50, shippingCents: 37 },
  };
  // Subtotal 505, discount 101, tax round(404 * .07) = 28, plus shipping 37.
  assert.deepEqual(returnOrder(order, { nowDay: 26 }),
    { eligible: true, reason: 'eligible', refundCents: 469, currency: 'EUR' });
});

test('refund pricing supports defaults, empty carts and rounding once per order', () => {
  const order = { status: 'delivered', deliveredDay: 0,
    cart: [{ sku: 'a', quantity: 1, unitPriceCents: 101 }] };
  assert.deepEqual(returnOrder(order, { nowDay: 0 }),
    { eligible: true, reason: 'eligible', refundCents: 108, currency: 'EUR' });
  assert.deepEqual(returnOrder({ ...order, cart: [] }, { nowDay: 0 }),
    { eligible: true, reason: 'eligible', refundCents: 0, currency: 'EUR' });
  const smallOrder = { ...order,
    cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 1 })),
    options: { couponPercent: 20, shippingCents: 5 } };
  assert.deepEqual(returnOrder(smallOrder, { nowDay: 16 }),
    { eligible: true, reason: 'eligible', refundCents: 7, currency: 'EUR' });
});

test('ineligible returns retain the reason, refund zero and do not read pricing inputs', () => {
  const cases = [
    { status: 'pending', deliveredDay: -1, nowDay: -1, reason: 'status' },
    { status: 'delivered', deliveredDay: 10, nowDay: 9, reason: 'date' },
    { status: 'delivered', deliveredDay: 10, nowDay: 27, reason: 'window' },
  ];
  for (const { status, deliveredDay, nowDay, reason } of cases) {
    const order = {
      status, deliveredDay,
      get cart() { throw new Error('ineligible return must not read cart'); },
      get options() { throw new Error('ineligible return must not read options'); },
    };
    assert.deepEqual(returnOrder(order, { nowDay }),
      { eligible: false, reason, refundCents: 0, currency: 'EUR' });
  }
});

test('returnOrder preserves frozen inputs and gives each call a fresh exact-shape result', () => {
  const order = Object.freeze({
    id: 'order-1', status: 'delivered', deliveredDay: 2,
    cart: Object.freeze([Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 })]),
    options: Object.freeze({ couponPercent: 10, shippingCents: 5 }),
  });
  const context = Object.freeze({ nowDay: 18 });
  const before = structuredClone({ order, context });
  const first = returnOrder(order, context);
  const second = returnOrder(order, context);
  assert.notStrictEqual(first, second);
  assert.deepEqual(first,
    { eligible: true, reason: 'eligible', refundCents: 200, currency: 'EUR' });
  first.refundCents = -1;
  assert.equal(second.refundCents, 200);
  assert.deepEqual({ order, context }, before);
});

