  assert.deepEqual(buildReceipt({
    id: 'discount', cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 3 })),
    options: { couponPercent: 20 },
  }), {
    orderId: 'discount', subtotalCents: 9, discountCents: 2, taxCents: 0,
    shippingCents: 0, totalCents: 7, itemCount: 3, currency: 'EUR',
  });
  assert.deepEqual(buildReceipt({
    id: 'tax', cart: ['a', 'b'].map(sku => ({ sku, quantity: 1, unitPriceCents: 25 })),
  }), {
    orderId: 'tax', subtotalCents: 50, discountCents: 0, taxCents: 4,
    shippingCents: 0, totalCents: 54, itemCount: 2, currency: 'EUR',
  });
