import { test } from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder } from './cart.mjs';

const cartFor = cents => [{ sku: 'item', quantity: 1, unitPriceCents: cents }];

test('defaults coupon and shipping to zero with an exact result shape', () => {
  const expected = {
    subtotalCents: 101, discountCents: 0, taxCents: 11, shippingCents: 0, totalCents: 112,
  };
  assert.deepEqual(priceOrder(cartFor(101)), expected);
  assert.deepEqual(priceOrder(cartFor(101), {}), expected);
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 0, totalCents: 0,
  });
});

test('taxes the discounted subtotal at 11 percent and excludes shipping', () => {
  assert.deepEqual(priceOrder(cartFor(10000), { couponPercent: 20, shippingCents: 999 }), {
    subtotalCents: 10000, discountCents: 2000, taxCents: 880,
    shippingCents: 999, totalCents: 9879,
  });
  assert.deepEqual(priceOrder([], { couponPercent: 25, shippingCents: 999 }), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 999, totalCents: 999,
  });
});

test('clamps negative coupons to zero and caps coupons at 25 percent', () => {
  for (const couponPercent of [-50, 0, 25, 26, 100]) {
    const discountCents = couponPercent <= 0 ? 0 : 2500;
    assert.deepEqual(priceOrder(cartFor(10000), { couponPercent }), {
      subtotalCents: 10000, discountCents, taxCents: discountCents === 0 ? 1100 : 825,
      shippingCents: 0, totalCents: discountCents === 0 ? 11100 : 8325,
    });
  }
});

test('rounds fractional discounts once across the whole normalized order', () => {
  const cart = [
    { sku: ' a ', quantity: 1, unitPriceCents: 1 },
    { sku: 'b', quantity: 1, unitPriceCents: 1 },
    { sku: 'a', quantity: 1, unitPriceCents: 1 },
  ];
  assert.deepEqual(priceOrder(cart, { couponPercent: 20 }), {
    subtotalCents: 3, discountCents: 1, taxCents: 0, shippingCents: 0, totalCents: 2,
  });
  assert.deepEqual(priceOrder(cartFor(100), { couponPercent: 12.5 }), {
    subtotalCents: 100, discountCents: 13, taxCents: 10, shippingCents: 0, totalCents: 97,
  });
});

test('uses the rounded discount as the tax base and rounds tax once per order', () => {
  assert.deepEqual(priceOrder(cartFor(14), { couponPercent: 3 }), {
    subtotalCents: 14, discountCents: 0, taxCents: 2, shippingCents: 0, totalCents: 16,
  });
  assert.equal(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 5 },
  ]).taxCents, 1);
});

test('normalizes lines and leaves frozen cart and options unchanged', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
    Object.freeze({ sku: 'free', quantity: 9, unitPriceCents: 0 }),
    Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 900 }),
    Object.freeze({ sku: 'invalid', quantity: 2, unitPriceCents: '900' }),
    null,
  ]);
  const options = Object.freeze({ couponPercent: 25, shippingCents: 40 });
  const before = structuredClone({ cart, options });
  const result = priceOrder(cart, options);
  assert.deepEqual(result, {
    subtotalCents: 700, discountCents: 175, taxCents: 58, shippingCents: 40, totalCents: 623,
  });
  result.totalCents = -1;
  assert.equal(priceOrder(cart, options).totalCents, 623);
  assert.deepEqual({ cart, options }, before);
});

