import assert from 'node:assert/strict';
import { formatSummary } from './summary.mjs';

test('empty receipts produce an exact zero summary', () => {
  assert.deepEqual(formatSummary([]), { orders: 0, totalCents: 0, units: 0 });
});

test('summary counts orders and sums final totals and item quantities', () => {
  const receipts = [
    { orderId: 'a', subtotalCents: 1000, totalCents: 1234, itemCount: 3, currency: 'USD' },
    { orderId: 'b', subtotalCents: 800, totalCents: 567, itemCount: 2, currency: 'USD' },
    { orderId: 'a', subtotalCents: 0, totalCents: 0, itemCount: 4, currency: 'USD' },
  ];
  assert.deepEqual(formatSummary(receipts), { orders: 3, totalCents: 1801, units: 9 });
});

test('frozen receipts are unchanged and calls return independent summaries', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a', totalCents: 101, itemCount: 2, currency: 'USD' }),
  ]);
  const before = structuredClone(receipts);
  const first = formatSummary(receipts);
  first.totalCents = 0;
  first.units = 0;
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 101, units: 2 });
  assert.deepEqual(receipts, before);
});

