});

test('fulfillment propagates shortage without changing order or any stock counts', () => {
  const order = {
    id: 'short', cart: [
      { sku: 'enough', quantity: 1, unitPriceCents: 100 },
      { sku: 'short', quantity: 2, unitPriceCents: 100 },
      { sku: 'short', quantity: 2, unitPriceCents: 200 },
    ], options: { couponPercent: 10, shippingCents: 5 },
  };
  const stock = { enough: 8, short: 3 };
  const before = structuredClone({ order, stock });
  assert.throws(() => fulfillOrder(order, stock), { name: 'RangeError', message: 'insufficient stock' });
  assert.deepEqual({ order, stock }, before);
});

test('empty fulfillment uses receipt defaults and returns a fresh stock object', () => {
  const stock = Object.freeze({ untouched: 2 });
  const result = fulfillOrder({ id: 0, cart: [] }, stock);
  assert.deepEqual(result, {
    receipt: {
      orderId: 0, subtotalCents: 0, discountCents: 0, taxCents: 0,
