});

inventory.mjs.text:
// Atomic reservation adapter.
import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const required = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    required.set(sku, (required.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of required) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of required) {
    reserved[sku] -= quantity;
  }
  return reserved;
}

