import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('integrated fulfillment, reporting and returns share the revised receipt total', () => {
  const order = Object.freeze({
    id: 'order,"one"\nnext', status: 'delivered', deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 148 }),
      Object.freeze({ sku: 'gift', quantity: 1, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 900 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 9 }),
  });
  const stock = Object.freeze({ a: 6, gift: 2, unrelated: 7 });
  const before = structuredClone({ order, stock });
  const fulfilled = fulfillOrder(order, stock);
  assert.deepEqual(fulfilled, {
    receipt: {
      orderId: order.id, subtotalCents: 451, discountCents: 113, taxCents: 37,
      shippingCents: 9, totalCents: 384, itemCount: 5, currency: 'USD',
    },
    stock: { a: 2, gift: 1, unrelated: 7 },
  });
  const empty = fulfillOrder({ id: 'empty', cart: [], options: { shippingCents: 7 } }, fulfilled.stock);
  const receipts = Object.freeze([Object.freeze(fulfilled.receipt), Object.freeze(empty.receipt)]);
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 391, units: 5 });
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\n"order,""one""\nnext",384,USD\nempty,7,USD');
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 31 })), {
    eligible: true, reason: 'eligible', refundCents: 384, currency: 'USD',
  });
  assert.deepEqual(returnOrder(order, { nowDay: 32 }), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'USD',
  });
  assert.deepEqual({ order, stock }, before);
  assert.deepEqual(empty.stock, fulfilled.stock);
  assert.notStrictEqual(empty.stock, fulfilled.stock);
});

inventory.mjs.text:
// Atomic reservation adapter.
import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const required = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    required.set(sku, (required.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of required) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of required) {
    reserved[sku] -= quantity;
  }
  return reserved;
}

