import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reserveInventory } from './inventory.mjs';

const line = (sku, quantity, unitPriceCents = 100) => ({ sku, quantity, unitPriceCents });
const shortage = { name: 'RangeError', message: 'insufficient stock' };

test('reservation aggregates normalized quantities across prices and preserves unrelated stock', () => {
  const stock = Object.freeze({ a: 6, gift: 4, untouched: 12, zero: 0 });
  const cart = Object.freeze([
    line(' a ', 2), line('a', 1), line('a', 3, 200), line('gift', 2, 0),
    null, line(' ', 99), line('missing', 0), line('missing', 1.5),
    line('missing', 1, -1), { sku: 42, quantity: 1, unitPriceCents: 100 },
  ].map(item => item === null ? null : Object.freeze(item)));
  const before = structuredClone({ stock, cart });
  const result = reserveInventory(stock, cart);
  assert.deepEqual(result, { a: 0, gift: 2, untouched: 12, zero: 0 });
  assert.notStrictEqual(result, stock);
  assert.deepEqual({ stock, cart }, before);
});

test('different prices cannot reserve the same SKU beyond its combined availability', () => {
  const stock = Object.freeze({ a: 4 });
  const cart = Object.freeze([Object.freeze(line('a', 3)), Object.freeze(line(' a ', 2, 200))]);
  assert.throws(() => reserveInventory(stock, cart), shortage);
  assert.deepEqual(stock, { a: 4 });
  assert.deepEqual(cart, [line('a', 3), line(' a ', 2, 200)]);
});

test('a late shortage leaves all stock and cart inputs unchanged', () => {
  const stock = { enough: 10, scarce: 1, unrelated: 9 };
  const cart = [line('enough', 5), line('scarce', 2)];
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), shortage);
  assert.deepEqual({ stock, cart }, before);
});

test('absent and zero stock throw the exact shortage error', () => {
  for (const stock of [{}, { missing: 0 }]) {
    assert.throws(() => reserveInventory(stock, [line('missing', 1)]), shortage);
  }
});

test('empty or entirely invalid carts return independent unchanged stock copies', () => {
  const stock = Object.freeze({ a: 8 });
  for (const cart of [[], [null, line(' ', 1), line('a', -1)]]) {
    const first = reserveInventory(stock, cart);
    assert.deepEqual(first, stock);
    assert.notStrictEqual(first, stock);
    first.a = 0;
    assert.deepEqual(reserveInventory(stock, cart), { a: 8 });
  }
  const cart = [line('a', 2)];
  const first = reserveInventory(stock, cart);
  first.a = 99;
  assert.deepEqual(reserveInventory(stock, cart), { a: 6 });
});

test('stock SKU names are own keys, including prototype names and case-sensitive names', () => {
  const stock = Object.freeze(JSON.parse('{"__proto__":3,"constructor":4,"toString":2,"a":2,"A":5}'));
  assert.deepEqual(reserveInventory(stock, [
    line('__proto__', 2), line('constructor', 4), line('toString', 1), line('A', 3),
  ]), JSON.parse('{"__proto__":1,"constructor":0,"toString":1,"a":2,"A":2}'));
  for (const sku of ['__proto__', 'constructor', 'toString']) {
    assert.throws(() => reserveInventory({}, [line(sku, 1)]), shortage);
  }
  const inherited = Object.create({ hidden: 10 });
  assert.throws(() => reserveInventory(inherited, [line('hidden', 1)]), shortage);
});

