import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart } from './cart.mjs';

test('drops invalid lines without coercing fields and keeps zero prices', () => {
  const valid = { sku: ' free ', quantity: 1, unitPriceCents: 0 };
  const invalid = [null, undefined, false, 7, 'sku', {},
    ...['', ' \t\n ', 3, null, undefined].map(sku => ({ ...valid, sku })),
    ...[0, -1, 1.5, '2', NaN, Infinity, null, undefined].map(quantity => ({ ...valid, quantity })),
    ...[-1, 0.5, '0', NaN, Infinity, null, undefined].map(unitPriceCents => ({ ...valid, unitPriceCents }))];

  assert.deepEqual(normalizeCart(invalid), []);
  assert.deepEqual(normalizeCart([...invalid, valid]), [
    { sku: 'free', quantity: 1, unitPriceCents: 0 },
  ]);
});

test('merges by trimmed SKU and price while preserving first pair appearance', () => {
  const cart = [
    { sku: ' a ', quantity: 2, unitPriceCents: 101 },
    { sku: 'b', quantity: 1, unitPriceCents: 101 },
    { sku: 'a', quantity: 3, unitPriceCents: 102 },
    { sku: '\ta\n', quantity: 4, unitPriceCents: 101 },
    { sku: ' a ', quantity: 5, unitPriceCents: 102 },
    { sku: 'A', quantity: 6, unitPriceCents: 101 },
  ];

  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 6, unitPriceCents: 101 },
    { sku: 'b', quantity: 1, unitPriceCents: 101 },
    { sku: 'a', quantity: 8, unitPriceCents: 102 },
    { sku: 'A', quantity: 6, unitPriceCents: 101 },
  ]);
});

test('returns fresh exact objects and leaves frozen inputs unchanged', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'omit' }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: 'b', quantity: 4, unitPriceCents: 0 }),
    null,
  ]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);

  assert.deepEqual(result, [
    { sku: 'a', quantity: 5, unitPriceCents: 100 },
    { sku: 'b', quantity: 4, unitPriceCents: 0 },
  ]);
  assert.notStrictEqual(result, cart);
  for (const item of result) assert.ok(!cart.includes(item));
  result[0].quantity = 99;
  result[1].sku = 'changed';
  assert.deepEqual(cart, before);
  assert.equal(normalizeCart(cart)[0].quantity, 5);
});

test('handles object property names and separator-like SKUs independently', () => {
