import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('return status takes precedence over invalid dates and expired windows', () => {
  for (const status of ['pending', 'shipped', 'returned', 'Delivered', '', null, undefined]) {
    assert.deepEqual(canReturn({ status, deliveredDay: -1 }, { nowDay: -1 }), {
      eligible: false, reason: 'status',
    });
    assert.deepEqual(canReturn({ status, deliveredDay: 0 }, { nowDay: 22 }), {
      eligible: false, reason: 'status',
    });
  }
});

test('return dates require nonnegative integers without coercion', () => {
  const invalidDays = [-1, 0.5, '1', null, undefined, NaN, Infinity, -Infinity, true];
  for (const day of invalidDays) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: day }, { nowDay: 100 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: day }), {
      eligible: false, reason: 'date',
    });
  }
});

test('return dates reject a current day before delivery', () => {
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 50 }, { nowDay: 49 }), {
    eligible: false, reason: 'date',
  });
});

test('return window includes delivery day and day 21, but excludes day 22', () => {
  for (const deliveredDay of [0, 100]) {
    for (const elapsed of [0, 1, 20, 21]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, {
        nowDay: deliveredDay + elapsed,
      }), { eligible: true, reason: 'eligible' });
    }
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, {
      nowDay: deliveredDay + 22,
    }), { eligible: false, reason: 'window' });
  }
});

test('canReturn leaves frozen inputs unchanged and returns independent results', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 8, extra: 'ignored' });
  const context = Object.freeze({ nowDay: 29 });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  result.eligible = false;
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

