import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as cartModule from './cart.mjs';
import * as receiptModule from './receipt.mjs';
import * as inventoryModule from './inventory.mjs';
import * as returnsModule from './returns.mjs';
import * as pipelineModule from './pipeline.mjs';
import * as summaryModule from './summary.mjs';

// Independent audit of PROJECT_PLAN.md's final release contract.
const { normalizeCart, priceOrder } = cartModule;
const { buildReceipt, renderCSV } = receiptModule;
const { reserveInventory } = inventoryModule;
const { canReturn } = returnsModule;
const { fulfillOrder, returnOrder } = pipelineModule;
const { formatSummary } = summaryModule;
const line = (sku, quantity, unitPriceCents) => ({ sku, quantity, unitPriceCents });
const freeze = value => {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
};

test('audit: module exports match the nine release functions', () => {
  for (const [module, names] of [
    [cartModule, ['normalizeCart', 'priceOrder']],
    [receiptModule, ['buildReceipt', 'renderCSV']],
    [inventoryModule, ['reserveInventory']],
    [returnsModule, ['canReturn']],
    [pipelineModule, ['fulfillOrder', 'returnOrder']],
    [summaryModule, ['formatSummary']],
  ]) {
    assert.deepEqual(Object.keys(module).sort(), names.sort());
    for (const name of names) assert.equal(typeof module[name], 'function');
  }
});

test('audit: interleaved duplicate pairs, invalid lines and frozen inputs', () => {
  const cart = freeze([
    line(' x ', 1, 17), line('y', 2, 0), line('x', 2, 19),
    line('\tx\n', 3, 17), line('y', 1, 0), line('X', 1, 17),
    null, line(' ', 3, 99), line('x', 0, 17), line('x', 1, '17'),
  ]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);
  assert.deepEqual(result, [line('x', 4, 17), line('y', 3, 0), line('x', 2, 19), line('X', 1, 17)]);
  assert.deepEqual(normalizeCart(result), result);
  result[0].quantity = 999;
  assert.deepEqual(cart, before);
  assert.equal(normalizeCart(cart)[0].quantity, 4);
});

test('audit: fixed pricing examples distinguish rounding, cap and shipping tax base', () => {
  const cases = [
    [3, { couponPercent: 20 }, [3, 1, 0, 0, 2]],
    [14, { couponPercent: 3 }, [14, 0, 2, 0, 16]],
    [100, { couponPercent: 12.5 }, [100, 13, 10, 0, 97]],
    [10000, { couponPercent: 99, shippingCents: 777 }, [10000, 2500, 825, 777, 9102]],
    [10000, { couponPercent: -1, shippingCents: 777 }, [10000, 0, 1100, 777, 11877]],
    [0, { shippingCents: 777 }, [0, 0, 0, 777, 777]],
  ];
  for (const [subtotal, options, values] of cases) {
    const expected = Object.fromEntries(['subtotalCents', 'discountCents', 'taxCents', 'shippingCents', 'totalCents']
      .map((key, index) => [key, values[index]]));
    const cart = freeze([line('item', 1, subtotal)]);
    assert.deepEqual(priceOrder(cart, freeze(options)), expected);
    assert.deepEqual(priceOrder(cart, { ...options, shippingCents: (options.shippingCents ?? 0) + 100 }), {
      ...expected, shippingCents: expected.shippingCents + 100, totalCents: expected.totalCents + 100,
    });
  }
});

test('audit: CSV preserves special characters in every column, CRLF records and input order', () => {
  const receipts = freeze([
    { orderId: 'a,"b"\r\nc', totalCents: 1, currency: 'GBP' },
    { orderId: 'last', totalCents: '2,3', currency: 'G"B\nP' },
  ]);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"a,""b""\r\nc",1,GBP\r\nlast,"2,3","G""B\nP"');
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('audit: return precedence and relative window across all boundary days', () => {
  for (const deliveredDay of [0, 7, 1000]) {
    for (let elapsed = 0; elapsed <= 24; elapsed++) {
      const eligible = elapsed <= 23;
      const expected = { eligible, reason: eligible ? 'eligible' : 'window' };
      const order = freeze({ status: 'delivered', deliveredDay, cart: [line('a', 1, 100)], options: { couponPercent: 25 } });
      const context = freeze({ nowDay: deliveredDay + elapsed });
      assert.deepEqual(canReturn(order, context), expected);
      assert.deepEqual(returnOrder(order, context), { ...expected, refundCents: eligible ? 83 : 0, currency: 'GBP' });
    }
  }
  assert.deepEqual(canReturn({ status: 'pending', deliveredDay: -1 }, { nowDay: 100 }), { eligible: false, reason: 'status' });
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: -1 }, { nowDay: 100 }), { eligible: false, reason: 'date' });
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 10 }, { nowDay: 9 }), { eligible: false, reason: 'date' });
});

test('audit: atomic inventory and all adapters agree on a frozen end-to-end order', () => {
  const order = freeze({ id: 'audit', status: 'delivered', deliveredDay: 4,
    cart: [line(' a ', 1, 101), line('a', 1, 101), line('a', 1, 98), line('gift', 2, 0), null],
    options: { couponPercent: 50, shippingCents: 13 }, currency: 'EUR' });
  const stock = freeze({ a: 5, gift: 2, untouched: 8 });
  const before = structuredClone({ order, stock });
  const receipt = { orderId: 'audit', subtotalCents: 300, discountCents: 75, taxCents: 25,
    shippingCents: 13, totalCents: 263, itemCount: 5, currency: 'GBP' };
  const remaining = { a: 2, gift: 0, untouched: 8 };
  assert.deepEqual(buildReceipt(order), receipt);
  assert.deepEqual(reserveInventory(stock, order.cart), remaining);
  assert.deepEqual(fulfillOrder(order, stock), { receipt, stock: remaining });
  assert.deepEqual(returnOrder(order, freeze({ nowDay: 27 })), { eligible: true, reason: 'eligible', refundCents: 263, currency: 'GBP' });
  assert.deepEqual(formatSummary(freeze([receipt, { totalCents: 7, itemCount: 0 }])), { orders: 2, totalCents: 270, units: 5 });
  assert.deepEqual(formatSummary([]), { orders: 0, totalCents: 0, units: 0 });
  const scarce = { a: 5, gift: 1, untouched: 8 };
  const scarceBefore = structuredClone(scarce);
  for (const reserve of [() => reserveInventory(scarce, order.cart), () => fulfillOrder(order, scarce)]) {
    assert.throws(reserve, error => error instanceof RangeError && error.message === 'insufficient stock');
    assert.deepEqual(scarce, scarceBefore);
  }
  assert.deepEqual({ order, stock }, before);
});

