import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';

test('receipt uses revised pricing and counts normalized quantities with an exact shape', () => {
  const order = {
    id: 'order-1', currency: 'EUR',
    cart: [
      { sku: ' a ', quantity: 2, unitPriceCents: 101 },
      { sku: 'a', quantity: 1, unitPriceCents: 101 },
      { sku: 'a', quantity: 2, unitPriceCents: 1 },
      { sku: 'gift', quantity: 4, unitPriceCents: 0 },
      null,
      { sku: ' ', quantity: 100, unitPriceCents: 900 },
      { sku: 'invalid', quantity: 1.5, unitPriceCents: 900 },
      { sku: 'invalid', quantity: 1, unitPriceCents: -1 },
    ],
    options: { couponPercent: 99, shippingCents: 17 },
    status: 'delivered',
    deliveredDay: 5,
  };
  assert.deepEqual(buildReceipt(order), {
    orderId: 'order-1', subtotalCents: 305, discountCents: 76,
    taxCents: 25, shippingCents: 17, totalCents: 271, itemCount: 9, currency: 'GBP',
  });
});

test('receipt handles absent options, empty carts and shipping on an empty cart', () => {
  assert.deepEqual(buildReceipt({ id: 0, cart: [] }), {
    orderId: 0, subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'GBP',
  });
  assert.deepEqual(buildReceipt({ id: 'empty', cart: [], options: { shippingCents: 13 } }), {
    orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 13, totalCents: 13, itemCount: 0, currency: 'GBP',
  });
  assert.deepEqual(buildReceipt({ id: 'default', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 101 }] }), {
    orderId: 'default', subtotalCents: 101, discountCents: 0, taxCents: 11,
    shippingCents: 0, totalCents: 112, itemCount: 1, currency: 'GBP',
  });
});

test('receipt rounds the discount once per order', () => {
  const receipt = buildReceipt({
    id: 'rounding',
    cart: [{ sku: 'a', quantity: 1, unitPriceCents: 1 }, { sku: 'b', quantity: 1, unitPriceCents: 1 }],
    options: { couponPercent: 25 },
  });
  assert.equal(receipt.discountCents, 1);
  assert.equal(receipt.totalCents, 1);
});

test('receipt leaves frozen order inputs unchanged and returns independent objects', () => {
  const order = Object.freeze({
    id: 'frozen', status: 'pending', deliveredDay: 0,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
    ]),
    options: Object.freeze({ couponPercent: 10, shippingCents: 5 }),
  });
  const before = structuredClone(order);
  const expected = buildReceipt(order);
  const first = buildReceipt(order);
  assert.notStrictEqual(first, expected);
  first.itemCount = 999;
  first.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('CSV emits only its header for empty input and preserves row order with CRLF separators and no trailing newline', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
  assert.equal(renderCSV([
    { orderId: 'b', totalCents: 271, currency: 'GBP', itemCount: 9 },
    { orderId: 'a', totalCents: 0, currency: 'GBP' },
    { orderId: 'b', totalCents: 1, currency: 'GBP' },
  ]), 'orderId,totalCents,currency\r\nb,271,GBP\r\na,0,GBP\r\nb,1,GBP');
});

test('CSV quotes commas, quotes and newline fields while preserving field contents', () => {
  const cases = [
    ['', ''],
    ['plain', 'plain'],
    ['a,b', '"a,b"'],
    ['a"b', '"a""b"'],
    ['a\nb', '"a\nb"'],
    ['a\rb', '"a\rb"'],
    ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\nc', '"a,""b""\nc"'],
  ];
  for (const [orderId, escaped] of cases) {
    assert.equal(renderCSV([{ orderId, totalCents: 0, currency: 'GBP' }]),
      `orderId,totalCents,currency\r\n${escaped},0,GBP`);
  }
  assert.equal(renderCSV([{ orderId: 42, totalCents: 12, currency: 'U,S"D' }]),
    'orderId,totalCents,currency\r\n42,12,"U,S""D"');
});

test('CSV renders built receipts without changing frozen inputs', () => {
  const receipt = Object.freeze(buildReceipt({
    id: 'order,"one"', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 101 }],
    options: { couponPercent: 25, shippingCents: 7 },
  }));
  const receipts = Object.freeze([receipt]);
  const before = structuredClone(receipts);
  const expected = 'orderId,totalCents,currency\r\n"order,""one""",175,GBP';
  assert.equal(renderCSV(receipts), expected);
  assert.equal(renderCSV(receipts), expected);
  assert.deepEqual(receipts, before);
});

