  for (const [cart, options, refundCents] of [
    [cartFor(10000), { couponPercent: 90 }, 8325],
    [cartFor(10000), { couponPercent: -10 }, 11100],
    [[{ sku: 'a', quantity: 1, unitPriceCents: 1 },
      { sku: 'b', quantity: 2, unitPriceCents: 1 }], { couponPercent: 20 }, 2],
    [cartFor(101), undefined, 112],
    [[], undefined, 0],
    [[], { shippingCents: 99 }, 99],
