  assert.deepEqual(priceOrder(cart), expected);
  assert.deepEqual(priceOrder(cart, {}), expected);
});

test('clamps coupons to the revised 25 percent cap and taxes after discount', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 10000 }];
  for (const couponPercent of [25, 26, 100]) {
    assert.deepEqual(priceOrder(cart, { couponPercent, shippingCents: 200 }), {
      subtotalCents: 10000, discountCents: 2500, taxCents: 825,
      shippingCents: 200, totalCents: 8525,
    });
