import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatSummary } from './summary.mjs';

test('empty receipts produce an exact zero summary', () => {
  assert.deepEqual(formatSummary([]), { orders: 0, totalCents: 0, units: 0 });
});

test('summary counts receipts and sums cents and item quantities', () => {
  const receipts = [
    { orderId: 'a', totalCents: 111, itemCount: 3, currency: 'USD' },
    { orderId: 'b', totalCents: 222, itemCount: 2, currency: 'USD' },
    { orderId: 'c', totalCents: 0, itemCount: 0, currency: 'USD' },
  ];

  assert.deepEqual(formatSummary(receipts), { orders: 3, totalCents: 333, units: 5 });
});

test('summary preserves frozen inputs and returns an independent result', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a', totalCents: 125, itemCount: 4 }),
  ]);
  const summary = formatSummary(receipts);

  assert.deepEqual(summary, { orders: 1, totalCents: 125, units: 4 });
  summary.totalCents = 0;
  summary.units = 0;
  assert.deepEqual(receipts, [{ orderId: 'a', totalCents: 125, itemCount: 4 }]);
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 125, units: 4 });
});

