test('CSV quotes commas, quotes, LF, CR and CRLF while preserving field content', () => {
  const ids = ['a,b', 'say "hi"', 'line\nbreak', 'line\rbreak', 'line\r\nbreak', 'a,"b"\nc'];
  const receipts = ids.map(orderId => ({ orderId, totalCents: 0, currency: 'USD' }));
  assert.equal(renderCSV(receipts), [
    'orderId,totalCents,currency',
    '"a,b",0,USD',
    '"say ""hi""",0,USD',
    '"line\nbreak",0,USD',
    '"line\rbreak",0,USD',
    '"line\r\nbreak",0,USD',
    '"a,""b""\nc",0,USD',
  ].join('\n'));
  assert.equal(renderCSV([{ orderId: 'id', totalCents: '1,000', currency: 'U"SD' }]),
    'orderId,totalCents,currency\nid,"1,000","U""SD"');
});

test('CSV preserves frozen receipts and their array', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a,"b"', totalCents: 125, itemCount: 4, currency: 'USD' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\n"a,""b""",125,USD');
  assert.deepEqual(receipts, before);
});

