  }), {
    orderId: 'rounding', subtotalCents: 6, discountCents: 2,
    taxCents: 0, shippingCents: 10000, totalCents: 10004, itemCount: 2, currency: 'USD',
  });
});

test('receipt handles empty and entirely invalid carts, including shipping-only orders', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    assert.deepEqual(buildReceipt({ id: 0, cart }), {
