test('CSV quotes commas, quotes, LF, CR and CRLF while preserving field content', () => {
  const ids = ['a,b', 'say "hi"', 'line\nbreak', 'line\rbreak', 'line\r\nbreak', 'a,"b"\nc'];
  const receipts = ids.map(orderId => ({ orderId, totalCents: 0, currency: 'USD' }));
  assert.equal(renderCSV(receipts), [
