import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('return status must be delivered and takes precedence over invalid dates', () => {
  for (const status of ['pending', 'shipped', 'returned', 'Delivered', '', null, undefined]) {
    assert.deepEqual(canReturn({ status, deliveredDay: -1 }, { nowDay: -2 }), {
      eligible: false, reason: 'status',
    });
  }
  assert.deepEqual(canReturn({ status: 'pending', deliveredDay: 0 }, { nowDay: 22 }), {
    eligible: false, reason: 'status',
  });
});

test('both return dates must be nonnegative integers', () => {
  const invalidDays = [-1, 0.5, '0', null, undefined, NaN, Infinity, -Infinity, true, {}, []];
  for (const invalidDay of invalidDays) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: invalidDay }, { nowDay: 100 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: invalidDay }), {
      eligible: false, reason: 'date',
    });
  }
});

test('a date before delivery fails before the window check', () => {
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 100 }, { nowDay: 1 }), {
    eligible: false, reason: 'date',
  });
});

test('return window includes delivery day and day 21, but excludes day 22', () => {
  for (const deliveredDay of [0, 10]) {
    for (const elapsed of [0, 1, 20, 21]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: true, reason: 'eligible',
      });
    }
    for (const elapsed of [22, 30, 100]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: false, reason: 'window',
      });
    }
  }
});

test('return eligibility preserves frozen inputs and returns independent exact results', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 5, extra: 'omit' });
  const context = Object.freeze({ nowDay: 26, extra: 'omit' });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  assert.deepEqual(result, { eligible: true, reason: 'eligible' });
  result.eligible = false;
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

