  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
});

test('missing and zero stock reject positive demand, including prototype-like sku names', () => {
  for (const sku of ['missing', 'zero', '__proto__', 'constructor', 'toString']) {
    assert.throws(() => reserveInventory({ zero: 0 }, [
      { sku, quantity: 1, unitPriceCents: 0 },
    ]), { name: 'RangeError', message: 'insufficient stock' });
  }
  const stock = Object.create({ inherited: 5 });
  assert.throws(() => reserveInventory(stock, [
    { sku: 'inherited', quantity: 1, unitPriceCents: 0 },
  ]), { name: 'RangeError', message: 'insufficient stock' });
