import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart } from './cart.mjs';

test('drops malformed lines and invalid field values', () => {
  const valid = { sku: 'valid', quantity: 1, unitPriceCents: 0 };
  const invalidSkus = [undefined, null, 123, {}, '', ' \t\n '];
  const invalidQuantities = [undefined, null, '1', 0, -1, 1.5, NaN, Infinity];
  const invalidPrices = [undefined, null, '0', -1, 0.5, NaN, Infinity];
  const cart = [
    null, undefined, false, 1, 'line', {},
    ...invalidSkus.map(sku => ({ ...valid, sku })),
    ...invalidQuantities.map(quantity => ({ ...valid, quantity })),
    ...invalidPrices.map(unitPriceCents => ({ ...valid, unitPriceCents })),
    valid,
  ];
  assert.deepEqual(normalizeCart(cart), [valid]);
});

test('merges only trimmed sku and price pairs in first appearance order', () => {
  assert.deepEqual(normalizeCart([
    { sku: ' a ', quantity: 2, unitPriceCents: 101 },
    { sku: 'b', quantity: 1, unitPriceCents: 50 },
    { sku: 'a', quantity: 3, unitPriceCents: 202 },
    { sku: '\ta\n', quantity: 4, unitPriceCents: 101 },
    { sku: ' b ', quantity: 2, unitPriceCents: 50 },
    { sku: 'A', quantity: 1, unitPriceCents: 101 },
  ]), [
    { sku: 'a', quantity: 6, unitPriceCents: 101 },
    { sku: 'b', quantity: 3, unitPriceCents: 50 },
    { sku: 'a', quantity: 3, unitPriceCents: 202 },
    { sku: 'A', quantity: 1, unitPriceCents: 101 },
  ]);
});

test('accepts zero prices and sku names that match object properties', () => {
  assert.deepEqual(normalizeCart([
    { sku: '__proto__', quantity: 1, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: '__proto__', quantity: 3, unitPriceCents: 0 },
  ]), [
    { sku: '__proto__', quantity: 4, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
  ]);
});

test('returns fresh objects with only required fields and never mutates input', () => {
  const first = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101, extra: 'omit' });
  const second = Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 101 });
  const cart = Object.freeze([first, null, second]);
  const result = normalizeCart(cart);
  assert.deepEqual(result, [{ sku: 'a', quantity: 5, unitPriceCents: 101 }]);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], first);
  assert.notStrictEqual(result[0], second);
  result[0].quantity = 99;
  assert.equal(first.quantity, 2);
  assert.equal(second.quantity, 3);
  assert.equal(first.sku, ' a ');
  assert.deepEqual(normalizeCart(cart), [{ sku: 'a', quantity: 5, unitPriceCents: 101 }]);
});

