    { status: 'delivered', deliveredDay: 10, nowDay: 9, reason: 'date' },
    { status: 'delivered', deliveredDay: 10, nowDay: 32, reason: 'window' },
  ];
  for (const { status, deliveredDay, nowDay, reason } of cases) {
    const order = Object.freeze({
      status, deliveredDay,
      get cart() { throw new Error('ineligible cart must not be read'); },
      get options() { throw new Error('ineligible options must not be read'); },
    });
    assert.deepEqual(returnOrder(order, Object.freeze({ nowDay })), {
      eligible: false, reason, refundCents: 0, currency: 'USD',
    });
  }
});

test('refund normalizes the cart and preserves frozen order, options and context', () => {
  const order = Object.freeze({
    status: 'delivered', deliveredDay: 1,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'omit' }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'bad', quantity: -1, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 75 }),
  });
  const context = Object.freeze({ nowDay: 22 });
  const before = structuredClone({ order, context });
  const expected = { eligible: true, reason: 'eligible', refundCents: 658, currency: 'USD' };
  const result = returnOrder(order, context);
  assert.deepEqual(result, expected);
  result.refundCents = 0;
  assert.deepEqual(returnOrder(order, context), expected);
  assert.deepEqual({ order, context }, before);
});

test('eligible empty and invalid carts refund zero or shipping only', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    for (const shippingCents of [0, 123]) {
      assert.deepEqual(returnOrder({
        status: 'delivered', deliveredDay: 0, cart,
        options: { couponPercent: 25, shippingCents },
      }, { nowDay: 21 }), {
        eligible: true, reason: 'eligible', refundCents: shippingCents, currency: 'USD',
      });
    }
  }
});

