  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.itemCount = 0;
  receipt.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('receipt applies order-level discount rounding and excludes shipping from tax', () => {
  assert.deepEqual(buildReceipt({
    id: 'rounding',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 3 },
      { sku: 'b', quantity: 1, unitPriceCents: 3 },
    ],
    options: { couponPercent: 25, shippingCents: 10000 },
  }), {
    orderId: 'rounding', subtotalCents: 6, discountCents: 2,
    taxCents: 0, shippingCents: 10000, totalCents: 10004, itemCount: 2, currency: 'USD',
  });
});

test('receipt handles empty and entirely invalid carts, including shipping-only orders', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    assert.deepEqual(buildReceipt({ id: 0, cart }), {
      orderId: 0, subtotalCents: 0, discountCents: 0,
      taxCents: 0, shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'USD',
    });
    assert.deepEqual(buildReceipt({ id: 0, cart, options: { shippingCents: 123 } }), {
      orderId: 0, subtotalCents: 0, discountCents: 0,
      taxCents: 0, shippingCents: 123, totalCents: 123, itemCount: 0, currency: 'USD',
    });
  }
});

test('CSV of empty input is only the header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV selects the three columns in input order with LF and no trailing newline', () => {
  const receipts = [
    buildReceipt({ id: 'b', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 101 }] }),
    buildReceipt({ id: 0, cart: [] }),
    buildReceipt({ id: '', cart: [] }),
  ];
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\nb,224,USD\n0,0,USD\n,0,USD');
});

test('CSV quotes commas, quotes, LF, CR and CRLF while preserving field content', () => {
  const ids = ['a,b', 'say "hi"', 'line\nbreak', 'line\rbreak', 'line\r\nbreak', 'a,"b"\nc'];
  const receipts = ids.map(orderId => ({ orderId, totalCents: 0, currency: 'USD' }));
  assert.equal(renderCSV(receipts), [
    'orderId,totalCents,currency',
    '"a,b",0,USD',
    '"say ""hi""",0,USD',
    '"line\nbreak",0,USD',
    '"line\rbreak",0,USD',
    '"line\r\nbreak",0,USD',
    '"a,""b""\nc",0,USD',
  ].join('\n'));
  assert.equal(renderCSV([{ orderId: 'id', totalCents: '1,000', currency: 'U"SD' }]),
    'orderId,totalCents,currency\nid,"1,000","U""SD"');
});

test('CSV preserves frozen receipts and their array', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a,"b"', totalCents: 125, itemCount: 4, currency: 'USD' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\n"a,""b""",125,USD');
  assert.deepEqual(receipts, before);
});

