import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('integrated fulfillment, CSV, summary and returns agree on the current release', () => {
  const order = Object.freeze({
    id: 'order,"one"',
    status: 'delivered',
    deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 75 }),
  });
  const stock = Object.freeze({ a: 8, free: 2 });
  const before = structuredClone({ order, stock });
  const { receipt, stock: reserved } = fulfillOrder(order, stock);
  assert.deepEqual(reserved, { a: 2, free: 0 });
  assert.equal(receipt.totalCents, 658);
  const receipts = Object.freeze([Object.freeze(receipt)]);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\n"order,""one""",658,USD');
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 658, units: 8 });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 31 })), {
    eligible: true, reason: 'eligible', refundCents: receipt.totalCents, currency: 'USD',
  });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 32 })), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'USD',
  });
  assert.deepEqual({ order, stock }, before);
});

returns.mjs.text:
// Return eligibility policy.

export function canReturn(order, { nowDay }) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  if (
    !Number.isInteger(order.deliveredDay) ||
    order.deliveredDay < 0 ||
    !Number.isInteger(nowDay) ||
    nowDay < 0 ||
    nowDay < order.deliveredDay
  ) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - order.deliveredDay > 21) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

