      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 75 }),
    status: 'pending',
    deliveredDay: 10,
    extra: 'omit',
  });
  const stock = Object.freeze({ a: 8, free: 2, untouched: 9 });
  const before = structuredClone({ order, stock });
  const result = fulfillOrder(order, stock);
  assert.deepEqual(result, {
    receipt: {
      orderId: 'fulfill-1', subtotalCents: 700, discountCents: 175,
      taxCents: 58, shippingCents: 75, totalCents: 658, itemCount: 8, currency: 'GBP',
    },
    stock: { a: 2, free: 0, untouched: 9 },
  });
  assert.notStrictEqual(result.stock, stock);
  assert.deepEqual({ order, stock }, before);
  result.stock.a = 0;
  result.receipt.totalCents = 0;
  assert.deepEqual({ order, stock }, before);
});

test('fulfillment supports default pricing and exact depletion', () => {
  assert.deepEqual(fulfillOrder({
    id: 'defaults', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 101 }],
  }, { a: 2 }), {
    receipt: {
      orderId: 'defaults', subtotalCents: 202, discountCents: 0,
      taxCents: 22, shippingCents: 0, totalCents: 224, itemCount: 2, currency: 'GBP',
    },
    stock: { a: 0 },
  });
});

test('fulfillment uses order-level rounding and excludes shipping from tax', () => {
  assert.deepEqual(fulfillOrder({
    id: 'rounding',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 3 },
      { sku: 'b', quantity: 1, unitPriceCents: 3 },
    ],
    options: { couponPercent: 25, shippingCents: 10000 },
  }, { a: 1, b: 1 }), {
    receipt: {
      orderId: 'rounding', subtotalCents: 6, discountCents: 2,
      taxCents: 0, shippingCents: 10000, totalCents: 10004, itemCount: 2, currency: 'GBP',
    },
    stock: { a: 0, b: 0 },
  });
});

test('fulfillment propagates insufficient stock without mutating order or stock', () => {
  for (const stock of [{ a: 5, b: 2 }, { a: 6 }]) {
    const order = {
      id: 'shortage',
      cart: [
        { sku: 'a', quantity: 3, unitPriceCents: 100 },
        { sku: 'a', quantity: 3, unitPriceCents: 200 },
        { sku: 'b', quantity: 2, unitPriceCents: 100 },
      ],
      options: { couponPercent: 25, shippingCents: 75 },
    };
    const before = structuredClone({ order, stock });
    assert.throws(() => fulfillOrder(order, stock), {
      name: 'RangeError', message: 'insufficient stock',
    });
    assert.deepEqual({ order, stock }, before);
  }
});

test('fulfillment handles empty and invalid carts as shipping-only orders', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    const stock = Object.freeze({ a: 3 });
    const result = fulfillOrder({ id: 0, cart, options: { shippingCents: 123 } }, stock);
    assert.deepEqual(result, {
      receipt: {
        orderId: 0, subtotalCents: 0, discountCents: 0,
        taxCents: 0, shippingCents: 123, totalCents: 123, itemCount: 0, currency: 'GBP',
      },
      stock: { a: 3 },
    });
    assert.notStrictEqual(result.stock, stock);
  }
});

inventory.mjs.text:
// Atomic reservation adapter.

import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const required = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    required.set(sku, (required.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of required) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of required) {
    reserved[sku] -= quantity;
  }
  return reserved;
}

