import { test } from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder } from './cart.mjs';

test('defaults coupon and shipping to zero and returns exactly the pricing fields', () => {
  const cart = [{ sku: 'a', quantity: 2, unitPriceCents: 101 }];
  const expected = {
    subtotalCents: 202, discountCents: 0, taxCents: 22,
    shippingCents: 0, totalCents: 224,
  };
  assert.deepEqual(priceOrder(cart), expected);
  assert.deepEqual(priceOrder(cart, {}), expected);
});

test('clamps coupons to the revised 25 percent cap and taxes after discount', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 10000 }];
  for (const couponPercent of [25, 26, 100]) {
    assert.deepEqual(priceOrder(cart, { couponPercent, shippingCents: 200 }), {
      subtotalCents: 10000, discountCents: 2500, taxCents: 825,
      shippingCents: 200, totalCents: 8525,
    });
  }
  for (const couponPercent of [-10, 0]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 10000, discountCents: 0, taxCents: 1100,
      shippingCents: 0, totalCents: 11100,
    });
  }
});

test('accepts fractional coupon percentages', () => {
  assert.deepEqual(priceOrder(
    [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }],
    { couponPercent: 12.5 },
  ), {
    subtotalCents: 1000, discountCents: 125, taxCents: 96,
    shippingCents: 0, totalCents: 971,
  });
});

test('rounds the discount once per order, including half-cent discounts', () => {
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 1 },
    { sku: 'b', quantity: 1, unitPriceCents: 1 },
  ], { couponPercent: 25 }), {
    subtotalCents: 2, discountCents: 1, taxCents: 0,
    shippingCents: 0, totalCents: 1,
  });
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 3 },
    { sku: 'a', quantity: 1, unitPriceCents: 3 },
    { sku: 'b', quantity: 1, unitPriceCents: 3 },
  ], { couponPercent: 25 }), {
    subtotalCents: 9, discountCents: 2, taxCents: 1,
    shippingCents: 0, totalCents: 8,
  });
});

test('rounds tax once per order and rounds half cents up', () => {
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 5 },
  ]), {
    subtotalCents: 10, discountCents: 0, taxCents: 1,
    shippingCents: 0, totalCents: 11,
  });
  assert.equal(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 50 }]).taxCents, 6);
});

test('calculates tax from the rounded discount and excludes shipping', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 6 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 25, shippingCents: 10000 }), {
    subtotalCents: 6, discountCents: 2, taxCents: 0,
    shippingCents: 10000, totalCents: 10004,
  });
});

test('normalizes invalid and duplicate lines without mutating cart or options', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'omit' }),
    null,
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
    Object.freeze({ sku: 'bad', quantity: -1, unitPriceCents: 999 }),
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 999 }),
    Object.freeze({ sku: 'free', quantity: 1, unitPriceCents: 0 }),
  ]);
  const options = Object.freeze({ couponPercent: 20, shippingCents: 75 });
  const before = structuredClone({ cart, options });
  assert.deepEqual(priceOrder(cart, options), {
    subtotalCents: 700, discountCents: 140, taxCents: 62,
    shippingCents: 75, totalCents: 697,
  });
  assert.deepEqual({ cart, options }, before);
});

test('empty and entirely invalid carts charge only shipping', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    assert.deepEqual(priceOrder(cart, { couponPercent: 25, shippingCents: 123 }), {
      subtotalCents: 0, discountCents: 0, taxCents: 0,
      shippingCents: 123, totalCents: 123,
    });
  }
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0,
  });
});

