test('receipt counts normalized quantities and preserves frozen order inputs', () => {
  const order = Object.freeze({
    id: 'normalized',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'omit' }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'bad', quantity: -1, unitPriceCents: 999 }),
      Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 999 }),
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 75 }),
    status: 'delivered',
    deliveredDay: 1,
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'normalized', subtotalCents: 700, discountCents: 175,
    taxCents: 58, shippingCents: 75, totalCents: 658, itemCount: 8, currency: 'GBP',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.itemCount = 0;
  receipt.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('receipt applies order-level discount rounding and excludes shipping from tax', () => {
  assert.deepEqual(buildReceipt({
    id: 'rounding',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 3 },
      { sku: 'b', quantity: 1, unitPriceCents: 3 },
    ],
    options: { couponPercent: 25, shippingCents: 10000 },
  }), {
    orderId: 'rounding', subtotalCents: 6, discountCents: 2,
    taxCents: 0, shippingCents: 10000, totalCents: 10004, itemCount: 2, currency: 'GBP',
  });
});

test('receipt handles empty and entirely invalid carts, including shipping-only orders', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 }]]) {
    assert.deepEqual(buildReceipt({ id: 0, cart }), {
      orderId: 0, subtotalCents: 0, discountCents: 0,
      taxCents: 0, shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'GBP',
    });
    assert.deepEqual(buildReceipt({ id: 0, cart, options: { shippingCents: 123 } }), {
      orderId: 0, subtotalCents: 0, discountCents: 0,
      taxCents: 0, shippingCents: 123, totalCents: 123, itemCount: 0, currency: 'GBP',
    });
  }
});

test('CSV of empty input is only the header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV selects the three columns in input order with CRLF and no trailing newline', () => {
  const receipts = [
    buildReceipt({ id: 'b', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 101 }] }),
    buildReceipt({ id: 0, cart: [] }),
    buildReceipt({ id: '', cart: [] }),
  ];
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\nb,224,GBP\r\n0,0,GBP\r\n,0,GBP');
});

test('CSV quotes commas, quotes, LF, CR and CRLF while preserving field content', () => {
  const ids = ['a,b', 'say "hi"', 'line\nbreak', 'line\rbreak', 'line\r\nbreak', 'a,"b"\nc'];
  const receipts = ids.map(orderId => ({ orderId, totalCents: 0, currency: 'GBP' }));
  assert.equal(renderCSV(receipts), [
    'orderId,totalCents,currency',
    '"a,b",0,GBP',
    '"say ""hi""",0,GBP',
    '"line\nbreak",0,GBP',
    '"line\rbreak",0,GBP',
    '"line\r\nbreak",0,GBP',
    '"a,""b""\nc",0,GBP',
  ].join('\r\n'));
  assert.equal(renderCSV([{ orderId: 'id', totalCents: '1,000', currency: 'U"SD' }]),
    'orderId,totalCents,currency\r\nid,"1,000","U""SD"');
});

test('CSV preserves frozen receipts and their array', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a,"b"', totalCents: 125, itemCount: 4, currency: 'GBP' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"a,""b""",125,GBP');
  assert.deepEqual(receipts, before);
});

