  assert.notStrictEqual(reserved, stock);
  assert.deepEqual({ stock, cart }, before);
  reserved.untouched = 0;
  assert.deepEqual({ stock, cart }, before);
});

test('reservation rejects aggregate shortages even if each price line fits individually', () => {
