  const cart = Object.freeze([
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 200 }),
  ]);
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
});

test('a later shortage leaves all input stock and cart lines unchanged', () => {
  const stock = { a: 10, b: 1 };
  const cart = [
    { sku: 'a', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 2, unitPriceCents: 100 },
  ];
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
});

test('missing and zero stock reject positive demand, including prototype-like sku names', () => {
  for (const sku of ['missing', 'zero', '__proto__', 'constructor', 'toString']) {
    assert.throws(() => reserveInventory({ zero: 0 }, [
      { sku, quantity: 1, unitPriceCents: 0 },
    ]), { name: 'RangeError', message: 'insufficient stock' });
  }
  const stock = Object.create({ inherited: 5 });
  assert.throws(() => reserveInventory(stock, [
    { sku: 'inherited', quantity: 1, unitPriceCents: 0 },
  ]), { name: 'RangeError', message: 'insufficient stock' });
});

test('own stock entries with prototype-like sku names reserve as ordinary counts', () => {
  const stock = Object.freeze(JSON.parse('{"__proto__":3,"constructor":4,"toString":5}'));
  const cart = Object.keys(stock).map(sku => ({ sku, quantity: 2, unitPriceCents: 0 }));
  const reserved = reserveInventory(stock, cart);
  assert.deepEqual(reserved, JSON.parse('{"__proto__":1,"constructor":2,"toString":3}'));
  assert.strictEqual(Object.getPrototypeOf(reserved), Object.prototype);
  assert.deepEqual(stock, JSON.parse('{"__proto__":3,"constructor":4,"toString":5}'));
});

test('empty and entirely invalid carts return an independent stock copy', () => {
  for (const cart of [[], [null, { sku: '', quantity: 1, unitPriceCents: 100 },
    { sku: 'missing', quantity: 1.5, unitPriceCents: 0 },
    { sku: 'missing', quantity: 1, unitPriceCents: -1 }]]) {
    const stock = Object.freeze({ a: 2, zero: 0 });
    const reserved = reserveInventory(stock, cart);
    assert.deepEqual(reserved, stock);
    assert.notStrictEqual(reserved, stock);
  }
  assert.deepEqual(reserveInventory({}, []), {});
});

pipeline.mjs.text:
// Both pipeline workers edit this module. Preserve the other worker's exports.

import { priceOrder } from './cart.mjs';
import { canReturn } from './returns.mjs';
import { buildReceipt } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';

export function returnOrder(order, context) {
  const eligibility = canReturn(order, context);
  const refundCents = eligibility.eligible
    ? priceOrder(order.cart, order.options).totalCents
    : 0;

  return { ...eligibility, refundCents, currency: 'GBP' };
}

export function fulfillOrder(order, stock) {
  return {
    receipt: buildReceipt(order),
    stock: reserveInventory(stock, order.cart),
  };
}

