import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('integrated fulfillment, CSV, summary and returns agree on the current release', () => {
  const order = Object.freeze({
    id: 'order,"one"',
    status: 'delivered',
    deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 75 }),
  });
  const stock = Object.freeze({ a: 8, free: 2 });
  const before = structuredClone({ order, stock });
  const { receipt, stock: reserved } = fulfillOrder(order, stock);
  assert.deepEqual(reserved, { a: 2, free: 0 });
  assert.equal(receipt.totalCents, 658);
  const receipts = Object.freeze([Object.freeze(receipt)]);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"order,""one""",658,GBP');
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 658, units: 8 });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 33 })), {
    eligible: true, reason: 'eligible', refundCents: receipt.totalCents, currency: 'GBP',
  });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 34 })), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'GBP',
  });
  assert.deepEqual({ order, stock }, before);
});

returns.mjs.text:
// Return eligibility policy.

export function canReturn(order, { nowDay }) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  if (
    !Number.isInteger(order.deliveredDay) ||
    order.deliveredDay < 0 ||
    !Number.isInteger(nowDay) ||
    nowDay < 0 ||
    nowDay < order.deliveredDay
  ) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - order.deliveredDay > 23) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

returns.test.mjs.text:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('return status must be delivered and takes precedence over invalid dates', () => {
  for (const status of ['pending', 'shipped', 'returned', 'Delivered', '', null, undefined]) {
    assert.deepEqual(canReturn({ status, deliveredDay: -1 }, { nowDay: -2 }), {
      eligible: false, reason: 'status',
    });
  }
  assert.deepEqual(canReturn({ status: 'pending', deliveredDay: 0 }, { nowDay: 24 }), {
    eligible: false, reason: 'status',
  });
});

test('both return dates must be nonnegative integers', () => {
  const invalidDays = [-1, 0.5, '0', null, undefined, NaN, Infinity, -Infinity, true, {}, []];
  for (const invalidDay of invalidDays) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: invalidDay }, { nowDay: 100 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: invalidDay }), {
      eligible: false, reason: 'date',
    });
  }
});

test('a date before delivery fails before the window check', () => {
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 100 }, { nowDay: 1 }), {
    eligible: false, reason: 'date',
  });
});

test('return window includes delivery day and day 23, but excludes day 24', () => {
  for (const deliveredDay of [0, 10]) {
    for (const elapsed of [0, 1, 21, 22, 23]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: true, reason: 'eligible',
      });
    }
    for (const elapsed of [24, 30, 100]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }), {
        eligible: false, reason: 'window',
      });
    }
  }
});

test('return eligibility preserves frozen inputs and returns independent exact results', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 5, extra: 'omit' });
  const context = Object.freeze({ nowDay: 28, extra: 'omit' });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  assert.deepEqual(result, { eligible: true, reason: 'eligible' });
  result.eligible = false;
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

