import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('builds exact receipt fields from normalized quantities and revised pricing', () => {
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 5, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: -1, unitPriceCents: 999 }),
      Object.freeze({ sku: ' ', quantity: 10, unitPriceCents: 999 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
    status: 'pending',
    deliveredDay: 0,
    extra: 'ignored',
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 500, discountCents: 150, taxCents: 60,
    shippingCents: 250, totalCents: 660, itemCount: 9, currency: 'USD',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.totalCents = 0;
  const again = buildReceipt(order);
  assert.notStrictEqual(again, receipt);
  assert.deepEqual(again, expected);
});

test('builds empty receipts with default options and preserves numeric IDs', () => {
  assert.deepEqual(buildReceipt({ id: 0, cart: [] }), {
    orderId: 0, subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'USD',
  });
  assert.deepEqual(buildReceipt({ id: '', cart: [null], options: { shippingCents: 99 } }), {
    orderId: '', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 99, totalCents: 99, itemCount: 0, currency: 'USD',
  });
});

test('receipts use order-level discount rounding and tax after the rounded discount', () => {
  const receipt = buildReceipt({
    id: 'rounding',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 1 },
      { sku: 'b', quantity: 1, unitPriceCents: 14 },
    ],
    options: { couponPercent: 30 },
  });
  assert.deepEqual(receipt, {
    orderId: 'rounding', subtotalCents: 15, discountCents: 5, taxCents: 2,
    shippingCents: 0, totalCents: 12, itemCount: 2, currency: 'USD',
  });
});

test('empty CSV contains only the required header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves row order, selects required fields, and uses LF without a trailing newline', () => {
  const receipts = Object.freeze([
    Object.freeze({ currency: 'USD', itemCount: 2, totalCents: 1069, orderId: 'first' }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'USD', extra: 'ignored' }),
