import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';

test('drops invalid lines while accepting trimmed SKUs and zero prices', () => {
  const valid = { sku: ' \ta\n', quantity: 2, unitPriceCents: 0, ignored: true };
  const invalid = [null, undefined, {}, 7, 'a',
    { ...valid, sku: '' }, { ...valid, sku: ' \t\n' },
    { ...valid, sku: 1 }, { ...valid, sku: null }];
  for (const quantity of [undefined, null, '2', 0, -1, 1.5, NaN, Infinity]) {
    invalid.push({ ...valid, quantity });
  }
  for (const unitPriceCents of [undefined, null, '0', -1, 0.5, NaN, Infinity]) {
    invalid.push({ ...valid, unitPriceCents });
  }
  assert.deepEqual(normalizeCart([...invalid, valid]), [
    { sku: 'a', quantity: 2, unitPriceCents: 0 },
  ]);
});

test('merges only matching trimmed SKU and price in first appearance order', () => {
  assert.deepEqual(normalizeCart([
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 1, unitPriceCents: 100 },
    { sku: 'a', quantity: 3, unitPriceCents: 200 },
    { sku: '\ta', quantity: 4, unitPriceCents: 100 },
    { sku: 'a', quantity: 5, unitPriceCents: 200 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ]), [
    { sku: 'a', quantity: 6, unitPriceCents: 100 },
    { sku: 'b', quantity: 1, unitPriceCents: 100 },
    { sku: 'a', quantity: 8, unitPriceCents: 200 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ]);
});

test('returns fresh objects and leaves frozen input unchanged', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 1 });
  const duplicate = Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 });
  const cart = Object.freeze([line, duplicate]);
  const result = normalizeCart(cart);
  assert.deepEqual(result, [{ sku: 'a', quantity: 5, unitPriceCents: 100 }]);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], line);
  assert.notStrictEqual(result[0], duplicate);
  result[0].quantity = 99;
  assert.deepEqual(cart, [
    { sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 1 },
    { sku: 'a', quantity: 3, unitPriceCents: 100 },
  ]);
  assert.equal(normalizeCart(cart)[0].quantity, 5);
});

test('handles object-property names and delimiter-containing SKUs as distinct keys', () => {
  const cart = ['__proto__', 'constructor', 'a:1', 'a'].map(sku => ({
    sku, quantity: 1, unitPriceCents: 0,
  }));
  assert.deepEqual(normalizeCart([...cart, ...cart]), cart.map(line => ({
    ...line, quantity: 2,
  })));
});

test('prices empty carts and defaults coupon and shipping to zero', () => {
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 0, totalCents: 0,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 2, unitPriceCents: 101 }], {}), {
    subtotalCents: 202, discountCents: 0, taxCents: 34, shippingCents: 0, totalCents: 236,
  });
  assert.deepEqual(priceOrder([], { shippingCents: 99 }), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 99, totalCents: 99,
  });
});

test('taxes the discounted subtotal at 17 percent and excludes shipping', () => {
  const cart = [{ sku: 'a', quantity: 2, unitPriceCents: 500 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 30, shippingCents: 250 }), {
    subtotalCents: 1000, discountCents: 300, taxCents: 119,
    shippingCents: 250, totalCents: 1069,
  });
});

test('clamps coupons to the revised cap and accepts fractional percentages', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  for (const couponPercent of [-20, 0, 12.5, 30, 99]) {
    const discountCents = new Map([[-20, 0], [0, 0], [12.5, 125], [30, 300], [99, 300]])
      .get(couponPercent);
    const taxCents = new Map([[0, 170], [125, 149], [300, 119]]).get(discountCents);
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 1000, discountCents, taxCents, shippingCents: 0,
      totalCents: 1000 - discountCents + taxCents,
    });
  }
});

test('rounds discounts once per order and taxes after the rounded discount', () => {
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 1 },
    { sku: 'b', quantity: 1, unitPriceCents: 1 },
  ], { couponPercent: 30 }), {
    subtotalCents: 2, discountCents: 1, taxCents: 0, shippingCents: 0, totalCents: 1,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 15 }], {
    couponPercent: 30,
  }), {
    subtotalCents: 15, discountCents: 5, taxCents: 2, shippingCents: 0, totalCents: 12,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 2, unitPriceCents: 3 }]), {
    subtotalCents: 6, discountCents: 0, taxCents: 1, shippingCents: 0, totalCents: 7,
  });
});

test('prices normalized lines without changing frozen cart or options', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
    Object.freeze({ sku: 'free', quantity: 5, unitPriceCents: 0 }),
    Object.freeze({ sku: 'invalid', quantity: -1, unitPriceCents: 999 }),
    null,
  ]);
  const options = Object.freeze({ couponPercent: 20, shippingCents: 50 });
  const before = structuredClone({ cart, options });
  const expected = {
    subtotalCents: 500, discountCents: 100, taxCents: 68, shippingCents: 50, totalCents: 518,
  };
  const result = priceOrder(cart, options);
  assert.deepEqual(result, expected);
  assert.deepEqual({ cart, options }, before);
  result.totalCents = 0;
  assert.deepEqual(priceOrder(cart, options), expected);
});

