// Return eligibility policy.

export function canReturn(order, { nowDay }) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  const { deliveredDay } = order;
  if (!Number.isInteger(deliveredDay) || deliveredDay < 0 ||
      !Number.isInteger(nowDay) || nowDay < 0 || nowDay < deliveredDay) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - deliveredDay > 7) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

