import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('requires delivered status before checking invalid dates or expired windows', () => {
  for (const status of [undefined, null, '', 'pending', 'shipped', 'returned', 'Delivered']) {
    for (const deliveredDay of [-1, 0]) {
      assert.deepEqual(canReturn({ status, deliveredDay }, { nowDay: 20 }), {
        eligible: false, reason: 'status',
      });
    }
  }
});

test('requires nonnegative integer days and rejects dates before delivery', () => {
  const invalidDays = [undefined, null, '0', false, -1, 0.5, NaN, Infinity, -Infinity];
  for (const invalidDay of invalidDays) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: invalidDay }, { nowDay: 20 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: invalidDay }), {
      eligible: false, reason: 'date',
    });
  }
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 10 }, { nowDay: 9 }), {
    eligible: false, reason: 'date',
  });
});

test('allows delivery day through day seven and rejects day eight or later', () => {
  for (const deliveredDay of [0, 10]) {
    for (const elapsed of [0, 1, 6, 7, 8, 30]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, {
        nowDay: deliveredDay + elapsed,
      }), elapsed <= 7
        ? { eligible: true, reason: 'eligible' }
        : { eligible: false, reason: 'window' });
    }
  }
});

test('returns fresh exact fields without changing frozen order or context', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 10, extra: 'ignored' });
  const context = Object.freeze({ nowDay: 17, extra: 'ignored' });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  assert.deepEqual(result, { eligible: true, reason: 'eligible' });
  result.reason = 'changed';
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

