import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reserveInventory } from './inventory.mjs';

test('reserves normalized quantities across prices and keeps untouched stock', () => {
  const stock = Object.freeze({ a: 7, free: 2, untouched: 9, zero: 0 });
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 4, unitPriceCents: 200 }),
    Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
    Object.freeze({ sku: 'missing', quantity: 0, unitPriceCents: 100 }),
    Object.freeze({ sku: 'missing', quantity: 1, unitPriceCents: -1 }),
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 100 }),
    null,
  ]);
  const before = structuredClone(cart);
  const remaining = reserveInventory(stock, cart);
  assert.deepEqual(remaining, { a: 0, free: 0, untouched: 9, zero: 0 });
  assert.notStrictEqual(remaining, stock);
  assert.deepEqual(stock, { a: 7, free: 2, untouched: 9, zero: 0 });
  assert.deepEqual(cart, before);
});

test('shortage across distinct prices throws without partially reserving stock', () => {
  const stock = { enough: 3, short: 4 };
  const cart = [
    { sku: 'enough', quantity: 2, unitPriceCents: 100 },
    { sku: 'short', quantity: 3, unitPriceCents: 100 },
    { sku: ' short ', quantity: 2, unitPriceCents: 200 },
  ];
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
  assert.deepEqual(reserveInventory(stock, [cart[0]]), { enough: 1, short: 4 });
});

test('absent and zero-count SKUs are insufficient, including prototype names', () => {
  for (const sku of ['missing', 'zero', '__proto__', 'constructor', 'toString']) {
    const stock = Object.freeze({ zero: 0 });
    assert.throws(() => reserveInventory(stock, [
      { sku, quantity: 1, unitPriceCents: 0 },
    ]), { name: 'RangeError', message: 'insufficient stock' });
    assert.deepEqual(stock, { zero: 0 });
  }
});

test('empty and invalid-only carts return fresh stock with no added keys', () => {
  const stock = Object.freeze({ a: 3 });
  for (const cart of [[], [null, { sku: 'a', quantity: 1.5, unitPriceCents: 0 }]]) {
    const remaining = reserveInventory(stock, cart);
    assert.deepEqual(remaining, { a: 3 });
    assert.notStrictEqual(remaining, stock);
  }
  assert.deepEqual(reserveInventory({}, []), {});
});

test('special own SKU keys and null-prototype stock reserve safely', () => {
  const stock = Object.freeze(Object.assign(Object.create(null), {
    ['__proto__']: 3, constructor: 2, toString: 1,
  }));
  const cart = ['__proto__', 'constructor', 'toString'].map(sku => ({
    sku, quantity: 1, unitPriceCents: 0,
  }));
  const remaining = reserveInventory(stock, cart);
  assert.deepEqual(remaining, { ['__proto__']: 2, constructor: 1, toString: 0 });
  assert.strictEqual(Object.getPrototypeOf(remaining), Object.prototype);
  assert.equal(stock.__proto__, 3);
});

test('SKU case stays distinct and repeated reservations produce independent objects', () => {
  const stock = Object.freeze({ a: 2, A: 5 });
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 10 }];
  const first = reserveInventory(stock, cart);
  first.a = 99;
  assert.deepEqual(reserveInventory(stock, cart), { a: 1, A: 5 });
  assert.deepEqual(stock, { a: 2, A: 5 });
});

