test('refunds normalized revised pricing and matches receipts, CSV, and summary', () => {
  const order = Object.freeze({
    id: 'return,1',
    status: 'delivered',
    deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 5, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: -1, unitPriceCents: 999 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
  });
  const context = Object.freeze({ nowDay: 17 });
  const before = structuredClone({ order, context });
  const result = returnOrder(order, context);
  assert.deepEqual(result, {
    eligible: true, reason: 'eligible', refundCents: 660, currency: 'USD',
  });
  const receipt = buildReceipt(order);
  assert.equal(result.refundCents, receipt.totalCents);
  assert.equal(result.currency, receipt.currency);
  assert.equal(renderCSV([receipt]), 'orderId,totalCents,currency\n"return,1",660,USD');
  assert.deepEqual(formatSummary([receipt]), { orders: 1, totalCents: 660, units: 9 });
  result.refundCents = 0;
  assert.equal(returnOrder(order, context).refundCents, 660);
  assert.deepEqual({ order, context }, before);
});

