    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 1 },
      { sku: 'b', quantity: 1, unitPriceCents: 14 },
    ],
    options: { couponPercent: 30 },
  };
  assert.deepEqual(returnOrder(order, { nowDay: 0 }), {
    eligible: true, reason: 'eligible', refundCents: 12, currency: 'USD',
  });
});

test('handles default options, free carts, and shipping-only refunds', () => {
  for (const [cart, options, refundCents] of [
    [[{ sku: 'a', quantity: 2, unitPriceCents: 101 }], undefined, 236],
    [[], undefined, 0],
    [[{ sku: 'gift', quantity: 5, unitPriceCents: 0 }], undefined, 0],
    [[], { shippingCents: 99 }, 99],
  ]) {
    assert.deepEqual(returnOrder({ status: 'delivered', deliveredDay: 0, cart, options }, {
      nowDay: 7,
    }), { eligible: true, reason: 'eligible', refundCents, currency: 'USD' });
  }
});

test('ineligible returns retain the rejection reason and skip pricing', () => {
  for (const [status, deliveredDay, nowDay, reason] of [
    ['pending', -1, 20, 'status'],
    ['delivered', -1, 20, 'date'],
    ['delivered', 10, 9, 'date'],
    ['delivered', 10, 18, 'window'],
  ]) {
    const order = Object.freeze({
      status, deliveredDay,
      get cart() { throw new Error('ineligible cart must not be priced'); },
      get options() { throw new Error('ineligible options must not be read'); },
