// Both pipeline workers edit this module. Preserve the other worker's exports.

import { buildReceipt } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { priceOrder } from './cart.mjs';
import { canReturn } from './returns.mjs';

export function fulfillOrder(order, stock) {
  return {
    receipt: buildReceipt(order),
    stock: reserveInventory(stock, order.cart),
  };
}

export function returnOrder(order, context) {
  const eligibility = canReturn(order, context);
  return {
    ...eligibility,
    refundCents: eligibility.eligible ? priceOrder(order.cart, order.options).totalCents : 0,
    currency: 'USD',
  };
}

receipt.mjs.text:
// Receipt and CSV adapters.

import { normalizeCart, priceOrder } from './cart.mjs';

export function buildReceipt(order) {
  const itemCount = normalizeCart(order.cart).reduce(
    (count, { quantity }) => count + quantity,
    0,
  );

  return {
    orderId: order.id,
    ...priceOrder(order.cart, order.options),
    itemCount,
    currency: 'USD',
  };
}

function csvField(value) {
  const field = String(value);
  return /[,"\r\n]/.test(field) ? `"${field.replaceAll('"', '""')}"` : field;
}

export function renderCSV(receipts) {
  const rows = receipts.map(({ orderId, totalCents, currency }) =>
    [orderId, totalCents, currency].map(csvField).join(','),
  );
  return ['orderId,totalCents,currency', ...rows].join('\n');
}

