cart.mjs.text:
// Cart normalization and price calculation. Implement the requested exports here.

export function normalizeCart(cart) {
  const normalized = [];
  const bySku = new Map();

  for (const line of cart) {
    if (line == null) continue;
    const { sku, quantity, unitPriceCents } = line;
    if (typeof sku !== 'string' || !sku.trim() ||
        !Number.isInteger(quantity) || quantity <= 0 ||
        !Number.isInteger(unitPriceCents) || unitPriceCents < 0) {
      continue;
    }

    const trimmedSku = sku.trim();
    let byPrice = bySku.get(trimmedSku);
    if (!byPrice) {
      byPrice = new Map();
      bySku.set(trimmedSku, byPrice);
    }

    const existing = byPrice.get(unitPriceCents);
    if (existing) {
      existing.quantity += quantity;
    } else {
      const item = { sku: trimmedSku, quantity, unitPriceCents };
      byPrice.set(unitPriceCents, item);
      normalized.push(item);
    }
  }

  return normalized;
}

export function priceOrder(cart, options = {}) {
  const { couponPercent = 0, shippingCents = 0 } = options;
  const subtotalCents = normalizeCart(cart).reduce(
    (subtotal, { quantity, unitPriceCents }) => subtotal + quantity * unitPriceCents,
    0,
  );
  const cappedCouponPercent = Math.min(30, Math.max(0, couponPercent));
  const discountCents = Math.round(subtotalCents * cappedCouponPercent / 100);
  const taxCents = Math.round((subtotalCents - discountCents) * 17 / 100);
  const totalCents = subtotalCents - discountCents + taxCents + shippingCents;

  return { subtotalCents, discountCents, taxCents, shippingCents, totalCents };
}

