import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('fulfillment returns exact receipt and stock using the revised release policy', () => {
  const order = Object.freeze({
    id: 'paid,1',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 5, unitPriceCents: 0 }),
      Object.freeze({ sku: 'missing', quantity: -1, unitPriceCents: 999 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
    status: 'pending',
    deliveredDay: 0,
  });
  const stock = Object.freeze({ a: 5, free: 5, untouched: 8 });
  const before = structuredClone({ order, stock });
  const fulfilled = fulfillOrder(order, stock);
  const expected = {
    receipt: {
      orderId: 'paid,1', subtotalCents: 500, discountCents: 150, taxCents: 60,
      shippingCents: 250, totalCents: 660, itemCount: 9, currency: 'CAD',
    },
    stock: { a: 1, free: 0, untouched: 8 },
  };
  assert.deepEqual(fulfilled, expected);
  assert.deepEqual({ order, stock }, before);
  assert.equal(renderCSV([fulfilled.receipt]),
    'orderId,totalCents,currency\r\n"paid,1",660,CAD');
  assert.deepEqual(formatSummary([fulfilled.receipt]), {
    orders: 1, totalCents: 660, units: 9,
  });
  fulfilled.receipt.totalCents = 0;
  fulfilled.stock.a = 0;
  assert.deepEqual(fulfillOrder(order, stock), expected);
});

test('fulfillment propagates shortage and preserves every input on failure', () => {
  const order = {
    id: 'short',
    cart: [
      { sku: 'enough', quantity: 1, unitPriceCents: 100 },
      { sku: 'short', quantity: 2, unitPriceCents: 100 },
      { sku: ' short ', quantity: 2, unitPriceCents: 200 },
    ],
    options: { couponPercent: 30, shippingCents: 99 },
  };
  const stock = { enough: 1, short: 3 };
  const before = structuredClone({ order, stock });
  assert.throws(() => fulfillOrder(order, stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ order, stock }, before);
});

test('empty fulfillment uses default pricing and returns fresh stock', () => {
  const stock = Object.freeze({ a: 1 });
  const fulfilled = fulfillOrder({ id: 0, cart: [] }, stock);
  assert.deepEqual(fulfilled, {
    receipt: {
      orderId: 0, subtotalCents: 0, discountCents: 0, taxCents: 0,
      shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'CAD',
    },
    stock: { a: 1 },
  });
  assert.notStrictEqual(fulfilled.stock, stock);
});

inventory.mjs.text:
// Atomic reservation adapter.

import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const quantities = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    quantities.set(sku, (quantities.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of quantities) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const remaining = { ...stock };
  for (const [sku, quantity] of quantities) {
    remaining[sku] -= quantity;
  }
  return remaining;
}

