import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('builds exact receipt fields from normalized quantities and revised pricing', () => {
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 5, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: -1, unitPriceCents: 999 }),
      Object.freeze({ sku: ' ', quantity: 10, unitPriceCents: 999 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 250 }),
    status: 'pending',
    deliveredDay: 0,
    extra: 'ignored',
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 500, discountCents: 150, taxCents: 60,
    shippingCents: 250, totalCents: 660, itemCount: 9, currency: 'CAD',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.deepEqual(order, before);
  receipt.totalCents = 0;
  const again = buildReceipt(order);
  assert.notStrictEqual(again, receipt);
  assert.deepEqual(again, expected);
});

test('builds empty receipts with default options and preserves numeric IDs', () => {
  assert.deepEqual(buildReceipt({ id: 0, cart: [] }), {
    orderId: 0, subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'CAD',
  });
  assert.deepEqual(buildReceipt({ id: '', cart: [null], options: { shippingCents: 99 } }), {
    orderId: '', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 99, totalCents: 99, itemCount: 0, currency: 'CAD',
  });
});

test('receipts use order-level discount rounding and tax after the rounded discount', () => {
  const receipt = buildReceipt({
    id: 'rounding',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 1 },
      { sku: 'b', quantity: 1, unitPriceCents: 14 },
    ],
    options: { couponPercent: 30 },
  });
  assert.deepEqual(receipt, {
    orderId: 'rounding', subtotalCents: 15, discountCents: 5, taxCents: 2,
    shippingCents: 0, totalCents: 12, itemCount: 2, currency: 'CAD',
  });
});

test('empty CSV contains only the required header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves row order, selects required fields, and uses CRLF without a trailing newline', () => {
  const receipts = Object.freeze([
    Object.freeze({ currency: 'CAD', itemCount: 2, totalCents: 1069, orderId: 'first' }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'CAD', extra: 'ignored' }),
    Object.freeze({ orderId: '', totalCents: 99, currency: 'CAD' }),
  ]);
  const before = structuredClone(receipts);
  const expected = 'orderId,totalCents,currency\r\nfirst,1069,CAD\r\n0,0,CAD\r\n,99,CAD';
  assert.equal(renderCSV(receipts), expected);
  assert.equal(renderCSV(receipts).endsWith('\n'), false);
  assert.equal(renderCSV(receipts).endsWith('\r'), false);
  assert.equal(renderCSV(receipts), expected);
  assert.deepEqual(receipts, before);
});

test('CSV quotes commas, doubles quotes, and preserves embedded LF and CR', () => {
  const ids = ['a,b', 'a"b', 'a\nb', 'a\rb', 'a\r\nb', 'a,"b"\nc'];
  const receipts = ids.map(orderId => ({ orderId, totalCents: 0, currency: 'CAD' }));
  assert.equal(renderCSV(receipts), [
    'orderId,totalCents,currency',
    '"a,b",0,CAD',
    '"a""b",0,CAD',
    '"a\nb",0,CAD',
    '"a\rb",0,CAD',
    '"a\r\nb",0,CAD',
    '"a,""b""\nc",0,CAD',
  ].join('\r\n'));
  assert.equal(renderCSV([{ orderId: 'a', totalCents: 1, currency: 'U,"SD\n' }]),
    'orderId,totalCents,currency\r\na,1,"U,""SD\n"');
});

test('built receipts feed CSV and summary with consistent totals and units', () => {
  const receipts = [
    buildReceipt({
      id: 'paid,1', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 500 }],
      options: { couponPercent: 30, shippingCents: 250 },
    }),
    buildReceipt({ id: 'free', cart: [{ sku: 'gift', quantity: 5, unitPriceCents: 0 }] }),
  ];
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"paid,1",1069,CAD\r\nfree,0,CAD');
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 1069, units: 7 });
});

returns.mjs.text:
// Return eligibility policy.

export function canReturn(order, { nowDay }) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  const { deliveredDay } = order;
  if (!Number.isInteger(deliveredDay) || deliveredDay < 0 ||
      !Number.isInteger(nowDay) || nowDay < 0 || nowDay < deliveredDay) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - deliveredDay > 9) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

