import { buildReceipt, renderCSV } from './receipt.mjs';

function freeze(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}

test('receipt uses revised pricing and normalized units with exact shape and frozen inputs', () => {
  const order = freeze({
    id: 'order-1', status: 'delivered', deliveredDay: 3, extra: 'omit',
    cart: [
      { sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'keep' },
      { sku: 'a', quantity: 3, unitPriceCents: 100 },
      { sku: 'a', quantity: 1, unitPriceCents: 500 },
      { sku: 'free', quantity: 4, unitPriceCents: 0 },
      null,
      { sku: ' ', quantity: 10, unitPriceCents: 1000 },
      { sku: 'bad', quantity: 1.5, unitPriceCents: 1000 },
      { sku: 'bad', quantity: 2, unitPriceCents: -1 },
    ],
    options: { couponPercent: 80, shippingCents: 199, currency: 'EUR' },
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 1000, discountCents: 300,
    taxCents: 119, shippingCents: 199, totalCents: 1018,
    itemCount: 10, currency: 'USD',
  };
  const receipt = buildReceipt(order);
  assert.deepEqual(receipt, expected);
  assert.notStrictEqual(receipt, buildReceipt(order));
  receipt.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('receipt preserves order-level discount and tax rounding', () => {
  assert.deepEqual(buildReceipt({
    id: 7,
    cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 7 })),
    options: { couponPercent: 30, shippingCents: 100 },
  }), {
    orderId: 7, subtotalCents: 21, discountCents: 6, taxCents: 3,
    shippingCents: 100, totalCents: 118, itemCount: 3, currency: 'USD',
  });
});

test('receipt defaults options and handles empty, invalid-only and free carts', () => {
  assert.deepEqual(buildReceipt({
    id: 'default', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 100 }],
  }), {
    orderId: 'default', subtotalCents: 200, discountCents: 0, taxCents: 34,
    shippingCents: 0, totalCents: 234, itemCount: 2, currency: 'USD',
  });
  for (const [cart, itemCount] of [
    [[], 0], [[null, {}], 0], [[{ sku: 'free', quantity: 3, unitPriceCents: 0 }], 3],
  ]) {
    assert.deepEqual(buildReceipt({ id: 'empty', cart, options: { shippingCents: 99 } }), {
      orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
      shippingCents: 99, totalCents: 99, itemCount, currency: 'USD',
    });
  }
});

test('CSV empty input returns only the header', () => {
  assert.equal(renderCSV(Object.freeze([])), 'orderId,totalCents,currency');
});

test('CSV uses fixed columns and input row order with LF and no trailing newline', () => {
  const receipts = freeze([
    { currency: 'USD', totalCents: 117, orderId: 'second', itemCount: 99 },
    { totalCents: 0, orderId: 0, currency: 'USD', extra: 'omit' },
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\nsecond,117,USD\n0,0,USD');
  assert.deepEqual(receipts, before);
});

test('CSV quotes special characters in every field and doubles embedded quotes', () => {
  const receipts = freeze([
    { orderId: 'a,b', totalCents: '1,000', currency: 'U"SD' },
    { orderId: 'say "hi" twice ""', totalCents: '1\n2', currency: 'U\rSD' },
    { orderId: 'a\r\nb', totalCents: 0, currency: 'USD' },
    { orderId: ' café ', totalCents: 5, currency: 'USD' },
    { orderId: '', totalCents: 0, currency: '' },
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\n' +
    '"a,b","1,000","U""SD"\n' +
    '"say ""hi"" twice """"","1\n2","U\rSD"\n' +
    '"a\r\nb",0,USD\n' +
    ' café ,5,USD\n' +
    ',0,');
  assert.deepEqual(receipts, before);
});

test('built receipts render directly to CSV', () => {
  const receipt = buildReceipt(freeze({
    id: 'order,"one"', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 100 }],
    options: { couponPercent: 20, shippingCents: 10 },
  }));
  assert.equal(renderCSV([receipt]), 'orderId,totalCents,currency\n"order,""one""",104,USD');
});

