import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder } from './pipeline.mjs';

function freeze(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}

test('fulfillment combines revised receipt pricing with inventory demand across prices', () => {
  const order = freeze({
    id: 'order-1', status: 'pending', deliveredDay: 0, extra: 'omit',
    cart: [
      { sku: ' a ', quantity: 2, unitPriceCents: 100 },
      { sku: 'a', quantity: 3, unitPriceCents: 100 },
      { sku: 'a', quantity: 1, unitPriceCents: 500 },
      { sku: 'free', quantity: 4, unitPriceCents: 0 },
      null, { sku: 'missing', quantity: 0, unitPriceCents: 100 },
    ],
    options: { couponPercent: 80, shippingCents: 199 },
  });
  const stock = freeze({ a: 6, free: 5, unrelated: 8 });
  const before = structuredClone({ order, stock });
  const expected = {
    receipt: {
      orderId: 'order-1', subtotalCents: 1000, discountCents: 300,
      taxCents: 119, shippingCents: 199, totalCents: 1018,
      itemCount: 10, currency: 'USD',
    },
    stock: { a: 0, free: 1, unrelated: 8 },
  };
  const result = fulfillOrder(order, stock);
  assert.deepEqual(result, expected);
  assert.notStrictEqual(result.stock, stock);
  result.stock.a = 99;
  result.receipt.totalCents = 0;
  assert.deepEqual(fulfillOrder(order, stock), expected);
  assert.deepEqual({ order, stock }, before);
});

test('fulfillment propagates a late inventory shortage without mutating inputs', () => {
  const order = {
    id: 'shortage',
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 100 },
      { sku: 'missing', quantity: 1, unitPriceCents: 200 },
    ],
    options: { couponPercent: 20, shippingCents: 10 },
  };
  const stock = { a: 3 };
  const before = structuredClone({ order, stock });
  assert.throws(() => fulfillOrder(order, stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ order, stock }, before);
  freeze(order);
  freeze(stock);
  assert.throws(() => fulfillOrder(order, stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
});

test('fulfillment defaults options and handles empty and invalid-only carts', () => {
  for (const cart of [[], [null, {}]]) {
    const order = freeze({ id: 'empty', cart });
    const stock = freeze({ unrelated: 5 });
    const result = fulfillOrder(order, stock);
    assert.deepEqual(result, {
      receipt: {
        orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
        shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'USD',
      },
      stock: { unrelated: 5 },
    });
    assert.notStrictEqual(result.stock, stock);
  }
});

test('fulfillment keeps once-per-order rounding and excludes shipping from tax', () => {
  const order = freeze({
    id: 'rounding',
    cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 7 })),
    options: { couponPercent: 30, shippingCents: 100 },
  });
  assert.deepEqual(fulfillOrder(order, freeze({ a: 1, b: 1, c: 1 })), {
    receipt: {
      orderId: 'rounding', subtotalCents: 21, discountCents: 6, taxCents: 3,
      shippingCents: 100, totalCents: 118, itemCount: 3, currency: 'USD',
    },
    stock: { a: 0, b: 0, c: 0 },
  });
});

inventory.mjs.text:
// Atomic reservation adapter.
import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const demand = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    demand.set(sku, (demand.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of demand) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of demand) {
    reserved[sku] = stock[sku] - quantity;
  }
  return reserved;
}

