import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';

test('drops invalid lines and accepts a trimmed sku with zero price', () => {
  const valid = { sku: '\t free \n', quantity: 2, unitPriceCents: 0 };
  const invalid = [null, undefined, false, 1, 'line', {},
    { ...valid, sku: '' }, { ...valid, sku: ' \t\n' },
    { ...valid, sku: 12 }, { ...valid, sku: new String('sku') },
    ...[0, -1, 1.5, NaN, Infinity, '2', null, undefined].map(
      quantity => ({ ...valid, quantity })),
    ...[-1, 0.5, NaN, Infinity, '0', null, undefined].map(
      unitPriceCents => ({ ...valid, unitPriceCents })),
  ];
  assert.deepEqual(normalizeCart([...invalid, valid]), [
    { sku: 'free', quantity: 2, unitPriceCents: 0 },
  ]);
  assert.deepEqual(normalizeCart(invalid), []);
});

test('merges only equal trimmed sku and price in first appearance order', () => {
  const cart = [
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 1, unitPriceCents: 100 },
    { sku: 'a', quantity: 3, unitPriceCents: 200 },
    { sku: 'a\t', quantity: 4, unitPriceCents: 100 },
    { sku: ' b ', quantity: 5, unitPriceCents: 100 },
    { sku: 'a', quantity: 6, unitPriceCents: 200 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ];
  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 6, unitPriceCents: 100 },
    { sku: 'b', quantity: 6, unitPriceCents: 100 },
    { sku: 'a', quantity: 9, unitPriceCents: 200 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ]);
});

test('handles special sku keys without collisions', () => {
  const cart = ['__proto__', 'constructor', 'toString', 'a:1', 'a'].map(
    sku => ({ sku, quantity: 1, unitPriceCents: 0 }));
  assert.deepEqual(normalizeCart([...cart, cart[0]]), [
    { sku: '__proto__', quantity: 2, unitPriceCents: 0 },
    ...cart.slice(1),
  ]);
});

test('returns fresh exact-shape objects and never mutates frozen input', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 5, extra: 'omit' }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 5 }),
    Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 7 }),
    null,
  ]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);
  assert.notStrictEqual(result, cart);
  assert.deepEqual(result, [
    { sku: 'a', quantity: 5, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 7 },
  ]);
  assert.notStrictEqual(result[0], cart[0]);
  assert.notStrictEqual(result[1], cart[2]);
  result[0].quantity = 99;
  result[1].sku = 'changed';
  assert.deepEqual(cart, before);
  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 5, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 7 },
  ]);
});

test('prices normalized quantities while dropping invalid lines', () => {
  const cart = [
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'a', quantity: 3, unitPriceCents: 100 },
    { sku: 'b', quantity: 2, unitPriceCents: 250 },
    { sku: 'a', quantity: 1, unitPriceCents: 600 },
    { sku: 'free', quantity: 3, unitPriceCents: 0 },
    null,
    { sku: ' ', quantity: 10, unitPriceCents: 1000 },
    { sku: 'bad', quantity: 1.5, unitPriceCents: 1000 },
    { sku: 'bad', quantity: 1, unitPriceCents: -100 },
  ];
  assert.deepEqual(priceOrder(cart, { couponPercent: 12.5, shippingCents: 99 }), {
    subtotalCents: 1600, discountCents: 200, taxCents: 238,
    shippingCents: 99, totalCents: 1737,
  });
});

test('defaults coupon and shipping to zero with an exact totals shape', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 100 }];
  const expected = {
    subtotalCents: 100, discountCents: 0, taxCents: 17,
    shippingCents: 0, totalCents: 117,
  };
  assert.deepEqual(priceOrder(cart), expected);
  assert.deepEqual(priceOrder(cart, {}), expected);
  assert.deepEqual(priceOrder(cart, { couponPercent: undefined, shippingCents: undefined }), expected);
  assert.deepEqual(priceOrder(cart, { shippingCents: 10 }), {
    ...expected, shippingCents: 10, totalCents: 127,
  });
});

test('clamps coupons to 0..30 and taxes only the discounted subtotal', () => {
  const cart = [{ sku: 'a', quantity: 2, unitPriceCents: 1000 }];
  for (const [couponPercent, discountCents, taxCents, totalCents] of [
    [-5, 0, 340, 2640],
    [0, 0, 340, 2640],
    [25, 500, 255, 2055],
    [30, 600, 238, 1938],
    [100, 600, 238, 1938],
