});

test('rounds discount once across the whole order rather than each line', () => {
  const cart = ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 1 }));
  assert.deepEqual(priceOrder(cart, { couponPercent: 30 }), {
    subtotalCents: 3, discountCents: 1, taxCents: 0,
    shippingCents: 0, totalCents: 2,
  });
