  const context = freeze({ nowDay: 10, extra: 'keep' });
  const before = structuredClone({ order, context });
  const expected = { eligible: true, reason: 'eligible', refundCents: 1018, currency: 'USD' };
  const result = returnOrder(order, context);
  assert.deepEqual(result, expected);
  assert.notStrictEqual(result, returnOrder(order, context));
  result.refundCents = 0;
