    line('missing', 1.5), line('missing', 1, -1)];
  assert.deepEqual(reserveInventory(stock, [...invalid, line('a', 1)]), { a: 1 });
  for (const cart of [[], invalid]) {
    const reserved = reserveInventory(stock, cart);
    assert.deepEqual(reserved, stock);
    assert.notStrictEqual(reserved, stock);
  }
});

test('inventory shortage is atomic for early and late SKUs and aggregated prices', () => {
  for (const cart of [
    [line('missing', 1), line('a', 1)],
    [line('a', 1), line('b', 3)],
    [line('a', 2), line('a', 2, 200)],
    [line('zero', 1, 0)],
  ]) {
    const stock = { a: 3, b: 2, zero: 0, unrelated: 7 };
    const before = structuredClone({ stock, cart });
    assert.throws(() => reserveInventory(stock, cart), {
      name: 'RangeError', message: 'insufficient stock',
    });
    assert.deepEqual({ stock, cart }, before);
    Object.freeze(stock);
    cart.forEach(Object.freeze);
    Object.freeze(cart);
    assert.throws(() => reserveInventory(stock, cart), {
      name: 'RangeError', message: 'insufficient stock',
    });
  }
});

test('inventory treats prototype names as ordinary SKUs with absent own stock equal to zero', () => {
  for (const sku of ['__proto__', 'constructor', 'toString']) {
    assert.throws(() => reserveInventory({}, [line(sku, 1)]), {
      name: 'RangeError', message: 'insufficient stock',
    });
  }
  const stock = Object.freeze(JSON.parse('{"__proto__":3,"constructor":2,"toString":1}'));
  const reserved = reserveInventory(stock, [
    line('__proto__', 2), line('constructor', 2), line('toString', 1),
  ]);
  assert.deepEqual(reserved, JSON.parse('{"__proto__":1,"constructor":0,"toString":0}'));
  assert.strictEqual(Object.getPrototypeOf(reserved), Object.prototype);
  assert.deepEqual(stock, JSON.parse('{"__proto__":3,"constructor":2,"toString":1}'));
});

