    id: 'default', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 100 }],
  }), {
    orderId: 'default', subtotalCents: 200, discountCents: 0, taxCents: 34,
    shippingCents: 0, totalCents: 234, itemCount: 2, currency: 'CAD',
  });
  for (const [cart, itemCount] of [
    [[], 0], [[null, {}], 0], [[{ sku: 'free', quantity: 3, unitPriceCents: 0 }], 3],
