});

test('CSV uses fixed columns and input row order with CRLF and no trailing newline', () => {
  const receipts = freeze([
    { currency: 'CAD', totalCents: 117, orderId: 'second', itemCount: 99 },
    { totalCents: 0, orderId: 0, currency: 'CAD', extra: 'omit' },
