test('CSV quotes special characters in every field and doubles embedded quotes', () => {
  const receipts = freeze([
    { orderId: 'a,b', totalCents: '1,000', currency: 'U"SD' },
    { orderId: 'say "hi" twice ""', totalCents: '1\n2', currency: 'U\rSD' },
    { orderId: 'a\r\nb', totalCents: 0, currency: 'CAD' },
