  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\n' +
    '"a,b","1,000","U""SD"\r\n' +
    '"say ""hi"" twice """"","1\n2","U\rSD"\r\n' +
    '"a\r\nb",0,CAD\r\n' +
    ' café ,5,CAD\r\n' +
    ',0,');
  assert.deepEqual(receipts, before);
});

test('built receipts render directly to CSV', () => {
  const receipt = buildReceipt(freeze({
    id: 'order,"one"', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 100 }],
    options: { couponPercent: 20, shippingCents: 10 },
