import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('integrated fulfillment, reporting and return agree on the revised total', () => {
  const order = Object.freeze({
    id: 'release,"one"', status: 'delivered', deliveredDay: 10,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 7 }),
      Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 7 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 80, shippingCents: 100 }),
  });
  const stock = Object.freeze({ a: 4, spare: 5 });
  const before = structuredClone({ order, stock });
  const result = fulfillOrder(order, stock);
  assert.deepEqual(result.stock, { a: 1, spare: 5 });
  const receipts = Object.freeze([Object.freeze(result.receipt)]);
  assert.deepEqual(formatSummary(receipts), { orders: 1, totalCents: 118, units: 3 });
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"release,""one""",118,CAD');
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 19 })), {
    eligible: true, reason: 'eligible', refundCents: result.receipt.totalCents, currency: 'CAD',
  });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 20 })), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'CAD',
  });
  assert.deepEqual({ order, stock }, before);
});

test('summary counts receipts and units separately and preserves frozen inputs', () => {
  assert.deepEqual(formatSummary(Object.freeze([])), { orders: 0, totalCents: 0, units: 0 });
  const receipts = Object.freeze([
    Object.freeze({ totalCents: 118, itemCount: 3 }),
    Object.freeze({ totalCents: 234, itemCount: 2 }),
    Object.freeze({ totalCents: 0, itemCount: 0 }),
  ]);
  const before = structuredClone(receipts);
  const expected = { orders: 3, totalCents: 352, units: 5 };
  const summary = formatSummary(receipts);
  assert.deepEqual(summary, expected);
  summary.units = 99;
  assert.deepEqual(formatSummary(receipts), expected);
  assert.deepEqual(receipts, before);
});

