import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { canReturn } from './returns.mjs';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { formatSummary } from './summary.mjs';

// Independent audit of the current PROJECT_PLAN.md contract; no code repairs.
test('audit: pricing and adapters agree across rounding and coupon boundaries', () => {
  for (let subtotal = 0; subtotal <= 100; subtotal++) {
    for (const couponPercent of [-1, 0, 0.5, 10, 12.5, 29.9, 30, 31, 100]) {
      for (const shippingCents of [0, 99]) {
        const cart = Object.freeze([
          Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: subtotal }),
          Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 0 }),
          null,
        ]);
        const options = Object.freeze({ couponPercent, shippingCents });
        const discount = Math.floor(subtotal * Math.min(30, Math.max(0, couponPercent)) / 100 + 0.5);
        const tax = Math.floor((subtotal - discount) * 17 / 100 + 0.5);
        const total = subtotal - discount + tax + shippingCents;
        const expectedPrice = {
          subtotalCents: subtotal, discountCents: discount, taxCents: tax,
          shippingCents, totalCents: total,
        };
        const order = Object.freeze({ id: 'audit', cart, options, status: 'delivered', deliveredDay: 0 });
        assert.deepEqual(priceOrder(cart, options), expectedPrice);
        const receipt = { orderId: 'audit', ...expectedPrice, itemCount: 3, currency: 'CAD' };
        assert.deepEqual(buildReceipt(order), receipt);
        assert.deepEqual(fulfillOrder(order, Object.freeze({ a: 4, spare: 2 })), {
          receipt, stock: { a: 1, spare: 2 },
        });
        assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 9 })), {
          eligible: true, reason: 'eligible', refundCents: total, currency: 'CAD',
        });
        assert.deepEqual(formatSummary(Object.freeze([Object.freeze(receipt)])), {
          orders: 1, totalCents: total, units: 3,
        });
      }
    }
  }
});

test('audit: return validation and refund policy across status/date combinations', () => {
  const days = [undefined, null, NaN, Infinity, '0', -1, 0.5, 0, 1, 7, 8, 9, 10, 19, 20];
  for (const status of [undefined, 'pending', 'Delivered', 'delivered']) {
    for (const deliveredDay of days) {
      for (const nowDay of days) {
        let reason = 'status';
        if (status === 'delivered') {
          reason = !Number.isInteger(deliveredDay) || deliveredDay < 0 ||
            !Number.isInteger(nowDay) || nowDay < 0 || nowDay < deliveredDay
            ? 'date' : nowDay - deliveredDay > 9 ? 'window' : 'eligible';
        }
        const eligible = reason === 'eligible';
        const order = Object.freeze({ status, deliveredDay, cart: Object.freeze([]) });
        const context = Object.freeze({ nowDay });
        assert.deepEqual(canReturn(order, context), { eligible, reason });
        assert.deepEqual(returnOrder(order, context), { eligible, reason, refundCents: 0, currency: 'CAD' });
      }
    }
  }
});

test('audit: normalized demand is atomic across prices and stock boundaries', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 5, extra: true }),
    Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 0 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 7 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 5 }),
    null, Object.freeze({ sku: 'missing', quantity: 0, unitPriceCents: 9 }),
  ]);
  const before = structuredClone(cart);
  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 3, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 0 },
    { sku: 'a', quantity: 1, unitPriceCents: 7 },
  ]);
  for (let a = 0; a <= 5; a++) {
    for (let b = 0; b <= 2; b++) {
      const stock = { a, b, spare: 9 };
      const snapshot = structuredClone(stock);
      if (a < 4 || b < 1) {
        assert.throws(() => reserveInventory(stock, cart), { name: 'RangeError', message: 'insufficient stock' });
        assert.throws(() => fulfillOrder({ id: 'audit', cart }, stock), { name: 'RangeError', message: 'insufficient stock' });
      } else {
        const result = reserveInventory(stock, cart);
        assert.notStrictEqual(result, stock);
        assert.deepEqual(result, { a: a - 4, b: b - 1, spare: 9 });
      }
      assert.deepEqual(stock, snapshot);
      assert.deepEqual(cart, before);
    }
  }
});

test('audit: CSV escapes every column while preserving embedded newline bytes', () => {
  const fields = ['', 'plain', 'comma,', 'quote"', 'CR\r', 'LF\n', 'CRLF\r\n', ',"\r\nend'];
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
  for (const field of fields) {
    const encoded = /[,"\r\n]/.test(field) ? '"' + field.split('"').join('""') + '"' : field;
    const receipts = Object.freeze([
      Object.freeze({ orderId: field, totalCents: field, currency: field }),
      Object.freeze({ orderId: 'last', totalCents: 0, currency: 'CAD' }),
    ]);
    assert.equal(renderCSV(receipts), `orderId,totalCents,currency\r\n${encoded},${encoded},${encoded}\r\nlast,0,CAD`);
  }
});

cart.mjs.text:
// Cart normalization and price calculation. Implement the requested exports here.

export function normalizeCart(cart) {
  const normalized = [];
  const bySku = new Map();

  for (const line of cart) {
    if (line === null || typeof line !== 'object') continue;
    const { sku, quantity, unitPriceCents } = line;
    if (
      typeof sku !== 'string' ||
      !Number.isInteger(quantity) || quantity <= 0 ||
      !Number.isInteger(unitPriceCents) || unitPriceCents < 0
    ) continue;

    const trimmedSku = sku.trim();
    if (trimmedSku.length === 0) continue;

    let byPrice = bySku.get(trimmedSku);
    if (!byPrice) {
      byPrice = new Map();
      bySku.set(trimmedSku, byPrice);
    }

    const existing = byPrice.get(unitPriceCents);
    if (existing) {
      existing.quantity += quantity;
    } else {
      const item = { sku: trimmedSku, quantity, unitPriceCents };
      byPrice.set(unitPriceCents, item);
      normalized.push(item);
    }
  }

  return normalized;
}

export function priceOrder(cart, options = {}) {
  const { couponPercent = 0, shippingCents = 0 } = options;
  const subtotalCents = normalizeCart(cart).reduce(
    (subtotal, line) => subtotal + line.quantity * line.unitPriceCents, 0);
  const cappedCouponPercent = Math.min(30, Math.max(0, couponPercent));
  const discountCents = Math.round(subtotalCents * cappedCouponPercent / 100);
  const taxCents = Math.round((subtotalCents - discountCents) * 17 / 100);
  const totalCents = subtotalCents - discountCents + taxCents + shippingCents;

  return { subtotalCents, discountCents, taxCents, shippingCents, totalCents };
}

