test('fulfillment keeps once-per-order rounding and excludes shipping from tax', () => {
  const order = freeze({
    id: 'rounding',
    cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 7 })),
    options: { couponPercent: 30, shippingCents: 100 },
  });
  assert.deepEqual(fulfillOrder(order, freeze({ a: 1, b: 1, c: 1 })), {
    receipt: {
      orderId: 'rounding', subtotalCents: 21, discountCents: 6, taxCents: 3,
      shippingCents: 100, totalCents: 118, itemCount: 3, currency: 'CAD',
    },
    stock: { a: 0, b: 0, c: 0 },
  });
});

