// Both pipeline workers edit this module. Preserve the other worker's exports.
import { buildReceipt } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { priceOrder } from './cart.mjs';
import { canReturn } from './returns.mjs';

export function fulfillOrder(order, stock) {
  return {
    receipt: buildReceipt(order),
    stock: reserveInventory(stock, order.cart),
  };
}

export function returnOrder(order, context) {
  const eligibility = canReturn(order, context);
  const refundCents = eligibility.eligible
    ? priceOrder(order.cart, order.options).totalCents
    : 0;
  return { ...eligibility, refundCents, currency: 'CAD' };
}

