import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('only exact delivered status passes, before date validation', () => {
  for (const status of [undefined, null, '', 'pending', 'returned', 'Delivered', 1]) {
    assert.deepEqual(canReturn({ status, deliveredDay: -1 }, { nowDay: -1 }), {
      eligible: false, reason: 'status',
    });
  }
  assert.deepEqual(canReturn({
    status: 'pending',
    get deliveredDay() { throw new Error('status must be checked first'); },
  }, { nowDay: 100 }), { eligible: false, reason: 'status' });
});

test('both days must be nonnegative integers, with date rejection before window', () => {
  for (const invalid of [undefined, null, -1, 0.5, NaN, Infinity, -Infinity, '0', false]) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: invalid }, { nowDay: 100 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: invalid }), {
      eligible: false, reason: 'date',
    });
  }
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 10 }, { nowDay: 9 }), {
    eligible: false, reason: 'date',
  });
});

test('delivery day through day 9 inclusive are eligible; day 10 and day 30 are rejected', () => {
  for (const deliveredDay of [0, 10]) {
    for (const elapsed of [0, 1, 6, 7, 8, 9, 10, 30]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, { nowDay: deliveredDay + elapsed }),
        elapsed <= 9
          ? { eligible: true, reason: 'eligible' }
          : { eligible: false, reason: 'window' });
    }
  }
});

test('eligibility leaves frozen inputs untouched on every outcome and returns fresh results', () => {
  for (const [status, deliveredDay, nowDay, expected] of [
    ['pending', 0, 0, { eligible: false, reason: 'status' }],
    ['delivered', 5, 4, { eligible: false, reason: 'date' }],
    ['delivered', 5, 15, { eligible: false, reason: 'window' }],
    ['delivered', 5, 14, { eligible: true, reason: 'eligible' }],
  ]) {
    const order = Object.freeze({ status, deliveredDay, extra: 'keep' });
    const context = Object.freeze({ nowDay, extra: 'keep' });
    const before = structuredClone({ order, context });
    const result = canReturn(order, context);
    assert.deepEqual(result, expected);
    assert.notStrictEqual(result, canReturn(order, context));
    result.reason = 'changed';
    assert.deepEqual(canReturn(order, context), expected);
    assert.deepEqual({ order, context }, before);
  }
});

