    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 200 }),
  ]);
  const before = structuredClone(cart);
  assert.throws(() => reserveInventory(stock, cart),
    { name: 'RangeError', message: 'insufficient stock' });
