test('missing and zero-count skus fail atomically even when another sku is available', () => {
  for (const sku of ['missing', 'zero']) {
    const stock = { first: 3, zero: 0 };
    const cart = [{ sku: 'first', quantity: 1, unitPriceCents: 10 },
      { sku, quantity: 1, unitPriceCents: 0 }];
    const before = structuredClone({ stock, cart });
    assert.throws(() => reserveInventory(stock, cart),
      { name: 'RangeError', message: 'insufficient stock' });
    assert.deepEqual({ stock, cart }, before);
  }
});

test('prototype-like skus are ordinary own stock keys and inherited keys are absent', () => {
  const stock = Object.freeze({ ['__proto__']: 2, constructor: 3, toString: 1 });
  const cart = ['__proto__', 'constructor', 'toString'].map(sku =>
    ({ sku, quantity: 1, unitPriceCents: 0 }));
  const result = reserveInventory(stock, cart);
  assert.deepEqual(result, { ['__proto__']: 1, constructor: 2, toString: 0 });
  assert.strictEqual(Object.getPrototypeOf(result), Object.prototype);
  for (const sku of ['__proto__', 'constructor', 'toString', 'inherited']) {
    const inheritedStock = Object.create({ inherited: 10 });
    assert.throws(() => reserveInventory(inheritedStock,
      [{ sku, quantity: 1, unitPriceCents: 0 }]),
    { name: 'RangeError', message: 'insufficient stock' });
  }
});

