// Summary adapter.

export function formatSummary(receipts) {
  let totalCents = 0;
  let units = 0;

  for (const receipt of receipts) {
    totalCents += receipt.totalCents;
    units += receipt.itemCount;
  }

  return { orders: receipts.length, totalCents, units };
}

