    Object.freeze({ orderId: 'a', totalCents: 709, itemCount: 2, currency: 'USD' }),
  ]);
  const expected = { orders: 1, totalCents: 709, units: 2 };
  const first = formatSummary(receipts);
  const second = formatSummary(receipts);
  assert.deepEqual(first, expected);
  assert.deepEqual(second, expected);
  assert.notStrictEqual(first, second);
  first.totalCents = 0;
  assert.deepEqual(formatSummary(receipts), expected);
  assert.deepEqual(receipts, [
    { orderId: 'a', totalCents: 709, itemCount: 2, currency: 'USD' },
  ]);
});

