import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';

test('drops invalid lines without coercing fields', () => {
  const valid = { sku: 'ok', quantity: 1, unitPriceCents: 0 };
  const invalid = [null, undefined, 0, false, 'sku', {},
    ...['', ' \t\n ', null, undefined, 42].map(sku => ({ ...valid, sku })),
    ...[0, -1, 1.5, '2', null, undefined, NaN, Infinity].map(quantity => ({ ...valid, quantity })),
    ...[-1, 1.5, '0', null, undefined, NaN, Infinity].map(unitPriceCents => ({ ...valid, unitPriceCents }))];
  assert.deepEqual(normalizeCart([...invalid, valid]), [valid]);
});

test('trims skus, merges only equal sku and price, and preserves first appearance', () => {
  const cart = [
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 1, unitPriceCents: 200 },
    { sku: 'a', quantity: 3, unitPriceCents: 101 },
    { sku: '\ta\n', quantity: 4, unitPriceCents: 100 },
    { sku: ' b ', quantity: 2, unitPriceCents: 200 },
    { sku: 'a', quantity: 5, unitPriceCents: 101 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ];
  assert.deepEqual(normalizeCart(cart), [
    { sku: 'a', quantity: 6, unitPriceCents: 100 },
    { sku: 'b', quantity: 3, unitPriceCents: 200 },
    { sku: 'a', quantity: 8, unitPriceCents: 101 },
    { sku: 'A', quantity: 1, unitPriceCents: 100 },
  ]);
});

test('handles arbitrary sku strings and zero prices without key collisions', () => {
  const cart = [
    { sku: '__proto__', quantity: 1, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: 'a:1', quantity: 3, unitPriceCents: 2 },
    { sku: 'a', quantity: 4, unitPriceCents: 12 },
    { sku: ' __proto__ ', quantity: 5, unitPriceCents: 0 },
  ];
  assert.deepEqual(normalizeCart(cart), [
    { sku: '__proto__', quantity: 6, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: 'a:1', quantity: 3, unitPriceCents: 2 },
    { sku: 'a', quantity: 4, unitPriceCents: 12 },
  ]);
});

test('accepts frozen input and returns fresh exact-shaped objects on every call', () => {
  const first = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 0, extra: 'ignored' });
  const second = Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 0 });
  const cart = Object.freeze([first, null, second]);
  const result = normalizeCart(cart);
  assert.deepEqual(result, [{ sku: 'a', quantity: 5, unitPriceCents: 0 }]);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], first);
  assert.notStrictEqual(result[0], second);
  result[0].quantity = 99;
  result.push({ sku: 'new', quantity: 1, unitPriceCents: 0 });
  assert.deepEqual(normalizeCart(cart), [{ sku: 'a', quantity: 5, unitPriceCents: 0 }]);
  assert.deepEqual(cart, [
    { sku: ' a ', quantity: 2, unitPriceCents: 0, extra: 'ignored' },
    null,
    { sku: 'a', quantity: 3, unitPriceCents: 0 },
  ]);
});

test('prices empty carts with default options and shipping only', () => {
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 0, totalCents: 0,
  });
  assert.deepEqual(priceOrder([], { couponPercent: 35, shippingCents: 123 }), {
    subtotalCents: 0, discountCents: 0, taxCents: 0, shippingCents: 123, totalCents: 123,
  });
});

test('prices normalized lines with zero defaults and 9 percent tax', () => {
  const cart = [
    null,
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'a', quantity: 3, unitPriceCents: 100 },
    { sku: 'a', quantity: 1, unitPriceCents: 200 },
    { sku: 'free', quantity: 1, unitPriceCents: 0 },
    { sku: 'invalid', quantity: 0, unitPriceCents: 1000 },
    { sku: ' ', quantity: 1, unitPriceCents: 1000 },
  ];
  const expected = {
    subtotalCents: 700, discountCents: 0, taxCents: 63, shippingCents: 0, totalCents: 763,
  };
  assert.deepEqual(priceOrder(cart), expected);
  assert.deepEqual(priceOrder(cart, {}), expected);
});

test('clamps coupons to 0 through 35 percent and accepts fractional percentages', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  for (const [couponPercent, discountCents, taxCents, totalCents] of [
    [-5, 0, 90, 1090], [0, 0, 90, 1090], [12.5, 125, 79, 954],
    [20, 200, 72, 872], [35, 350, 59, 709], [99, 350, 59, 709],
  ]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 1000, discountCents, taxCents, shippingCents: 0, totalCents,
    });
  }
});

test('rounds the discount once across the entire order, including half cents', () => {
  const cart = ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 1 }));
  assert.deepEqual(priceOrder(cart, { couponPercent: 35 }), {
    subtotalCents: 3, discountCents: 1, taxCents: 0, shippingCents: 0, totalCents: 2,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 10 }],
    { couponPercent: 35 }), {
    subtotalCents: 10, discountCents: 4, taxCents: 1, shippingCents: 0, totalCents: 7,
  });
});

test('taxes the subtotal after the rounded discount and excludes shipping', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 101 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 35, shippingCents: 1000 }), {
    subtotalCents: 101, discountCents: 35, taxCents: 6, shippingCents: 1000, totalCents: 1072,
  });
  // Using the unrounded discount here would round tax to 6 rather than 5.
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 94 }],
    { couponPercent: 34.9 }), {
    subtotalCents: 94, discountCents: 33, taxCents: 5, shippingCents: 0, totalCents: 66,
  });
});

test('rounds tax once per order, including half cents', () => {
  const cart = ['a', 'b'].map(sku => ({ sku, quantity: 1, unitPriceCents: 6 }));
  assert.deepEqual(priceOrder(cart), {
    subtotalCents: 12, discountCents: 0, taxCents: 1, shippingCents: 0, totalCents: 13,
  });
  assert.deepEqual(priceOrder([{ sku: 'a', quantity: 1, unitPriceCents: 50 }]), {
    subtotalCents: 50, discountCents: 0, taxCents: 5, shippingCents: 0, totalCents: 55,
  });
});

test('pricing accepts frozen input and returns fresh exact-shaped totals', () => {
  const line = Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 });
  const cart = Object.freeze([line]);
  const options = Object.freeze({ couponPercent: 35, shippingCents: 25 });
  const expected = {
    subtotalCents: 202, discountCents: 71, taxCents: 12, shippingCents: 25, totalCents: 168,
  };
  const first = priceOrder(cart, options);
  const second = priceOrder(cart, options);
  assert.deepEqual(first, expected);
  assert.deepEqual(second, expected);
  assert.notStrictEqual(first, second);
  first.totalCents = 0;
  assert.deepEqual(priceOrder(cart, options), expected);
  assert.deepEqual(cart, [{ sku: ' a ', quantity: 2, unitPriceCents: 101 }]);
  assert.deepEqual(options, { couponPercent: 35, shippingCents: 25 });
});

