import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder } from './pipeline.mjs';

test('fulfillment composes revised receipt pricing and atomic inventory without mutation', () => {
  const order = Object.freeze({
    id: 'order-1', status: 'pending', deliveredDay: 5,
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 1, unitPriceCents: 0 }),
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 100 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 1000 }),
  });
  const stock = Object.freeze({ a: 6, free: 2, untouched: 9 });
  const before = structuredClone({ order, stock });
  const expected = {
    receipt: {
      orderId: 'order-1', subtotalCents: 700, discountCents: 245, taxCents: 41,
      shippingCents: 1000, totalCents: 1496, itemCount: 7, currency: 'USD',
    },
    stock: { a: 0, free: 1, untouched: 9 },
  };
  const first = fulfillOrder(order, stock);
  const second = fulfillOrder(order, stock);
  assert.deepEqual(first, expected);
  assert.deepEqual(second, expected);
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first.receipt, second.receipt);
  assert.notStrictEqual(first.stock, stock);
  assert.notStrictEqual(first.stock, second.stock);
  assert.deepEqual({ order, stock }, before);
});

test('empty fulfillment preserves stock and supports default and shipping-only receipts', () => {
  const stock = Object.freeze({ a: 2 });
  for (const shippingCents of [0, 25]) {
    const order = { id: 'empty', cart: [] };
    if (shippingCents) order.options = { shippingCents };
    assert.deepEqual(fulfillOrder(order, stock), {
      receipt: { orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
        shippingCents, totalCents: shippingCents, itemCount: 0, currency: 'USD' },
      stock: { a: 2 },
    });
  }
});

test('insufficient fulfillment throws without mutating stock or order', () => {
  const stock = { first: 5, a: 2 };
  const order = { id: 'short', options: { couponPercent: 35, shippingCents: 25 },
    cart: [{ sku: 'first', quantity: 1, unitPriceCents: 1 },
      { sku: 'a', quantity: 2, unitPriceCents: 100 },
      { sku: 'a', quantity: 1, unitPriceCents: 200 }] };
  const before = structuredClone({ stock, order });
  assert.throws(() => fulfillOrder(order, stock),
    { name: 'RangeError', message: 'insufficient stock' });
  assert.deepEqual({ stock, order }, before);
});

