import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('builds empty receipts with default pricing and shipping only', () => {
  const expected = {
    orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'ILS',
  };
  assert.deepEqual(buildReceipt({ id: 'empty', cart: [] }), expected);
  assert.deepEqual(buildReceipt({
    id: 'empty', cart: [null, { sku: ' ', quantity: 1, unitPriceCents: 100 }],
    options: { shippingCents: 123 },
  }), { ...expected, shippingCents: 123, totalCents: 123 });
});

test('builds exact receipts from normalized quantities and revised pricing without mutation', () => {
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100, extra: 'ignored' }),
      Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
      Object.freeze({ sku: 'free', quantity: 1, unitPriceCents: 0 }),
      Object.freeze({ sku: 'bad', quantity: 0, unitPriceCents: 1000 }),
      Object.freeze({ sku: 'bad', quantity: 9, unitPriceCents: -1 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 1000 }),
    status: 'pending', deliveredDay: 5, currency: 'ignored',
  });
  const before = structuredClone(order);
  const expected = {
    orderId: 'order-1', subtotalCents: 700, discountCents: 245, taxCents: 41,
    shippingCents: 1000, totalCents: 1496, itemCount: 7, currency: 'ILS',
  };
  const first = buildReceipt(order);
  const second = buildReceipt(order);
  assert.deepEqual(first, expected);
  assert.deepEqual(second, expected);
  assert.notStrictEqual(first, second);
  first.totalCents = 0;
  assert.deepEqual(buildReceipt(order), expected);
  assert.deepEqual(order, before);
});

test('receipts inherit order-level rounding and tax after rounded discounts', () => {
  assert.deepEqual(buildReceipt({
    id: 0, cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 1 })),
    options: { couponPercent: 35 },
  }), {
    orderId: 0, subtotalCents: 3, discountCents: 1, taxCents: 0,
    shippingCents: 0, totalCents: 2, itemCount: 3, currency: 'ILS',
  });
  assert.deepEqual(buildReceipt({
    id: 'fractional', cart: [{ sku: 'a', quantity: 1, unitPriceCents: 94 }],
    options: { couponPercent: 34.9, shippingCents: 25 },
  }), {
    orderId: 'fractional', subtotalCents: 94, discountCents: 33, taxCents: 5,
    shippingCents: 25, totalCents: 91, itemCount: 1, currency: 'ILS',
  });
});

test('empty CSV contains only the header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves receipt order and duplicates with CRLF separators and no trailing newline', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a', totalCents: 1496, currency: 'ILS', itemCount: 7 }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'ILS' }),
    Object.freeze({ orderId: 'a', totalCents: 91, currency: 'ILS' }),
    Object.freeze({ orderId: '', totalCents: 123, currency: 'ILS' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\na,1496,ILS\r\n0,0,ILS\r\na,91,ILS\r\n,123,ILS');
  assert.deepEqual(receipts, before);
});

test('CSV quotes commas, doubles embedded quotes and preserves embedded newlines', () => {
  for (const [orderId, escaped] of [
    ['a,b', '"a,b"'],
    ['a"b', '"a""b"'],
    ['a\nb', '"a\nb"'],
    ['a\rb', '"a\rb"'],
    ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\nc', '"a,""b""\nc"'],
    ['"', '""""'],
    [' café ', ' café '],
  ]) {
    assert.equal(renderCSV([{ orderId, totalCents: 0, currency: 'ILS' }]),
      `orderId,totalCents,currency\r\n${escaped},0,ILS`);
  }
});

test('built receipts feed CSV and the existing summary adapter', () => {
  const receipts = [
    buildReceipt({ id: 'paid,1', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 101 }],
      options: { couponPercent: 35, shippingCents: 25 } }),
    buildReceipt({ id: 'empty', cart: [] }),
  ];
  assert.equal(renderCSV(receipts), 'orderId,totalCents,currency\r\n"paid,1",168,ILS\r\nempty,0,ILS');
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 168, units: 2 });
});

