import { test } from 'node:test';
import assert from 'node:assert/strict';
import { returnOrder } from './pipeline.mjs';

test('eligible return refunds normalized totals with the revised policy and shipping', () => {
  const order = {
    status: 'delivered', deliveredDay: 20,
    cart: [null,
      { sku: ' a ', quantity: 1, unitPriceCents: 101 },
      { sku: 'a', quantity: 1, unitPriceCents: 101 },
      { sku: 'invalid', quantity: 0, unitPriceCents: 1000 },
    ],
    options: { couponPercent: 99, shippingCents: 25 },
  };
  // Subtotal 202, capped discount 71, tax 12 on 131, plus shipping 25.
  assert.deepEqual(returnOrder(order, { nowDay: 30 }), {
    eligible: true, reason: 'eligible', refundCents: 168, currency: 'ILS',
  });
});

test('return refunds inherit once-per-order rounding and tax after rounded discount', () => {
  const order = { status: 'delivered', deliveredDay: 0 };
  assert.deepEqual(returnOrder({ ...order,
    cart: ['a', 'b', 'c'].map(sku => ({ sku, quantity: 1, unitPriceCents: 1 })),
    options: { couponPercent: 35 },
  }, { nowDay: 0 }), { eligible: true, reason: 'eligible', refundCents: 2, currency: 'ILS' });
  assert.deepEqual(returnOrder({ ...order,
    cart: [{ sku: 'a', quantity: 1, unitPriceCents: 94 }],
    options: { couponPercent: 34.9, shippingCents: 7 },
  }, { nowDay: 10 }), { eligible: true, reason: 'eligible', refundCents: 73, currency: 'ILS' });
});

test('eligible returns use pricing defaults for empty and populated carts', () => {
  for (const [cart, refundCents] of [
    [[], 0], [[{ sku: 'a', quantity: 1, unitPriceCents: 100 }], 109],
  ]) {
    assert.deepEqual(returnOrder({ status: 'delivered', deliveredDay: 0, cart }, { nowDay: 0 }),
      { eligible: true, reason: 'eligible', refundCents, currency: 'ILS' });
  }
});

test('return pipeline refunds days 10 through 12 and rejects day 13 in ILS', () => {
  for (const deliveredDay of [0, 20]) {
    const order = Object.freeze({
      status: 'delivered', deliveredDay,
      cart: Object.freeze([Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 101 })]),
      options: Object.freeze({ couponPercent: 99, shippingCents: 25 }),
    });
    for (const elapsed of [10, 11, 12, 13]) {
      const eligible = elapsed <= 12;
      assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: deliveredDay + elapsed })), {
        eligible, reason: eligible ? 'eligible' : 'window',
        refundCents: eligible ? 168 : 0, currency: 'ILS',
      });
    }
  }
});

test('ineligible returns preserve each reason and skip cart and options access', () => {
  for (const [status, deliveredDay, nowDay, reason] of [
    ['pending', -1, -1, 'status'],
    ['delivered', -1, 0, 'date'],
    ['delivered', 10, 9, 'date'],
    ['delivered', 10, 23, 'window'],
  ]) {
    const order = Object.freeze({
      status, deliveredDay,
      get cart() { throw new Error('ineligible returns must not be priced'); },
      get options() { throw new Error('ineligible returns must not access pricing options'); },
    });
    assert.deepEqual(returnOrder(order, Object.freeze({ nowDay })),
      { eligible: false, reason, refundCents: 0, currency: 'ILS' });
  }
});

test('return pipeline accepts frozen inputs and returns fresh exact-shaped results', () => {
  const order = Object.freeze({
    id: 'order-1', status: 'delivered', deliveredDay: 5,
    cart: Object.freeze([Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 })]),
    options: Object.freeze({ couponPercent: 35, shippingCents: 25 }),
  });
  const context = Object.freeze({ nowDay: 15 });
  const before = structuredClone({ order, context });
  const first = returnOrder(order, context);
  const second = returnOrder(order, context);
  const expected = { eligible: true, reason: 'eligible', refundCents: 168, currency: 'ILS' };
  assert.deepEqual(first, expected);
  assert.deepEqual(second, expected);
  assert.notStrictEqual(first, second);
  first.refundCents = 0;
  assert.deepEqual(returnOrder(order, context), expected);
  assert.deepEqual({ order, context }, before);
});

returns.mjs.text:
// Return eligibility policy.

export function canReturn(order, { nowDay }) {
  if (order.status !== 'delivered') {
    return { eligible: false, reason: 'status' };
  }

  const deliveredDay = order.deliveredDay;
  if (!Number.isInteger(deliveredDay) || deliveredDay < 0 ||
      !Number.isInteger(nowDay) || nowDay < 0 || nowDay < deliveredDay) {
    return { eligible: false, reason: 'date' };
  }

  if (nowDay - deliveredDay > 12) {
    return { eligible: false, reason: 'window' };
  }

  return { eligible: true, reason: 'eligible' };
}

