import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('returns reject non-delivered status before inspecting delivery dates', () => {
  for (const status of ['pending', 'shipped', 'returned', 'Delivered', '', null, undefined]) {
    const order = {
      status,
      get deliveredDay() { throw new Error('date must not be read'); },
    };
    assert.deepEqual(canReturn(order, { nowDay: -1 }), { eligible: false, reason: 'status' });
  }
});

test('returns reject non-integer or negative dates without coercion', () => {
  for (const date of [-1, 1.5, '1', null, undefined, NaN, Infinity, -Infinity, true]) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: date }, { nowDay: 100 }),
      { eligible: false, reason: 'date' });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: date }),
      { eligible: false, reason: 'date' });
  }
});

test('returns reject dates before delivery', () => {
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 20 }, { nowDay: 19 }),
    { eligible: false, reason: 'date' });
});

test('returns allow delivery day through day 12 inclusive and reject day 13 and later', () => {
  for (const deliveredDay of [0, 20]) {
    for (const elapsed of [0, 1, 9, 10, 11, 12]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay },
        { nowDay: deliveredDay + elapsed }), { eligible: true, reason: 'eligible' });
    }
    for (const elapsed of [13, 30]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay },
        { nowDay: deliveredDay + elapsed }), { eligible: false, reason: 'window' });
    }
  }
});

test('eligibility accepts frozen inputs and returns fresh exact-shaped results', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 5, extra: 'ignored' });
  const context = Object.freeze({ nowDay: 15 });
  const first = canReturn(order, context);
  const second = canReturn(order, context);
  assert.deepEqual(first, { eligible: true, reason: 'eligible' });
  assert.deepEqual(second, first);
  assert.notStrictEqual(first, second);
  first.eligible = false;
  assert.deepEqual(canReturn(order, context), { eligible: true, reason: 'eligible' });
  assert.deepEqual(order, { status: 'delivered', deliveredDay: 5, extra: 'ignored' });
  assert.deepEqual(context, { nowDay: 15 });
});

