import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as cartModule from './cart.mjs';
import * as inventoryModule from './inventory.mjs';
import * as returnsModule from './returns.mjs';
import * as receiptModule from './receipt.mjs';
import * as pipelineModule from './pipeline.mjs';
import * as summaryModule from './summary.mjs';

test('audit: pricing matches an independent integer oracle across rounding boundaries', () => {
  for (let subtotal = 0; subtotal <= 250; subtotal++) {
    for (const [couponPercent, basisPoints] of [
      [-10, 0], [0, 0], [12.5, 1250], [34.9, 3490], [35, 3500], [90, 3500],
    ]) {
      const discount = Math.floor((subtotal * basisPoints + 5000) / 10000);
      const tax = Math.floor(((subtotal - discount) * 9 + 50) / 100);
      const cart = Object.freeze([
        Object.freeze({ sku: ' first ', quantity: 1, unitPriceCents: Math.floor(subtotal / 2) }),
        Object.freeze({ sku: 'second', quantity: 1, unitPriceCents: Math.ceil(subtotal / 2) }),
        null,
      ]);
      for (const shipping of [0, 17]) {
        assert.deepEqual(cartModule.priceOrder(cart,
          Object.freeze({ couponPercent, shippingCents: shipping })), {
          subtotalCents: subtotal, discountCents: discount, taxCents: tax,
          shippingCents: shipping, totalCents: subtotal - discount + tax + shipping,
        });
      }
    }
  }
});

test('audit: inventory aggregation and atomic failure hold across stock boundaries', () => {
  for (let available = 0; available <= 8; available++) {
    for (let first = 1; first <= 4; first++) {
      for (let second = 1; second <= 4; second++) {
        const stock = Object.freeze({ before: 2, a: available, untouched: 7 });
        const cart = Object.freeze([
          Object.freeze({ sku: 'before', quantity: 1, unitPriceCents: 0 }),
          Object.freeze({ sku: ' a ', quantity: first, unitPriceCents: 3 }),
          Object.freeze({ sku: 'a', quantity: second, unitPriceCents: 5 }),
        ]);
        if (first + second > available) {
          assert.throws(() => inventoryModule.reserveInventory(stock, cart),
            { name: 'RangeError', message: 'insufficient stock' });
        } else {
          const result = inventoryModule.reserveInventory(stock, cart);
          assert.deepEqual(result, { before: 1, a: available - first - second, untouched: 7 });
          assert.notStrictEqual(result, stock);
        }
        assert.deepEqual(stock, { before: 2, a: available, untouched: 7 });
      }
    }
  }
});

test('audit: eligibility and refunds match the inclusive window and rejection precedence', () => {
  for (const status of ['delivered', 'pending']) {
    for (let deliveredDay = -1; deliveredDay <= 15; deliveredDay++) {
      for (let nowDay = -1; nowDay <= 30; nowDay++) {
        const reason = status !== 'delivered' ? 'status'
          : deliveredDay < 0 || nowDay < 0 || nowDay < deliveredDay ? 'date'
          : nowDay - deliveredDay > 12 ? 'window' : 'eligible';
        const eligible = reason === 'eligible';
        const order = Object.freeze({
          status, deliveredDay,
          cart: Object.freeze([Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 94 })]),
          options: Object.freeze({ couponPercent: 34.9, shippingCents: 7 }),
        });
        const context = Object.freeze({ nowDay });
        assert.deepEqual(returnsModule.canReturn(order, context), { eligible, reason });
        assert.deepEqual(pipelineModule.returnOrder(order, context), {
          eligible, reason, refundCents: eligible ? 73 : 0, currency: 'ILS',
        });
      }
    }
  }
});

test('audit: all nine exports compose with exact shapes, unusual SKUs and escaped CSV', () => {
  for (const [module, exports] of [
    [cartModule, ['normalizeCart', 'priceOrder']],
    [inventoryModule, ['reserveInventory']], [returnsModule, ['canReturn']],
    [receiptModule, ['buildReceipt', 'renderCSV']],
    [pipelineModule, ['fulfillOrder', 'returnOrder']], [summaryModule, ['formatSummary']],
  ]) {
    assert.deepEqual(Object.keys(module).sort(), exports.sort());
    for (const name of exports) assert.equal(typeof module[name], 'function');
  }
  const cart = Object.freeze([
    Object.freeze({ sku: ' __proto__ ', quantity: 1, unitPriceCents: 10, ignored: true }),
    Object.freeze({ sku: 'constructor', quantity: 1, unitPriceCents: 0 }),
    Object.freeze({ sku: '__proto__', quantity: 2, unitPriceCents: 10 }),
    Object.freeze({ sku: '__proto__', quantity: 1, unitPriceCents: 20 }),
    Object.freeze({ sku: ' ', quantity: 99, unitPriceCents: 100 }), null,
  ]);
  assert.deepEqual(cartModule.normalizeCart(cart), [
    { sku: '__proto__', quantity: 3, unitPriceCents: 10 },
    { sku: 'constructor', quantity: 1, unitPriceCents: 0 },
    { sku: '__proto__', quantity: 1, unitPriceCents: 20 },
  ]);
  const order = Object.freeze({ id: 'a,"b"\r\nc', cart,
    options: Object.freeze({ couponPercent: 35, shippingCents: 7 }) });
  const stock = Object.freeze({ ['__proto__']: 4, constructor: 2 });
  const receipt = { orderId: order.id, subtotalCents: 50, discountCents: 18,
    taxCents: 3, shippingCents: 7, totalCents: 42, itemCount: 5, currency: 'ILS' };
  assert.deepEqual(receiptModule.buildReceipt(order), receipt);
  assert.deepEqual(pipelineModule.fulfillOrder(order, stock), {
    receipt, stock: { ['__proto__']: 0, constructor: 1 },
  });
  const receipts = Object.freeze([Object.freeze(receipt),
    Object.freeze(receiptModule.buildReceipt({ id: 'empty', cart: [] }))]);
  assert.equal(receiptModule.renderCSV(receipts),
    'orderId,totalCents,currency\r\n"a,""b""\r\nc",42,ILS\r\nempty,0,ILS');
  assert.deepEqual(summaryModule.formatSummary(receipts), { orders: 2, totalCents: 42, units: 5 });
});

