import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('integrated fulfillment, receipts and returns share the release policy', () => {
  const order = Object.freeze({
    id: 'paid,"1"\nnext', status: 'delivered', deliveredDay: 20,
    cart: Object.freeze([
      null,
      Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 94 }),
      Object.freeze({ sku: 'invalid', quantity: 0, unitPriceCents: 1000 }),
    ]),
    options: Object.freeze({ couponPercent: 99, shippingCents: 25 }),
  });
  const stock = Object.freeze({ a: 3, untouched: 9 });
  const before = structuredClone({ order, stock });
  const fulfilled = fulfillOrder(order, stock);
  assert.deepEqual(fulfilled, {
    receipt: {
      orderId: order.id, subtotalCents: 296, discountCents: 104, taxCents: 17,
      shippingCents: 25, totalCents: 234, itemCount: 3, currency: 'ILS',
    },
    stock: { a: 0, untouched: 9 },
  });
  assert.deepEqual(returnOrder(order, Object.freeze({ nowDay: 32 })), {
    eligible: true, reason: 'eligible', refundCents: fulfilled.receipt.totalCents,
    currency: fulfilled.receipt.currency,
  });
  assert.deepEqual(returnOrder(order, { nowDay: 33 }), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'ILS',
  });
  const empty = fulfillOrder({ id: 'empty', cart: [] }, fulfilled.stock);
  const receipts = Object.freeze([
    Object.freeze(fulfilled.receipt), Object.freeze(empty.receipt),
  ]);
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\n"paid,""1""\nnext",234,ILS\r\nempty,0,ILS');
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 234, units: 3 });
  assert.throws(() => fulfillOrder(order, fulfilled.stock),
    { name: 'RangeError', message: 'insufficient stock' });
  assert.deepEqual(fulfilled.stock, { a: 0, untouched: 9 });
  assert.deepEqual({ order, stock }, before);
});

