import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reserveInventory } from './inventory.mjs';

test('empty and invalid carts return fresh stock without changing counts', () => {
  const stock = Object.freeze({ a: 3, unused: 0 });
  const cart = Object.freeze([
    null,
    Object.freeze({ sku: ' ', quantity: 1, unitPriceCents: 1 }),
    Object.freeze({ sku: 'absent', quantity: 0, unitPriceCents: 1 }),
    Object.freeze({ sku: 'absent', quantity: 1, unitPriceCents: -1 }),
    Object.freeze({ sku: 'absent', quantity: 1.5, unitPriceCents: 1 }),
  ]);
  for (const input of [[], cart]) {
    const result = reserveInventory(stock, input);
    assert.deepEqual(result, { a: 3, unused: 0 });
    assert.notStrictEqual(result, stock);
  }
  assert.deepEqual(reserveInventory({}, []), {});
});

test('reservation trims and aggregates a sku across duplicate and distinct prices', () => {
  const stock = Object.freeze({ a: 6, free: 3, unused: 7 });
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'free', quantity: 1, unitPriceCents: 0 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 200 }),
  ]);
  const before = structuredClone(cart);
  const result = reserveInventory(stock, cart);
  assert.deepEqual(result, { a: 0, free: 2, unused: 7 });
  assert.notStrictEqual(result, stock);
  result.unused = 0;
  assert.deepEqual(stock, { a: 6, free: 3, unused: 7 });
  assert.deepEqual(cart, before);
});

test('shortages across prices throw the exact error without partially reserving earlier skus', () => {
  const stock = Object.freeze({ first: 3, a: 4 });
  const cart = Object.freeze([
    Object.freeze({ sku: 'first', quantity: 2, unitPriceCents: 10 }),
    Object.freeze({ sku: 'a', quantity: 3, unitPriceCents: 100 }),
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 200 }),
  ]);
  const before = structuredClone(cart);
  assert.throws(() => reserveInventory(stock, cart),
    { name: 'RangeError', message: 'insufficient stock' });
  assert.deepEqual(stock, { first: 3, a: 4 });
  assert.deepEqual(cart, before);
});

test('missing and zero-count skus fail atomically even when another sku is available', () => {
  for (const sku of ['missing', 'zero']) {
    const stock = { first: 3, zero: 0 };
    const cart = [{ sku: 'first', quantity: 1, unitPriceCents: 10 },
      { sku, quantity: 1, unitPriceCents: 0 }];
    const before = structuredClone({ stock, cart });
    assert.throws(() => reserveInventory(stock, cart),
      { name: 'RangeError', message: 'insufficient stock' });
    assert.deepEqual({ stock, cart }, before);
  }
});

test('prototype-like skus are ordinary own stock keys and inherited keys are absent', () => {
  const stock = Object.freeze({ ['__proto__']: 2, constructor: 3, toString: 1 });
  const cart = ['__proto__', 'constructor', 'toString'].map(sku =>
    ({ sku, quantity: 1, unitPriceCents: 0 }));
  const result = reserveInventory(stock, cart);
  assert.deepEqual(result, { ['__proto__']: 1, constructor: 2, toString: 0 });
  assert.strictEqual(Object.getPrototypeOf(result), Object.prototype);
  for (const sku of ['__proto__', 'constructor', 'toString', 'inherited']) {
    const inheritedStock = Object.create({ inherited: 10 });
    assert.throws(() => reserveInventory(inheritedStock,
      [{ sku, quantity: 1, unitPriceCents: 0 }]),
    { name: 'RangeError', message: 'insufficient stock' });
  }
});

