import { test } from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder } from './cart.mjs';

test('prices normalized lines with default coupon and shipping', () => {
  assert.deepEqual(priceOrder([
    { sku: ' a ', quantity: 2, unitPriceCents: 101 },
    { sku: 'a', quantity: 1, unitPriceCents: 101 },
    { sku: 'a', quantity: 1, unitPriceCents: 102 },
    { sku: 'free', quantity: 2, unitPriceCents: 0 },
    null,
    { sku: 'bad', quantity: -1, unitPriceCents: 1000 },
    { sku: ' ', quantity: 1, unitPriceCents: 1000 },
  ]), {
    subtotalCents: 405, discountCents: 0, taxCents: 36,
    shippingCents: 0, totalCents: 441,
  });
});

test('clamps coupons to the revised range from zero to 35 percent', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  for (const couponPercent of [35, 36, 100]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 1000, discountCents: 350, taxCents: 59,
      shippingCents: 0, totalCents: 709,
    });
  }
  for (const couponPercent of [-5, 0]) {
    assert.deepEqual(priceOrder(cart, { couponPercent }), {
      subtotalCents: 1000, discountCents: 0, taxCents: 90,
      shippingCents: 0, totalCents: 1090,
    });
  }
});

test('taxes the discounted subtotal at 9 percent and excludes shipping', () => {
  const cart = [{ sku: 'a', quantity: 1, unitPriceCents: 1000 }];
  assert.deepEqual(priceOrder(cart, { couponPercent: 20, shippingCents: 199 }), {
    subtotalCents: 1000, discountCents: 200, taxCents: 72,
    shippingCents: 199, totalCents: 1071,
  });
});

test('rounds discount and tax once per order, including fractional coupons', () => {
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 1 },
    { sku: 'b', quantity: 1, unitPriceCents: 1 },
  ], { couponPercent: 35 }), {
    subtotalCents: 2, discountCents: 1, taxCents: 0,
    shippingCents: 0, totalCents: 1,
  });
  assert.deepEqual(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 101 },
  ], { couponPercent: 12.5 }), {
    subtotalCents: 101, discountCents: 13, taxCents: 8,
    shippingCents: 0, totalCents: 96,
  });
  assert.equal(priceOrder([
    { sku: 'a', quantity: 1, unitPriceCents: 5 },
    { sku: 'b', quantity: 1, unitPriceCents: 5 },
  ]).taxCents, 1);
});

test('handles empty and entirely invalid carts, retaining shipping', () => {
  assert.deepEqual(priceOrder([]), {
    subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0,
  });
  assert.deepEqual(priceOrder([null, {}], { couponPercent: 35, shippingCents: 123 }), {
    subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 123, totalCents: 123,
  });
});

test('leaves frozen cart and options unchanged and returns fresh results', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 100 }),
  ]);
  const options = Object.freeze({ couponPercent: 20, shippingCents: 5 });
  const before = structuredClone({ cart, options });
  const result = priceOrder(cart, options);
  assert.deepEqual(result, {
    subtotalCents: 300, discountCents: 60, taxCents: 22,
    shippingCents: 5, totalCents: 267,
  });
  const next = priceOrder(cart, options);
  assert.notStrictEqual(result, next);
  result.totalCents = 0;
  assert.equal(next.totalCents, 267);
  assert.deepEqual({ cart, options }, before);
});

