import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fulfillOrder } from './pipeline.mjs';

test('fulfillment combines current receipt pricing and reservation without mutating frozen inputs', () => {
  const order = Object.freeze({
    id: 'order-1',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 102 }),
      Object.freeze({ sku: 'free', quantity: 2, unitPriceCents: 0 }),
      null,
      Object.freeze({ sku: 'bad', quantity: -1, unitPriceCents: 1000 }),
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 199 }),
    status: 'pending',
  });
  const stock = Object.freeze({ a: 5, free: 2, unrelated: 8 });
  const before = structuredClone({ order, stock });
  const result = fulfillOrder(order, stock);
  assert.deepEqual(result, {
    receipt: {
      orderId: 'order-1', subtotalCents: 405, discountCents: 142,
      taxCents: 24, shippingCents: 199, totalCents: 486,
      itemCount: 6, currency: 'USD',
    },
    stock: { a: 1, free: 0, unrelated: 8 },
  });
  const next = fulfillOrder(order, stock);
  assert.notStrictEqual(result, next);
  assert.notStrictEqual(result.receipt, next.receipt);
  assert.notStrictEqual(result.stock, next.stock);
  result.stock.a = 0;
  result.receipt.totalCents = 0;
  assert.equal(next.stock.a, 1);
  assert.equal(next.receipt.totalCents, 486);
  assert.deepEqual({ order, stock }, before);
});

test('fulfillment propagates insufficient stock without changing order or stock', () => {
  const order = {
    id: 'short',
    cart: [
      { sku: 'first', quantity: 1, unitPriceCents: 100 },
      { sku: 'a', quantity: 2, unitPriceCents: 100 },
      { sku: 'a', quantity: 2, unitPriceCents: 200 },
    ],
    options: { couponPercent: 20 },
  };
  const stock = { first: 2, a: 3 };
  const before = structuredClone({ order, stock });
  assert.throws(() => fulfillOrder(order, stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ order, stock }, before);
});

test('fulfillment handles empty and invalid carts with default options', () => {
  const stock = { unrelated: 2 };
  for (const cart of [[], [null, {}]]) {
    const result = fulfillOrder({ id: 'empty', cart }, stock);
    assert.deepEqual(result, {
      receipt: {
        orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
        shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'USD',
      },
      stock: { unrelated: 2 },
    });
    assert.notStrictEqual(result.stock, stock);
  }
});

inventory.mjs.text:
// Atomic reservation adapter.

import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const required = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    required.set(sku, (required.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of required) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of required) {
    reserved[sku] -= quantity;
  }
  return reserved;
}

