import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart } from './cart.mjs';

test('drops invalid lines and accepts zero prices', () => {
  const valid = { sku: ' free ', quantity: 1, unitPriceCents: 0 };
  const invalid = [null, undefined, {}, 5, 'line',
    { ...valid, sku: '' }, { ...valid, sku: ' \t\n ' }, { ...valid, sku: 1 }];
  for (const quantity of [0, -1, 1.5, NaN, Infinity, '2', null, undefined]) {
    invalid.push({ ...valid, quantity });
  }
  for (const unitPriceCents of [-1, 1.5, NaN, Infinity, '0', null, undefined]) {
    invalid.push({ ...valid, unitPriceCents });
  }
  assert.deepEqual(normalizeCart([...invalid, valid]), [
    { sku: 'free', quantity: 1, unitPriceCents: 0 },
  ]);
});

test('merges only matching trimmed sku and price in first appearance order', () => {
  assert.deepEqual(normalizeCart([
    { sku: ' a ', quantity: 2, unitPriceCents: 101 },
    { sku: 'b', quantity: 1, unitPriceCents: 5 },
    { sku: 'a', quantity: 3, unitPriceCents: 102 },
    { sku: '\ta\n', quantity: 4, unitPriceCents: 101 },
    { sku: 'A', quantity: 1, unitPriceCents: 101 },
    { sku: 'b', quantity: 2, unitPriceCents: 5 },
  ]), [
    { sku: 'a', quantity: 6, unitPriceCents: 101 },
    { sku: 'b', quantity: 3, unitPriceCents: 5 },
    { sku: 'a', quantity: 3, unitPriceCents: 102 },
    { sku: 'A', quantity: 1, unitPriceCents: 101 },
  ]);
});

test('returns fresh plain objects and leaves frozen inputs unchanged', () => {
  const cart = Object.freeze([
    Object.freeze({ sku: ' x ', quantity: 1, unitPriceCents: 10, extra: 'ignored' }),
    Object.freeze({ sku: 'x', quantity: 2, unitPriceCents: 10 }),
    null,
  ]);
  const before = structuredClone(cart);
  const result = normalizeCart(cart);
  assert.deepEqual(result, [{ sku: 'x', quantity: 3, unitPriceCents: 10 }]);
  assert.notStrictEqual(result, cart);
  assert.notStrictEqual(result[0], cart[0]);
  assert.equal(Object.getPrototypeOf(result[0]), Object.prototype);
  result[0].quantity = 20;
  assert.deepEqual(cart, before);
  assert.deepEqual(normalizeCart(cart), [{ sku: 'x', quantity: 3, unitPriceCents: 10 }]);
});

test('treats prototype names and punctuation as ordinary sku values', () => {
  assert.deepEqual(normalizeCart([
    { sku: '__proto__', quantity: 1, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: ' __proto__ ', quantity: 3, unitPriceCents: 0 },
    { sku: 'a:1', quantity: 1, unitPriceCents: 2 },
    { sku: 'a', quantity: 1, unitPriceCents: 12 },
  ]), [
    { sku: '__proto__', quantity: 4, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: 'a:1', quantity: 1, unitPriceCents: 2 },
    { sku: 'a', quantity: 1, unitPriceCents: 12 },
  ]);
});

