receipt.mjs.text:
// Receipt and CSV adapters.

import { normalizeCart, priceOrder } from './cart.mjs';

export function buildReceipt(order) {
  const itemCount = normalizeCart(order.cart).reduce(
    (sum, { quantity }) => sum + quantity,
    0,
  );

  return {
    orderId: order.id,
    ...priceOrder(order.cart, order.options),
    itemCount,
    currency: 'USD',
  };
}

function csvField(value) {
  const text = String(value);
  return /[,"\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function renderCSV(receipts) {
  const records = ['orderId,totalCents,currency'];
  for (const { orderId, totalCents, currency } of receipts) {
    records.push([orderId, totalCents, currency].map(csvField).join(','));
  }
  return records.join('\n');
}

