import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canReturn } from './returns.mjs';

test('requires exact delivered status before checking invalid dates or the window', () => {
  for (const status of [undefined, null, '', 'pending', 'returned', 'Delivered']) {
    for (const [deliveredDay, nowDay] of [[undefined, -1], [0, 11], [0, 0]]) {
      assert.deepEqual(canReturn({ status, deliveredDay }, { nowDay }), {
        eligible: false, reason: 'status',
      });
    }
  }
});

test('requires nonnegative integer dates without coercion', () => {
  const invalidDays = [undefined, null, -1, 0.5, '0', NaN, Infinity, -Infinity, true];
  for (const day of invalidDays) {
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: day }, { nowDay: 20 }), {
      eligible: false, reason: 'date',
    });
    assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 0 }, { nowDay: day }), {
      eligible: false, reason: 'date',
    });
  }
  assert.deepEqual(canReturn({ status: 'delivered' }, {}), {
    eligible: false, reason: 'date',
  });
});

test('rejects dates before delivery and accepts the inclusive 10-day window', () => {
  assert.deepEqual(canReturn({ status: 'delivered', deliveredDay: 20 }, { nowDay: 19 }), {
    eligible: false, reason: 'date',
  });
  for (const deliveredDay of [0, 20]) {
    for (const elapsed of [0, 1, 9, 10]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, {
        nowDay: deliveredDay + elapsed,
      }), { eligible: true, reason: 'eligible' });
    }
    for (const elapsed of [11, 12, 100]) {
      assert.deepEqual(canReturn({ status: 'delivered', deliveredDay }, {
        nowDay: deliveredDay + elapsed,
      }), { eligible: false, reason: 'window' });
    }
  }
});

test('eligibility leaves frozen inputs unchanged and returns fresh results', () => {
  const order = Object.freeze({ status: 'delivered', deliveredDay: 2 });
  const context = Object.freeze({ nowDay: 12 });
  const before = structuredClone({ order, context });
  const result = canReturn(order, context);
  const next = canReturn(order, context);
  assert.notStrictEqual(result, next);
  result.eligible = false;
  assert.deepEqual(next, { eligible: true, reason: 'eligible' });
  assert.deepEqual({ order, context }, before);
});

