import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart, priceOrder } from './cart.mjs';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { reserveInventory } from './inventory.mjs';
import { canReturn } from './returns.mjs';
import { fulfillOrder, returnOrder } from './pipeline.mjs';
import { formatSummary } from './summary.mjs';

test('release adapters agree on fulfilled receipts, exports, summaries, and refunds', () => {
  const order = Object.freeze({
    id: 'first,"order"\nline', status: 'delivered', deliveredDay: 2,
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 101 }),
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 102 }),
      null,
    ]),
    options: Object.freeze({ couponPercent: 100, shippingCents: 199 }),
  });
  const secondOrder = Object.freeze({
    id: 'second', status: 'delivered', deliveredDay: 0,
    cart: Object.freeze([
      Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 1 }),
      Object.freeze({ sku: 'b', quantity: 1, unitPriceCents: 1 }),
    ]),
    options: Object.freeze({ couponPercent: 35 }),
  });
  const stock = Object.freeze({ a: 5, b: 1, unrelated: 7 });
  const before = structuredClone({ order, secondOrder, stock });
  const first = fulfillOrder(order, stock);
  const second = fulfillOrder(secondOrder, Object.freeze(first.stock));
  const receipts = Object.freeze([
    Object.freeze(first.receipt), Object.freeze(second.receipt),
  ]);

  assert.deepEqual(normalizeCart(order.cart), [
    { sku: 'a', quantity: 3, unitPriceCents: 101 },
    { sku: 'a', quantity: 1, unitPriceCents: 102 },
  ]);
  assert.deepEqual(priceOrder(order.cart, order.options), {
    subtotalCents: 405, discountCents: 142, taxCents: 24,
    shippingCents: 199, totalCents: 486,
  });
  assert.deepEqual(first.receipt, buildReceipt(order));
  assert.deepEqual(first.stock, reserveInventory(stock, order.cart));
  assert.deepEqual(second.stock, { a: 0, b: 0, unrelated: 7 });
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\n"first,""order""\nline",486,ILS\r\nsecond,1,ILS');
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 487, units: 6 });

  assert.deepEqual(canReturn(order, { nowDay: 14 }), {
    eligible: true, reason: 'eligible',
  });
  assert.deepEqual(returnOrder(order, { nowDay: 14 }), {
    eligible: true, reason: 'eligible', refundCents: first.receipt.totalCents,
    currency: first.receipt.currency,
  });
  for (const nowDay of [10, 11, 12]) {
    assert.deepEqual(returnOrder(secondOrder, { nowDay }), {
      eligible: true, reason: 'eligible', refundCents: second.receipt.totalCents,
      currency: second.receipt.currency,
    });
  }
  assert.deepEqual(returnOrder(order, { nowDay: 15 }), {
    eligible: false, reason: 'window', refundCents: 0, currency: 'ILS',
  });
  assert.throws(() => fulfillOrder(secondOrder, second.stock), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual(second.stock, { a: 0, b: 0, unrelated: 7 });
  assert.deepEqual({ order, secondOrder, stock }, before);
});

inventory.mjs.text:
// Atomic reservation adapter.

import { normalizeCart } from './cart.mjs';

export function reserveInventory(stock, cart) {
  const required = new Map();
  for (const { sku, quantity } of normalizeCart(cart)) {
    required.set(sku, (required.get(sku) ?? 0) + quantity);
  }

  for (const [sku, quantity] of required) {
    const available = Object.hasOwn(stock, sku) ? stock[sku] : 0;
    if (available < quantity) throw new RangeError('insufficient stock');
  }

  const reserved = { ...stock };
  for (const [sku, quantity] of required) {
    reserved[sku] -= quantity;
  }
  return reserved;
}

