import { reserveInventory } from './inventory.mjs';

test('reservation aggregates trimmed sku quantities across prices and retains unrelated stock', () => {
  assert.deepEqual(reserveInventory({ a: 10, b: 2, unrelated: 7 }, [
    { sku: ' a ', quantity: 2, unitPriceCents: 100 },
    { sku: 'b', quantity: 2, unitPriceCents: 0 },
    { sku: 'a', quantity: 3, unitPriceCents: 200 },
    { sku: 'a', quantity: 1, unitPriceCents: 100 },
