test('reservation rejects combined demand even when each price group fits', () => {
  const stock = { a: 4 };
  const cart = [
    { sku: 'a', quantity: 2, unitPriceCents: 100 },
    { sku: 'a', quantity: 3, unitPriceCents: 200 },
  ];
  const before = structuredClone({ stock, cart });
  assert.throws(() => reserveInventory(stock, cart), {
    name: 'RangeError', message: 'insufficient stock',
  });
  assert.deepEqual({ stock, cart }, before);
});

test('reservation is atomic when a later sku is absent or insufficient', () => {
  for (const stock of [{ a: 5 }, { a: 5, b: 0 }, { a: 5, b: 1 }]) {
    const cart = [
      { sku: 'a', quantity: 2, unitPriceCents: 100 },
      { sku: 'b', quantity: 2, unitPriceCents: 200 },
    ];
    const before = structuredClone({ stock, cart });
    assert.throws(() => reserveInventory(stock, cart), {
      name: 'RangeError', message: 'insufficient stock',
    });
    assert.deepEqual({ stock, cart }, before);
  }
});

test('empty and invalid carts return a fresh stock copy without reserving anything', () => {
  const stock = Object.freeze({ a: 2 });
  for (const cart of [[], [null, {},
    { sku: 'missing', quantity: 0, unitPriceCents: 1 },
    { sku: 'missing', quantity: 1, unitPriceCents: -1 },
    { sku: ' ', quantity: 1, unitPriceCents: 0 },
  ]]) {
    const reserved = reserveInventory(stock, cart);
    assert.deepEqual(reserved, { a: 2 });
    assert.notStrictEqual(reserved, stock);
  }
});

test('reservation leaves frozen inputs unchanged and returns independent results', () => {
  const stock = Object.freeze({ a: 5, unrelated: 1 });
  const cart = Object.freeze([
    Object.freeze({ sku: ' a ', quantity: 2, unitPriceCents: 100 }),
    Object.freeze({ sku: 'a', quantity: 1, unitPriceCents: 200 }),
  ]);
  const before = structuredClone({ stock, cart });
  const first = reserveInventory(stock, cart);
  const second = reserveInventory(stock, cart);
  assert.deepEqual(first, { a: 2, unrelated: 1 });
  assert.notStrictEqual(first, second);
  first.a = 0;
  assert.equal(second.a, 2);
  assert.deepEqual({ stock, cart }, before);
});

test('prototype names are ordinary sku keys and inherited properties are absent stock', () => {
  const stock = Object.freeze(JSON.parse('{"__proto__":3,"constructor":2,"toString":1}'));
  const cart = [
    { sku: '__proto__', quantity: 2, unitPriceCents: 0 },
    { sku: 'constructor', quantity: 2, unitPriceCents: 0 },
    { sku: 'toString', quantity: 1, unitPriceCents: 0 },
  ];
  const reserved = reserveInventory(stock, cart);
  assert.deepEqual(reserved, JSON.parse('{"__proto__":1,"constructor":0,"toString":0}'));
  assert.equal(Object.getPrototypeOf(reserved), Object.prototype);
  for (const sku of ['__proto__', 'constructor', 'toString']) {
    assert.throws(() => reserveInventory({}, [{ sku, quantity: 1, unitPriceCents: 0 }]), {
      name: 'RangeError', message: 'insufficient stock',
    });
  }
  assert.throws(() => reserveInventory(Object.create({ inherited: 10 }), [
    { sku: 'inherited', quantity: 1, unitPriceCents: 0 },
  ]), { name: 'RangeError', message: 'insufficient stock' });
});

