import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildReceipt, renderCSV } from './receipt.mjs';
import { formatSummary } from './summary.mjs';

test('builds exactly the receipt fields using normalized quantities and current pricing', () => {
  assert.deepEqual(buildReceipt({
    id: 'order-1',
    cart: [
      { sku: ' a ', quantity: 2, unitPriceCents: 101 },
      { sku: 'a', quantity: 1, unitPriceCents: 101 },
      { sku: 'a', quantity: 1, unitPriceCents: 102 },
      { sku: 'free', quantity: 2, unitPriceCents: 0 },
      null,
      { sku: 'bad', quantity: -1, unitPriceCents: 1000 },
      { sku: ' ', quantity: 20, unitPriceCents: 1000 },
    ],
    options: { couponPercent: 100, shippingCents: 199 },
    status: 'delivered',
    deliveredDay: 2,
    currency: 'EUR',
  }), {
    orderId: 'order-1', subtotalCents: 405, discountCents: 142,
    taxCents: 24, shippingCents: 199, totalCents: 486,
    itemCount: 6, currency: 'ILS',
  });
});

test('receipts preserve order-level discount rounding', () => {
  assert.deepEqual(buildReceipt({
    id: 0,
    cart: [
      { sku: 'a', quantity: 1, unitPriceCents: 1 },
      { sku: 'b', quantity: 1, unitPriceCents: 1 },
    ],
    options: { couponPercent: 35 },
  }), {
    orderId: 0, subtotalCents: 2, discountCents: 1, taxCents: 0,
    shippingCents: 0, totalCents: 1, itemCount: 2, currency: 'ILS',
  });
});

test('receipts handle empty and invalid carts with default options and shipping', () => {
  assert.deepEqual(buildReceipt({ id: 'empty', cart: [] }), {
    orderId: 'empty', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 0, totalCents: 0, itemCount: 0, currency: 'ILS',
  });
  assert.deepEqual(buildReceipt({
    id: 'invalid', cart: [null, {}], options: { shippingCents: 123 },
  }), {
    orderId: 'invalid', subtotalCents: 0, discountCents: 0, taxCents: 0,
    shippingCents: 123, totalCents: 123, itemCount: 0, currency: 'ILS',
  });
});

test('buildReceipt leaves frozen orders unchanged and returns independent receipts', () => {
  const order = Object.freeze({
    id: 'frozen',
    cart: Object.freeze([
      Object.freeze({ sku: ' a ', quantity: 1, unitPriceCents: 100 }),
      Object.freeze({ sku: 'a', quantity: 2, unitPriceCents: 100 }),
    ]),
    options: Object.freeze({ couponPercent: 20, shippingCents: 5 }),
  });
  const before = structuredClone(order);
  const receipt = buildReceipt(order);
  const next = buildReceipt(order);
  assert.notStrictEqual(receipt, next);
  receipt.totalCents = 0;
  receipt.itemCount = 0;
  assert.equal(next.totalCents, 267);
  assert.equal(next.itemCount, 3);
  assert.deepEqual(order, before);
});

test('empty CSV contains only the exact header', () => {
  assert.equal(renderCSV([]), 'orderId,totalCents,currency');
});

test('CSV preserves input order and repeated IDs, converts numbers, and uses CRLF without a trailing newline', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'z', totalCents: 109, currency: 'ILS', itemCount: 1 }),
    Object.freeze({ orderId: 0, totalCents: 0, currency: 'ILS', itemCount: 0 }),
    Object.freeze({ orderId: 'z', totalCents: 2, currency: 'ILS', itemCount: 2 }),
    Object.freeze({ orderId: '', totalCents: 3, currency: 'ILS' }),
  ]);
  const before = structuredClone(receipts);
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\nz,109,ILS\r\n0,0,ILS\r\nz,2,ILS\r\n,3,ILS');
  assert.deepEqual(receipts, before);
});

test('CSV quotes commas, quotes, LF, CR, and CRLF while preserving field contents', () => {
  const ids = ['a,b', 'say "hi"', 'a\nb', 'a\rb', 'a\r\nb', 'a,"b"\nc'];
  const expected = ['"a,b"', '"say ""hi"""', '"a\nb"', '"a\rb"', '"a\r\nb"', '"a,""b""\nc"'];
  for (let index = 0; index < ids.length; index += 1) {
    assert.equal(renderCSV([{ orderId: ids[index], totalCents: 1, currency: 'ILS' }]),
      `orderId,totalCents,currency\r\n${expected[index]},1,ILS`);
  }
  assert.equal(renderCSV([{ orderId: 'plain', totalCents: 1, currency: 'U,S"D' }]),
    'orderId,totalCents,currency\r\nplain,1,"U,S""D"');
});

test('built receipts feed CSV and the existing summary adapter', () => {
  const receipts = [
    buildReceipt({ id: 'first,order', cart: [{ sku: 'a', quantity: 2, unitPriceCents: 100 }] }),
    buildReceipt({ id: 'second', cart: [], options: { shippingCents: 5 } }),
  ];
  assert.equal(renderCSV(receipts),
    'orderId,totalCents,currency\r\n"first,order",218,ILS\r\nsecond,5,ILS');
  assert.deepEqual(formatSummary(receipts), { orders: 2, totalCents: 223, units: 2 });
});

