summary.mjs.text:
// Summary adapter.

export function formatSummary(receipts) {
  let totalCents = 0;
  let units = 0;

  for (const receipt of receipts) {
    totalCents += receipt.totalCents;
    units += receipt.itemCount;
  }

  return { orders: receipts.length, totalCents, units };
}

summary.test.mjs.text:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatSummary } from './summary.mjs';

test('summarizes empty receipts with zero totals', () => {
  assert.deepEqual(formatSummary([]), { orders: 0, totalCents: 0, units: 0 });
});

test('counts every receipt and sums totals and units without mutating inputs', () => {
  const receipts = Object.freeze([
    Object.freeze({ orderId: 'a', totalCents: 1090, itemCount: 3, currency: 'ILS' }),
    Object.freeze({ orderId: 'a', totalCents: 215, itemCount: 2, currency: 'ILS' }),
    Object.freeze({ orderId: 'free', totalCents: 0, itemCount: 4, currency: 'ILS' }),
    Object.freeze({ orderId: 'empty', totalCents: 0, itemCount: 0, currency: 'ILS' }),
  ]);
  const before = structuredClone(receipts);

  assert.deepEqual(formatSummary(receipts), {
    orders: 4, totalCents: 1305, units: 9,
  });
  assert.deepEqual(receipts, before);
});
